INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('798891b1-4c6f-5c4c-a16f-e3022c9e3f49', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 10, 10, 'Then Joshua commanded the officers of the people, saying,'),
  ('c2053b38-7469-5ffa-ac0a-9996492f977c', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 11, 11, '"Pass through the midst of the camp, and command the people, saying, ''Prepare food; for within three days you are to pass over this Jordan, to go in to possess the land, which Yahweh your God gives you to possess it.''"'),
  ('7501e7af-2b09-5aed-a392-dd223c97d650', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 12, 12, 'Joshua spoke to the Reubenites, and to the Gadites, and to the half-tribe of Manasseh, saying,'),
  ('b1514469-124b-5ea7-af81-7d77614151aa', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 13, 13, '"Remember the word which Moses the servant of Yahweh commanded you, saying, ''Yahweh your God gives you rest, and will give you this land.'),
  ('4b7729e1-bbf3-53b1-a36d-e8c867c012e0', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 14, 14, 'Your wives, your little ones, and your livestock, shall live in the land which Moses gave you beyond the Jordan; but you shall pass over before your brothers armed, all the mighty men of valor, and shall help them'),
  ('c413203f-cede-5c5c-a800-eaa514bd8715', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 15, 15, 'until Yahweh has given your brothers rest, as he has given you, and they have also possessed the land which Yahweh your God gives them. Then you shall return to the land of your possession, and possess it, which Moses the servant of Yahweh gave you beyond the Jordan toward the sunrise.''"'),
  ('971cfefa-638e-5a7c-a161-c85345548c9a', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 16, 16, 'They answered Joshua, saying, "All that you have commanded us we will do, and wherever you send us we will go.'),
  ('001c20f4-19dd-5b8d-a287-b3ac565b4cea', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 17, 17, 'Just as we listened to Moses in all things, so will we listen to you. Only may Yahweh your God be with you, as he was with Moses.'),
  ('22fef327-1b8e-5f1f-a395-df2bc97db8cb', '5e51ec2d-171b-53a0-a93a-ae3d360a39f3', NULL, 18, 18, 'Whoever rebels against your commandment, and doesn''t listen to your words in all that you command him, he shall be put to death. Only be strong and courageous."'),
  ('7a8e9c49-809c-5ef2-a60f-5cd6387e714c', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 1, 1, 'Joshua the son of Nun secretly sent two men out of Shittim as spies, saying, "Go, view the land, including Jericho." They went and came into the house of a prostitute whose name was Rahab, and slept there.'),
  ('f8250641-9497-566e-a6d3-2292191e5a1e', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 2, 2, 'The king of Jericho was told, "Behold, men of the children of Israel came in here tonight to spy out the land."'),
  ('032a371d-a596-5b95-aa9f-5018f38d0c59', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 3, 3, 'The king of Jericho sent to Rahab, saying, "Bring out the men who have come to you, who have entered into your house; for they have come to spy out all the land."'),
  ('3f6ee7e0-c6ba-5da8-a550-cbf1ae62decc', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 4, 4, 'The woman took the two men and hid them. Then she said, "Yes, the men came to me, but I didn''t know where they came from.'),
  ('4f551e95-a3ab-50a4-a0f9-87d6b75d5394', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 5, 5, 'It happened about the time of the shutting of the gate, when it was dark, that the men went out. Where the men went, I don''t know. Pursue them quickly; for you will overtake them."'),
  ('d697460b-7472-508e-adf3-3497ea5e3468', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 6, 6, 'But she had brought them up to the roof, and hid them with the stalks of flax, which she had laid in order on the roof.'),
  ('78dd9002-c202-510e-a82d-fbc874176aa9', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 7, 7, 'The men pursued them the way to the Jordan to the fords: and as soon as those who pursued them had gone out, they shut the gate.'),
  ('1d14568f-a57f-5e39-aaf3-5c27c10112e3', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 8, 8, 'Before they had laid down, she came up to them on the roof;'),
  ('aa48b1f8-8fe9-5801-aa5d-9a5ddc1e2323', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 9, 9, 'and she said to the men, "I know that Yahweh has given you the land, and that the fear of you has fallen on us, and that all the inhabitants of the land melt away before you.'),
  ('a43e4ec4-819b-5cb7-a6b9-e64b74b5f1f8', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 10, 10, 'For we have heard how Yahweh dried up the water of the Red Sea before you, when you came out of Egypt; and what you did to the two kings of the Amorites, who were beyond the Jordan, to Sihon and to Og, whom you utterly destroyed.'),
  ('fb07e0a5-6369-5a88-ae2e-0fa7a9323a16', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 11, 11, 'As soon as we had heard it, our hearts melted, neither did there remain any more spirit in any man, because of you: for Yahweh your God, he is God in heaven above, and on earth beneath.'),
  ('a9f856fd-34fa-5e9c-a7b3-86b482629113', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 12, 12, 'Now therefore, please swear to me by Yahweh, since I have dealt kindly with you, that you also will deal kindly with my father''s house, and give me a true token;'),
  ('957e3762-345d-5f0d-a987-b80fd5638ae0', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 13, 13, 'and that you will save alive my father, my mother, my brothers, and my sisters, and all that they have, and will deliver our lives from death."'),
  ('c0119010-528f-56f4-a0e5-fb0ce16ab9f3', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 14, 14, 'The men said to her, "Our life for yours, if you don''t talk about this business of ours; and it shall be, when Yahweh gives us the land, that we will deal kindly and truly with you."'),
  ('2e0f028e-5dc6-5106-a905-ae8d52e7b633', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 15, 15, 'Then she let them down by a cord through the window; for her house was on the side of the wall, and she lived on the wall.'),
  ('74a08487-d080-5be3-a338-521f1e763d51', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 16, 16, 'She said to them, "Go to the mountain, lest the pursuers find you; and hide yourselves there three days, until the pursuers have returned. Afterward, you may go your way."'),
  ('ba67822c-c22f-5ada-a719-f001965f3cd4', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 17, 17, 'The men said to her, "We will be guiltless of this your oath which you have made us to swear.'),
  ('30b5b5a9-4668-58bd-a2fa-56282e714d92', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 18, 18, 'Behold, when we come into the land, you shall bind this line of scarlet thread in the window which you did let us down by. You shall gather to yourself into the house your father, your mother, your brothers, and all your father''s household.'),
  ('4fa0b012-7e92-575e-a634-2088b0333839', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 19, 19, 'It shall be that whoever goes out of the doors of your house into the street, his blood will be on his head, and we will be guiltless. Whoever is with you in the house, his blood shall be on our head, if any hand is on him.'),
  ('05fc208c-4b43-5ea7-a560-e7709abfda94', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 20, 20, 'But if you talk about this business of ours, then we shall be guiltless of your oath which you have made us to swear."'),
  ('c32286db-8eeb-5763-a354-a48b0de4eb3e', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 21, 21, 'She said, "According to your words, so be it." She sent them away, and they departed. She tied the scarlet line in the window.'),
  ('3746ebcc-c281-5df2-a001-c514c59607e1', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 22, 22, 'They went, and came to the mountain, and stayed there three days, until the pursuers had returned. The pursuers sought them throughout all the way, but didn''t find them.'),
  ('74dac662-903b-53d7-a96b-395b59d50c40', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 23, 23, 'Then the two men returned, descended from the mountain, passed over, and came to Joshua the son of Nun; and they told him all that had happened to them.'),
  ('3ffe2ad6-6f94-5483-a98e-46fbe6531fcc', '8420f9cd-8bb1-5293-a1b0-0ccd9ed75720', NULL, 24, 24, 'They said to Joshua, "Truly Yahweh has delivered into our hands all the land. Moreover, all the inhabitants of the land melt away before us."'),
  ('d617305f-d41f-5b14-ae5a-3f570ebc5251', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 1, 1, 'Joshua rose up early in the morning; and they moved from Shittim, and came to the Jordan, he and all the children of Israel. They lodged there before they passed over.'),
  ('f1b117e1-9c43-5e76-a138-15a2076dafea', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 2, 2, 'It happened after three days, that the officers went through the midst of the camp;'),
  ('97eb92ad-7eec-5d04-a9e8-d220f195858d', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 3, 3, 'and they commanded the people, saying, "When you see the ark of the covenant of Yahweh your God, and the priests the Levites bearing it, then you shall move from your place, and follow it.'),
  ('d30278b8-ea22-525e-adb0-f55f00152c44', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 4, 4, 'Yet there shall be a space between you and it, about two thousand cubits by measure. Don''t come near to it, that you may know the way by which you must go; for you have not passed this way before."'),
  ('c4e3c0ca-9faa-5e21-a63b-2fa35f3c8826', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 5, 5, 'Joshua said to the people, "Sanctify yourselves; for tomorrow Yahweh will do wonders among you."'),
  ('abc14687-eac9-5588-a5b4-44ae8750c79e', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 6, 6, 'Joshua spoke to the priests, saying, "Take up the ark of the covenant, and pass over before the people." They took up the ark of the covenant, and went before the people.'),
  ('5e055fe8-74c3-5024-a6a1-c4795b925f87', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 7, 7, 'Yahweh said to Joshua, "Today I will begin to magnify you in the sight of all Israel, that they may know that as I was with Moses, so I will be with you.'),
  ('1f9fd5de-5df8-5c66-a6b4-7bba76a7149f', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 8, 8, 'You shall command the priests who bear the ark of the covenant, saying, ''When you come to the brink of the waters of the Jordan, you shall stand still in the Jordan.''"'),
  ('c11c58d8-9b24-5ea3-aaf9-06b1e9cf4a47', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 9, 9, 'Joshua said to the children of Israel, "Come here, and hear the words of Yahweh your God."'),
  ('0af8927a-05ec-5445-a36c-f6f50f8f893a', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 10, 10, 'Joshua said, "Hereby you shall know that the living God is among you, and that he will without fail drive the Canaanite, and the Hittite, and the Hivite, and the Perizzite, and the Girgashite, and the Amorite, and the Jebusite out from before you.'),
  ('acd1a090-e002-583c-a6d9-d189cad82498', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 11, 11, 'Behold, the ark of the covenant of the Lord of all the earth passes over before you into the Jordan.'),
  ('29bd4a3e-9060-53e1-ae62-72d72076bc3e', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 12, 12, 'Now therefore take twelve men out of the tribes of Israel, for every tribe a man.'),
  ('350d1ab8-bdea-57bf-a053-0ea200ca21c0', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 13, 13, 'It shall come to pass, when the soles of the feet of the priests who bear the ark of Yahweh, the Lord of all the earth, rest in the waters of the Jordan, that the waters of the Jordan will be cut off, even the waters that come down from above; and they shall stand in one heap."'),
  ('b9b7f928-636f-5314-a564-1cd5031fe210', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 14, 14, 'It happened, when the people moved from their tents to pass over the Jordan, the priests who bore the ark of the covenant being before the people,'),
  ('721c6ba0-09cf-566d-a532-df864ade7c45', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 15, 15, 'and when those who bore the ark had come to the Jordan, and the feet of the priests who bore the ark had dipped in the edge of the water (for the Jordan overflows all its banks all the time of harvest),'),
  ('9053b9d2-caca-5445-ad79-c7152cd0c639', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 16, 16, 'that the waters which came down from above stood, and rose up in one heap, a great way off, at Adam, the city that is beside Zarethan; and those that went down toward the sea of the Arabah, even the Salt Sea, were wholly cut off. Then the people passed over right against Jericho.'),
  ('d1cd3eee-3342-5d14-acb2-c3c33bd843c3', '5f03d7f2-23f1-5adf-a6f3-a2ad368f863f', NULL, 17, 17, 'The priests who bore the ark of the covenant of Yahweh stood firm on dry ground in the middle of the Jordan; and all Israel passed over on dry ground, until all the nation had passed completely over the Jordan.'),
  ('734382d9-176e-5e3d-a512-246b9c798762', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 1, 1, 'It happened, when all the nation had completely passed over the Jordan, that Yahweh spoke to Joshua, saying,'),
  ('f017e20b-83f6-5811-af2b-6136be84e0d2', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 2, 2, '"Take twelve men out of the people, out of every tribe a man,'),
  ('5b398ecb-fca3-5e3f-a2d6-bfb2922c74f0', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 3, 3, 'and command them, saying, ''Take from out of the middle of the Jordan, out of the place where the priests'' feet stood firm, twelve stones, and carry them over with you, and lay them down in the lodging place, where you will lodge tonight.''"'),
  ('25f42c79-12f6-5ccc-a408-d989c293132a', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 4, 4, 'Then Joshua called the twelve men, whom he had prepared of the children of Israel, out of every tribe a man.'),
  ('6ae9950c-6e56-5e9b-a6d6-7dda789aee4c', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 5, 5, 'Joshua said to them, "Pass over before the ark of Yahweh your God into the middle of the Jordan, and each of you pick up a stone and put it on your shoulder, according to the number of the tribes of the children of Israel;'),
  ('a2efa08d-3154-5d1d-a091-6d7758b34cab', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 6, 6, 'that this may be a sign among you, that when your children ask in time to come, saying, ''What do you mean by these stones?'''),
  ('e558f2a8-0314-5715-ab58-a820749f36f5', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 7, 7, 'then you shall tell them, ''Because the waters of the Jordan were cut off before the ark of the covenant of Yahweh. When it passed over the Jordan, the waters of the Jordan were cut off. These stones shall be for a memorial to the children of Israel forever.''"'),
  ('2c3e80b8-c437-585c-a8be-ba4365dfd31a', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 8, 8, 'The children of Israel did as Joshua commanded, and took up twelve stones out of the middle of the Jordan, as Yahweh spoke to Joshua, according to the number of the tribes of the children of Israel; and they carried them over with them to the place where they lodged, and laid them down there.'),
  ('92d1ad5b-a119-571d-a34a-38eb3dfb6c9c', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 9, 9, 'Joshua set up twelve stones in the middle of the Jordan, in the place where the feet of the priests who bore the ark of the covenant stood; and they are there to this day.'),
  ('733f361f-b6b1-5c42-a0b0-f846675255dd', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 10, 10, 'For the priests who bore the ark stood in the middle of the Jordan, until everything was finished that Yahweh commanded Joshua to speak to the people, according to all that Moses commanded Joshua; and the people hurried and passed over.'),
  ('aa1f6061-e08a-56ce-a1a2-2567e4b7a208', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 11, 11, 'It happened, when all the people had completely passed over, that the ark of Yahweh passed over, with the priests, in the presence of the people.'),
  ('6f55b80a-6427-5a43-af03-94ccb4fdcc4c', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 12, 12, 'The children of Reuben, and the children of Gad, and the half-tribe of Manasseh, passed over armed before the children of Israel, as Moses spoke to them.'),
  ('23c06417-b480-50a5-a6bf-aff66ba5e77f', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 13, 13, 'About forty thousand men, ready and armed for war passed over before Yahweh to battle, to the plains of Jericho.'),
  ('58d05cdb-e56f-5f8b-a8b5-6f83dc2c0dca', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 14, 14, 'On that day, Yahweh magnified Joshua in the sight of all Israel; and they feared him, as they feared Moses, all the days of his life.'),
  ('ca3e9cd9-fa1e-5c1c-ad70-f8d781d9bab3', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 15, 15, 'Yahweh spoke to Joshua, saying,'),
  ('0584e8bd-945b-5f82-ab96-819243cd7b07', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 16, 16, '"Command the priests who bear the ark of the testimony, that they come up out of the Jordan."'),
  ('d45a44b6-5ecc-5a8a-aa20-319f474d37c0', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 17, 17, 'Joshua therefore commanded the priests, saying, "Come up out of the Jordan!"'),
  ('dd70efc1-8b61-5081-a99b-035939b44f9d', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 18, 18, 'It happened, when the priests who bore the ark of the covenant of Yahweh had come up out of the middle of the Jordan, and the soles of the priests'' feet were lifted up to the dry ground, that the waters of the Jordan returned to their place, and went over all its banks, as before.'),
  ('2bfe47b4-bbae-570a-af45-e1d4c2e525b3', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 19, 19, 'The people came up out of the Jordan on the tenth day of the first month, and encamped in Gilgal, on the east border of Jericho.'),
  ('4db1ff7f-3cad-506a-acbe-073265b1cb33', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 20, 20, 'Joshua set up those twelve stones, which they took out of the Jordan, in Gilgal.'),
  ('e50da3f8-7360-5dcd-a3fe-0571f5a37f5f', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 21, 21, 'He spoke to the children of Israel, saying, "When your children ask their fathers in time to come, saying, ''What do these stones mean?'''),
  ('f041be53-b277-58c7-adef-24a2baecf7ac', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 22, 22, 'Then you shall let your children know, saying, ''Israel came over this Jordan on dry land.'),
  ('545d2164-86f8-558a-a20a-b28343bedeb1', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 23, 23, 'For Yahweh your God dried up the waters of the Jordan from before you, until you had passed over, as Yahweh your God did to the Red Sea, which he dried up from before us, until we had passed over;'),
  ('b34e0ee8-7527-5fa0-af9d-34c634f7c8de', '58ea770a-014d-56ea-a7c4-79503868c736', NULL, 24, 24, 'that all the peoples of the earth may know the hand of Yahweh, that it is mighty; that you may fear Yahweh your God forever.''"'),
  ('9d8b4e25-c72b-5c31-a697-e310b744eb8f', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 1, 1, 'It happened, when all the kings of the Amorites, who were beyond the Jordan westward, and all the kings of the Canaanites, who were by the sea, heard how that Yahweh had dried up the waters of the Jordan from before the children of Israel, until we had passed over, that their heart melted, neither was there spirit in them any more, because of the children of Israel.'),
  ('c6cfdd0e-2644-548b-ad2e-0c46697746e1', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 2, 2, 'At that time, Yahweh said to Joshua, "Make flint knives, and circumcise again the children of Israel the second time."'),
  ('6f1234aa-2aa6-53d5-aba5-dfe0dbbc3fb8', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 3, 3, 'Joshua made himself flint knives, and circumcised the children of Israel at the hill of the foreskins.'),
  ('b1f2a0de-f3e2-56b1-a911-885c578fa26e', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 4, 4, 'This is the reason Joshua circumcised: all the people who came out of Egypt, who were males, even all the men of war, died in the wilderness by the way, after they came out of Egypt.'),
  ('486d725f-17f8-533f-a112-3e46070d5481', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 5, 5, 'For all the people who came out were circumcised; but all the people who were born in the wilderness by the way as they came out of Egypt had not been circumcised.'),
  ('cd7ef025-cef1-5078-ac7c-cdcb7d96c4df', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 6, 6, 'For the children of Israel walked forty years in the wilderness, until all the nation, even the men of war who came out of Egypt, were consumed, because they didn''t listen to the voice of Yahweh. Yahweh swore to them that he wouldn''t let them see the land which Yahweh swore to their fathers that he would give us, a land flowing with milk and honey.'),
  ('137e5953-3789-5b66-a69c-05d925e9221f', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 7, 7, 'Their children, whom he raised up in their place, were circumcised by Joshua; for they were uncircumcised, because they had not circumcised them on the way.'),
  ('bfafb376-5451-54a2-a560-e9afbe3f9a0c', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 8, 8, 'It happened, when they were done circumcising all the nation, that they stayed in their places in the camp until they were healed.'),
  ('c87b2a0e-b0d5-550d-ace8-69daf50e5c5a', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 9, 9, 'Yahweh said to Joshua, "Today I have rolled away the reproach of Egypt from off you." Therefore the name of that place was called Gilgal, to this day.'),
  ('8563e8d0-2fe7-5c94-a2cf-1971abf03227', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 10, 10, 'The children of Israel encamped in Gilgal. They kept the Passover on the fourteenth day of the month at evening in the plains of Jericho.'),
  ('425a1006-04c2-5720-a372-5ebb4836a7b4', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 11, 11, 'They ate unleavened cakes and parched grain of the produce of the land on the next day after the Passover, in the same day.'),
  ('e90e92d3-9d03-581b-a13b-f1ae8348c788', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 12, 12, 'The manna ceased on the next day, after they had eaten of the produce of the land. The children of Israel didn''t have manna any more; but they ate of the fruit of the land of Canaan that year.'),
  ('0a468e5a-bcea-56b2-a887-f0c3661a1d1c', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 13, 13, 'It happened, when Joshua was by Jericho, that he lifted up his eyes and looked, and behold, a man stood in front of him with his sword drawn in his hand. Joshua went to him, and said to him, "Are you for us, or for our adversaries?"'),
  ('e234c9e9-5a21-5357-a858-7c948c514551', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 14, 14, 'He said, "No; but I have come now as commander of Yahweh''s army." Joshua fell on his face to the earth, and worshipped, and said to him, "What does my lord say to his servant?"'),
  ('f8d31f93-a601-5cad-a9bd-5ab25596db31', '819dbddf-4021-54a0-a9bd-eb529798b18b', NULL, 15, 15, 'The prince of Yahweh''s army said to Joshua, "Take your shoes off of your feet; for the place on which you stand is holy." Joshua did so.'),
  ('857408b9-072a-5bae-a16e-3c5bf73e91d6', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 1, 1, 'Now Jericho was tightly shut up because of the children of Israel. No one went out, and no one came in.'),
  ('28e1c3e3-c63d-5b57-a184-b935958c6a72', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 2, 2, 'Yahweh said to Joshua, "Behold, I have given Jericho into your hand, with its king and the mighty men of valor.'),
  ('8c927807-a182-570e-a3a4-355590358259', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 3, 3, 'All your men of war shall march around the city, going around the city once. You shall do this six days.'),
  ('fbed2a78-7824-561b-adbe-961ca16c9c4e', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 4, 4, 'Seven priests shall bear seven trumpets of rams'' horns before the ark. On the seventh day, you shall march around the city seven times, and the priests shall blow the trumpets.'),
  ('0f44ce75-0fe4-504f-a813-c519e65e3727', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 5, 5, 'It shall be that when they make a long blast with the ram''s horn, and when you hear the sound of the trumpet, all the people shall shout with a great shout; and the wall of the city shall fall down flat, and the people shall go up every man straight before him."'),
  ('6e153782-9260-5e6d-a716-a66d2ff73b20', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 6, 6, 'Joshua the son of Nun called the priests, and said to them, "Take up the ark of the covenant, and let seven priests bear seven trumpets of rams'' horns before the ark of Yahweh."'),
  ('6743357f-63c9-5989-ae9e-fdf9974ab620', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 7, 7, 'They said to the people, "Advance! March around the city, and let the armed men pass on before Yahweh''s ark."'),
  ('a5814b46-a0fb-5fa5-a289-99e3823c346d', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 8, 8, 'It was so, that when Joshua had spoken to the people, the seven priests bearing the seven trumpets of rams'' horns before Yahweh advanced, and blew the trumpets; and the ark of the covenant of Yahweh followed them.'),
  ('ace1c606-07f1-518f-a538-0789f356ea41', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 9, 9, 'The armed men went before the priests who blew the trumpets, and the ark went after them. The trumpets sounded as they went.'),
  ('8a154716-4147-5d7b-ad01-4e5fe689f9a6', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 10, 10, 'Joshua commanded the people, saying, "You shall not shout, nor let your voice be heard, neither shall any word proceed out of your mouth, until the day I tell you to shout. Then you shall shout."'),
  ('f4b14b37-183b-596c-a2dd-31ca6746ff48', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 11, 11, 'So he caused the ark of Yahweh to go around the city, going about it once. Then they came into the camp, and lodged in the camp.'),
  ('6648e8d7-b2c3-59a4-ada1-4663cbfe64cc', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 12, 12, 'Joshua rose early in the morning, and the priests took up the ark of Yahweh.'),
  ('f090a885-5345-5774-aee1-62fb2ec7f6b7', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 13, 13, 'The seven priests bearing the seven trumpets of rams'' horns before the ark of Yahweh went on continually, and blew the trumpets: and the armed men went before them. The rear guard came after the ark of Yahweh. The trumpets sounded as they went.'),
  ('73ccb629-bb4c-5242-af4c-e8173f042575', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 14, 14, 'The second day they marched around the city once, and returned into the camp. They did this six days.'),
  ('bbc8ac75-d02b-5bfc-afc0-8d72dc9aef04', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 15, 15, 'It happened on the seventh day, that they rose early at the dawning of the day, and marched around the city in the same way seven times. Only on this day they marched around the city seven times.'),
  ('029e2a79-7f06-5051-a1c3-62bc92d1f7dd', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 16, 16, 'It happened at the seventh time, when the priests blew the trumpets, Joshua said to the people, "Shout, for Yahweh has given you the city!'),
  ('0b7e5551-5734-560d-a727-1818cbc5f4b4', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 17, 17, 'The city shall be devoted, even it and all that is in it, to Yahweh. Only Rahab the prostitute shall live, she and all who are with her in the house, because she hid the messengers that we sent.'),
  ('1a4430ce-c7b3-5edb-ae73-2fcd6aa0b67d', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 18, 18, 'But as for you, only keep yourselves from the devoted thing, lest when you have devoted it, you take of the devoted thing; so would you make the camp of Israel accursed, and trouble it.'),
  ('b4c3f23b-55b0-53cb-a951-40c0534d1816', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 19, 19, 'But all the silver, and gold, and vessels of brass and iron, are holy to Yahweh. They shall come into Yahweh''s treasury."'),
  ('760055f7-f2e4-5f33-ab2b-6938cf47319e', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 20, 20, 'So the people shouted, and the priests blew the trumpets. It happened, when the people heard the sound of the trumpet, that the people shouted with a great shout, and the wall fell down flat, so that the people went up into the city, every man straight before him, and they took the city.'),
  ('4fb97591-fbc2-52a4-a9de-5a60a16ae185', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 21, 21, 'They utterly destroyed all that was in the city, both man and woman, both young and old, and ox, and sheep, and donkey, with the edge of the sword.'),
  ('01c3c517-f687-5b87-aaca-ad9c4da412f7', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 22, 22, 'Joshua said to the two men who had spied out the land, "Go into the prostitute''s house, and bring out from there the woman and all that she has, as you swore to her."'),
  ('f6192db4-045d-5560-a53f-568c0f0221e7', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 23, 23, 'The young men who were spies went in, and brought out Rahab with her father, her mother, her brothers, and all that she had. They also brought out all her relatives, and they set them outside of the camp of Israel.'),
  ('e09ba1b8-9e90-5b2c-a89b-d639f8c415bc', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 24, 24, 'They burnt the city with fire, and all that was in it. Only they put the silver, the gold, and the vessels of brass and of iron into the treasury of Yahweh''s house.'),
  ('b762dfa0-6ef7-58e0-a631-0910de56657e', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 25, 25, 'But Rahab the prostitute, her father''s household, and all that she had, Joshua saved alive. She lived in the midst of Israel to this day, because she hid the messengers, whom Joshua sent to spy out Jericho.'),
  ('ce0cd424-9f09-5d1b-a17c-fb9e8fc58e18', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 26, 26, 'Joshua commanded them with an oath at that time, saying, "Cursed is the man before Yahweh, who rises up and builds this city Jericho. With the loss of his firstborn shall he lay its foundation, and with the loss of his youngest son shall he set up its gates."'),
  ('30b218fb-d782-5a9a-a24d-df72d19fc9fc', '67cd67f0-e308-5a68-a130-a3e476123183', NULL, 27, 27, 'So Yahweh was with Joshua; and his fame was in all the land.'),
  ('5b74f593-d646-5030-a835-8a1001f7b3d2', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 1, 1, 'But the children of Israel committed a trespass in the devoted things; for Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, took some of the devoted things. Therefore Yahweh''s anger burned against the children of Israel.'),
  ('29c37d53-d934-5fec-a6e0-9dc8a772510b', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 2, 2, 'Joshua sent men from Jericho to Ai, which is beside Beth Aven, on the east side of Bethel, and spoke to them, saying, "Go up and spy out the land." The men went up and spied out Ai.'),
  ('ed60fd96-5e98-5caa-a4a0-cc39e1d6e91c', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 3, 3, 'They returned to Joshua, and said to him, "Don''t let all the people go up; but let about two or three thousand men go up and strike Ai. Don''t make all the people to toil there, for there are only a few of them."'),
  ('793c955f-50e6-5b13-acb3-1f2df1b6f097', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 4, 4, 'So about three thousand men of the people went up there, and they fled before the men of Ai.'),
  ('c1628d9e-8788-58c8-a46e-6c771f581d4c', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 5, 5, 'The men of Ai struck about thirty-six men of them, and they chased them from before the gate even to Shebarim, and struck them at the descent. The hearts of the people melted, and became like water.'),
  ('d26be9e3-04ea-5ba2-aeaf-6c6cfa7a331c', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 6, 6, 'Joshua tore his clothes, and fell to the earth on his face before the ark of Yahweh until the evening, he and the elders of Israel; and they put dust on their heads.'),
  ('0cc97b7a-121d-52ef-a014-aba0f59b4e13', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 7, 7, 'Joshua said, "Alas, Lord Yahweh, why have you brought this people over the Jordan at all, to deliver us into the hand of the Amorites, to cause us to perish? I wish that we had been content and lived beyond the Jordan!'),
  ('85ff0b6a-edb4-56e0-ae13-b79399162232', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 8, 8, 'Oh, Lord, what shall I say, after that Israel has turned their backs before their enemies!'),
  ('30eb06be-3190-517a-aa5b-e3800641be21', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 9, 9, 'For the Canaanites and all the inhabitants of the land will hear of it, and will surround us, and cut off our name from the earth. What will you do for your great name?"'),
  ('a7649ac9-79f0-5415-ab47-9ed39d8a5f64', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 10, 10, 'Yahweh said to Joshua, "Get up! Why are you fallen on your face like that?'),
  ('1264baa7-3828-5d84-ac98-3ff275475181', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 11, 11, 'Israel has sinned. Yes, they have even transgressed my covenant which I commanded them. Yes, they have even taken of the devoted things, and have also stolen, and also deceived. They have even put it among their own stuff.'),
  ('0ed1421f-67c7-511b-a2bc-31d11bcdf0a3', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 12, 12, 'Therefore the children of Israel can''t stand before their enemies. They turn their backs before their enemies, because they have become devoted for destruction. I will not be with you any more, unless you destroy the devoted things from among you.'),
  ('b08e2234-ea84-5a3b-a312-eeabc3aa70a9', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 13, 13, '"Get up! Sanctify the people, and say, ''Sanctify yourselves for tomorrow, for Yahweh, the God of Israel, says, "There is a devoted thing in the midst of you, Israel. You cannot stand before your enemies until you take away the devoted thing from among you."'),
  ('f1cfc57a-fbd9-51be-abbf-3ad38c819c20', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 14, 14, '"''In the morning therefore you shall be brought near by your tribes. It shall be that the tribe which Yahweh selects shall come near by families. The family which Yahweh selects shall come near by households. The household which Yahweh selects shall come near man by man.'),
  ('0698ead4-7ad1-56ea-a3ae-1e998d4cd221', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 15, 15, 'It shall be, that he who is taken with the devoted thing shall be burnt with fire, he and all that he has, because he has transgressed the covenant of Yahweh, and because he has done a disgraceful thing in Israel.''"'),
  ('5dd073be-b236-5eeb-a2da-e6e393c6a841', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 16, 16, 'So Joshua rose up early in the morning and brought Israel near by their tribes. The tribe of Judah was selected.'),
  ('fd3772f8-38b7-5eb4-aa1f-cc999be01bd9', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 17, 17, 'He brought near the family of Judah; and he selected the family of the Zerahites. He brought near the family of the Zerahites man by man, and Zabdi was selected.'),
  ('6dd5ff46-39fa-5409-a11d-899b99450f7e', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 18, 18, 'He brought near his household man by man, and Achan, the son of Carmi, the son of Zabdi, the son of Zerah, of the tribe of Judah, was selected.'),
  ('1a5c70e6-c423-56ac-a3e9-f856fd35bb84', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 19, 19, 'Joshua said to Achan, "My son, please give glory to Yahweh, the God of Israel, and make confession to him. Tell me now what you have done! Don''t hide it from me!"'),
  ('11393958-149e-5aa2-a316-bfead11e2397', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 20, 20, 'Achan answered Joshua, and said, "I have truly sinned against Yahweh, the God of Israel, and this is what I have done.'),
  ('528f7f3f-6ccc-55f2-a668-555c5989d5a7', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 21, 21, 'When I saw among the spoil a beautiful Babylonian robe, two hundred shekels of silver, and a wedge of gold weighing fifty shekels, then I coveted them and took them. Behold, they are hidden in the ground in the middle of my tent, with the silver under it."'),
  ('4247ebc2-02b2-53a7-ae49-52d2bc006aaf', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 22, 22, 'So Joshua sent messengers, and they ran to the tent. Behold, it was hidden in his tent, with the silver under it.'),
  ('57851c94-adce-59a0-a3f2-b8657c30bd57', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 23, 23, 'They took them from the middle of the tent, and brought them to Joshua and to all the children of Israel. They laid them down before Yahweh.'),
  ('d49e021c-e0c9-562c-a22b-dacdf7d7911b', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 24, 24, 'Joshua, and all Israel with him, took Achan the son of Zerah, the silver, the robe, the wedge of gold, his sons, his daughters, his cattle, his donkeys, his sheep, his tent, and all that he had; and they brought them up to the valley of Achor.'),
  ('fda18590-6617-5f2c-aa6d-ffb2f21bf220', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 25, 25, 'Joshua said, "Why have you troubled us? Yahweh will trouble you this day." All Israel stoned him with stones, and they burned them with fire and stoned them with stones.'),
  ('9b8a4840-70e5-5131-ab55-59f0e73785ce', '19c65220-2a54-5038-a881-65d39a9f951f', NULL, 26, 26, 'They raised over him a great heap of stones that remains to this day. Yahweh turned from the fierceness of his anger. Therefore the name of that place was called "The valley of Achor" to this day.'),
  ('a272a0e4-d977-5999-a62e-348ad56a38be', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 1, 1, 'Yahweh said to Joshua, "Don''t be afraid, neither be dismayed. Take all the people of war with you, and arise, go up to Ai. Behold, I have given into your hand the king of Ai, with his people, his city, and his land.'),
  ('f977c2da-b922-5d14-a93e-754ffa1f76b6', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 2, 2, 'You shall do to Ai and her king as you did to Jericho and her king, except its spoil and its livestock, you shall take for a plunder for yourselves. Set an ambush for the city behind it."'),
  ('18a97cee-6ddf-5f92-a11a-aa84d5a161aa', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 3, 3, 'So Joshua arose, and all the people of war, to go up to Ai. Joshua chose thirty thousand men, the mighty men of valor, and sent them out by night.'),
  ('306721c9-293c-5885-aef7-c6c39dd1c99a', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 4, 4, 'He commanded them, saying, "Behold, you shall lie in ambush against the city, behind the city. Don''t go very far from the city, but all of you be ready.'),
  ('c816e0e6-c853-56e5-af64-2fc66c6cbbf8', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 5, 5, 'I, and all the people who are with me, will approach to the city. It shall happen, when they come out against us, as at the first, that we will flee before them.'),
  ('acbe022e-85ed-54a4-a1d8-9e4e4fc32884', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 6, 6, 'They will come out after us, until we have drawn them away from the city; for they will say, ''They flee before us, like the first time.'' So we will flee before them,'),
  ('316a1f87-5676-5bd8-a3ec-b7fc60b336ba', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 7, 7, 'and you shall rise up from the ambush, and take possession of the city; for Yahweh your God will deliver it into your hand.'),
  ('b7ff445f-9ad2-5a62-a5bb-267b67435244', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 8, 8, 'It shall be, when you have seized on the city, that you shall set the city on fire. You shall do this according to the word of Yahweh. Behold, I have commanded you."'),
  ('0fa68625-43de-56ff-a5a8-27ae3ba43e6f', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 9, 9, 'Joshua sent them out; and they went to set up the ambush, and stayed between Bethel and Ai, on the west side of Ai; but Joshua stayed among the people that night.'),
  ('38ac78d9-51c6-58f0-a107-0af612f1dc45', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 10, 10, 'Joshua rose up early in the morning, mustered the people, and went up, he and the elders of Israel, before the people to Ai.'),
  ('56097762-52f8-52d6-a1e2-f4f569757878', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 11, 11, 'All the people, even the men of war who were with him, went up, and drew near, and came before the city, and encamped on the north side of Ai. Now there was a valley between him and Ai.'),
  ('3cced57c-8d8c-5ed4-a09d-75da9e137728', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 12, 12, 'He took about five thousand men, and set them in ambush between Bethel and Ai, on the west side of the city.'),
  ('7ec882bc-5126-5846-aae2-9c30b8e77067', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 13, 13, 'So they set the people, even all the army who was on the north of the city, and their ambush on the west of the city; and Joshua went that night into the midst of the valley.'),
  ('98ff1512-ed30-5f10-a7d0-d0c3365300a2', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 14, 14, 'It happened, when the king of Ai saw it, that they hurried and rose up early, and the men of the city went out against Israel to battle, he and all his people, at the time appointed, before the Arabah; but he didn''t know that there was an ambush against him behind the city.'),
  ('8a3eab8a-6138-53b1-a4b7-ccda4d5a31b3', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 15, 15, 'Joshua and all Israel made as if they were beaten before them, and fled by the way of the wilderness.'),
  ('3a98c0a4-a621-5eba-a15d-da38496e152b', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 16, 16, 'All the people who were in the city were called together to pursue after them. They pursued Joshua, and were drawn away from the city.'),
  ('0e1568db-f6f8-518b-a34f-edf0b7679b7b', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 17, 17, 'There was not a man left in Ai or Beth El who didn''t go out after Israel. They left the city open, and pursued Israel.'),
  ('cfb5bb10-4de6-547b-a241-eb516550bddf', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 18, 18, 'Yahweh said to Joshua, "Stretch out the javelin that is in your hand toward Ai, for I will give it into your hand." Joshua stretched out the javelin that was in his hand toward the city.'),
  ('ba7cc965-ae77-5926-a4d2-b660bea32955', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 19, 19, 'The ambush arose quickly out of their place, and they ran as soon as he had stretched out his hand, and entered into the city, and took it. They hurried and set the city on fire.'),
  ('ef141c65-7314-5777-ac77-cb12af700d44', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 20, 20, 'When the men of Ai looked behind them, they saw, and behold, the smoke of the city ascended up to heaven, and they had no power to flee this way or that way. The people who fled to the wilderness turned back on the pursuers.'),
  ('0434d3ca-d66b-5d4a-a484-e557ca8ac84c', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 21, 21, 'When Joshua and all Israel saw that the ambush had taken the city, and that the smoke of the city ascended, then they turned again, and killed the men of Ai.'),
  ('0f750ee3-07b7-5e4b-a2a4-6ca8785d4444', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 22, 22, 'The others came out of the city against them, so they were in the midst of Israel, some on this side, and some on that side. They struck them, so that they let none of them remain or escape.'),
  ('86dbbe8c-7e68-5cf9-acdf-a5b3914c8f28', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 23, 23, 'They captured the king of Ai alive, and brought him to Joshua.'),
  ('f30cf4e1-e904-59c7-a77e-70a080a42687', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 24, 24, 'It happened, when Israel had made an end of killing all the inhabitants of Ai in the field, in the wilderness in which they pursued them, and they had all fallen by the edge of the sword, until they were consumed, that all Israel returned to Ai, and struck it with the edge of the sword.'),
  ('cb4a88a1-1150-5a1e-ad16-5f63ef72782b', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 25, 25, 'All that fell that day, both of men and women, were twelve thousand, even all the men of Ai.'),
  ('35cca567-0ecf-519c-ab9e-d49c1e4e5e62', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 26, 26, 'For Joshua didn''t draw back his hand, with which he stretched out the javelin, until he had utterly destroyed all the inhabitants of Ai.'),
  ('a95275fd-5d62-566b-a4dc-99d7d7966f8e', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 27, 27, 'Only the livestock and the spoil of that city Israel took for prey to themselves, according to the word of Yahweh which he commanded Joshua.'),
  ('5334eb5f-1b6f-576c-a83f-0b7153943f04', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 28, 28, 'So Joshua burnt Ai, and made it a heap forever, even a desolation, to this day.'),
  ('38754524-7e4c-590b-aa25-767c446a2819', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 29, 29, 'He hanged the king of Ai on a tree until the evening, and at the sundown Joshua commanded, and they took his body down from the tree, and threw it at the entrance of the gate of the city, and raised a great heap of stones on it that remains to this day.'),
  ('3620fd05-b9e8-5b78-a34f-6cc1073dc02e', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 30, 30, 'Then Joshua built an altar to Yahweh, the God of Israel, in Mount Ebal,'),
  ('b93ad58c-9edc-560e-ad55-bc03bd7e3275', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 31, 31, 'as Moses the servant of Yahweh commanded the children of Israel, as it is written in the book of the law of Moses, an altar of uncut stones, on which no man had lifted up any iron. They offered burnt offerings on it to Yahweh, and sacrificed peace offerings.'),
  ('06597c9f-81ce-5e64-a7d9-eb90cfaf2cf0', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 32, 32, 'He wrote there on the stones a copy of the law of Moses, which he wrote in the presence of the children of Israel.'),
  ('6deff8e6-50b8-58a0-ae10-77ba501d3ae6', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 33, 33, 'All Israel, and their elders and officers, and their judges, stood on this side of the ark and on that side before the priests the Levites, who carried the ark of Yahweh''s covenant, the foreigner as well as the native; half of them in front of Mount Gerizim, and half of them in front of Mount Ebal, as Moses the servant of Yahweh had commanded at the first, that they should bless the people of Israel.'),
  ('1fc4a43c-f0de-5618-a365-e973501801a9', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 34, 34, 'Afterward he read all the words of the law, the blessing and the curse, according to all that is written in the book of the law.'),
  ('8f7d3826-dc9a-5543-a53a-c68844037f03', 'b9fdf156-0752-5bba-a64a-7b0d0e1515a9', NULL, 35, 35, 'There was not a word of all that Moses commanded, which Joshua didn''t read before all the assembly of Israel, with the women, the little ones, and the foreigners who were among them.'),
  ('8fe43680-d38a-57d7-a2ba-e06e9880e593', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 1, 1, 'It happened, when all the kings who were beyond the Jordan, in the hill country, and in the lowland, and on all the shore of the great sea in front of Lebanon, the Hittite, the Amorite, the Canaanite, the Perizzite, the Hivite, and the Jebusite, heard of it'),
  ('96936cf6-b90f-5d79-ac4d-cd8c4e50811d', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 2, 2, 'that they gathered themselves together to fight with Joshua and with Israel, with one accord.'),
  ('a45fc9a2-7625-570b-aa90-cb3c24149691', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 3, 3, 'But when the inhabitants of Gibeon heard what Joshua had done to Jericho and to Ai,'),
  ('c58390a1-df6b-58a2-ae8a-a5d8e3604a84', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 4, 4, 'they also resorted to a ruse, and went and made as if they had been ambassadors, and took old sacks on their donkeys, and wineskins, old and torn and bound up,'),
  ('59ec2227-5f60-518d-a5fe-3d37380e28a7', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 5, 5, 'and old and patched shoes on their feet, and wore old garments. All the bread of their provision was dry and moldy.'),
  ('8f3c458f-76c3-5f1a-a962-0ce3788e8888', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 6, 6, 'They went to Joshua to the camp at Gilgal, and said to him, and to the men of Israel, "We have come from a far country. Now therefore make a covenant with us."'),
  ('89887b8f-1882-5530-a484-0132bf04bc1f', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 7, 7, 'The men of Israel said to the Hivites, "What if you live among us. How could we make a covenant with you?"'),
  ('fd48921e-e8ea-5baf-aec3-87651a05dde0', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 8, 8, 'They said to Joshua, "We are your servants." Joshua said to them, "Who are you? Where do you come from?"'),
  ('42cf7a8d-6554-5569-ab77-fc8fac295e75', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 9, 9, 'They said to him, "Your servants have come from a very far country because of the name of Yahweh your God; for we have heard of his fame, all that he did in Egypt,'),
  ('c4fcf824-042a-566b-a463-1a31af8da245', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 10, 10, 'and all that he did to the two kings of the Amorites who were beyond the Jordan, to Sihon king of Heshbon and to Og king of Bashan, who was at Ashtaroth.'),
  ('8ead6de9-9471-5d94-a575-667e614a341a', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 11, 11, 'Our elders and all the inhabitants of our country spoke to us, saying, ''Take provision in your hand for the journey, and go to meet them, and tell them, "We are your servants. Now make a covenant with us."'''),
  ('44882f5b-8886-5990-af76-84f0dde42d87', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 12, 12, 'This our bread we took hot for our provision out of our houses on the day we went out to go to you; but now, behold, it is dry, and has become moldy.'),
  ('d4123029-86bc-5f61-a62d-47197d81abe5', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 13, 13, 'These wineskins, which we filled, were new; and behold, they are torn. These our garments and our shoes have become old because of the very long journey."'),
  ('f09f68c2-9977-5a5a-a9b7-dabf862a7a1e', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 14, 14, 'The men sampled their provisions, and didn''t ask counsel from the mouth of Yahweh.'),
  ('2aad6257-1990-5706-a4fb-32641b9a7e5b', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 15, 15, 'Joshua made peace with them, and made a covenant with them, to let them live. The princes of the congregation swore to them.'),
  ('6b36eb37-46f7-535f-add1-3f89c495f416', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 16, 16, 'It happened at the end of three days after they had made a covenant with them, that they heard that they were their neighbors, and that they lived among them.'),
  ('373f4e29-8d8e-59aa-aba4-fa1ab88cfea0', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 17, 17, 'The children of Israel traveled and came to their cities on the third day. Now their cities were Gibeon, Chephirah, Beeroth, and Kiriath Jearim.'),
  ('97db35a0-f200-525a-a512-308c4e8644e7', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 18, 18, 'The children of Israel didn''t strike them, because the princes of the congregation had sworn to them by Yahweh, the God of Israel. All the congregation murmured against the princes.'),
  ('86a79870-17ab-52ad-a842-925dbe23599a', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 19, 19, 'But all the princes said to all the congregation, "We have sworn to them by Yahweh, the God of Israel: now therefore we may not touch them.'),
  ('26f05071-9c9a-59bd-a84e-a973f4eade6b', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 20, 20, 'This we will do to them, and let them live; lest wrath be on us, because of the oath which we swore to them."'),
  ('461c5f7f-5bb2-57b9-a3b9-f97f80e102d2', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 21, 21, 'The princes said to them, "Let them live, so they became wood cutters and drawers of water for all the congregation, as the princes had spoken to them."'),
  ('65b8770a-3fcc-5cf1-ab2e-b73e618e124f', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 22, 22, 'Joshua called for them, and he spoke to them, saying, "Why have you deceived us, saying, ''We are very far from you,'' when you live among us?'),
  ('3f7ae356-71e2-5cbf-a925-842f2bb40a60', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 23, 23, 'Now therefore you are cursed, and some of you will never fail to be bondservants, both wood cutters and drawers of water for the house of my God."'),
  ('8b8e3c66-3678-529a-ab1c-3ec9086f2961', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 24, 24, 'They answered Joshua, and said, "Because your servants were certainly told how Yahweh your God commanded his servant Moses to give you all the land, and to destroy all the inhabitants of the land from before you. Therefore we were very afraid for our lives because of you, and have done this thing.'),
  ('815ba87b-59f6-5d89-a293-6e62c4e92dd3', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 25, 25, 'Now, behold, we are in your hand. Do to us as it seems good and right to you to do."'),
  ('02346304-cc06-5152-a850-d80aa4414377', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 26, 26, 'He did so to them, and delivered them out of the hand of the children of Israel, so that they didn''t kill them.'),
  ('84f5c862-49b1-58ee-a095-dfc18d63496b', 'd0260fcc-f56c-57e4-a9ea-235e7e947578', NULL, 27, 27, 'That day Joshua made them wood cutters and drawers of water for the congregation and for the altar of Yahweh, to this day, in the place which he should choose.'),
  ('0c3f9cb0-c917-5d80-a8a6-349e3aa58cba', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 1, 1, 'Now it happened when Adoni-Zedek king of Jerusalem heard how Joshua had taken Ai, and had utterly destroyed it; as he had done to Jericho and her king, so he had done to Ai and her king; and how the inhabitants of Gibeon had made peace with Israel, and were among them;'),
  ('896bb1d8-3c8b-50dd-a47b-4754312af1a2', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 2, 2, 'that they were very afraid, because Gibeon was a great city, as one of the royal cities, and because it was greater than Ai, and all its men were mighty.'),
  ('ff9711d3-4753-534c-a7fb-074d091cbafc', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 3, 3, 'Therefore Adoni-Zedek king of Jerusalem sent to Hoham king of Hebron, to Piram king of Jarmuth, to Japhia king of Lachish, and to Debir king of Eglon, saying,'),
  ('eb337a25-f6d5-5806-aca0-7ab43a236422', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 4, 4, '"Come up to me, and help me, and let us strike Gibeon; for it has made peace with Joshua and with the children of Israel."'),
  ('29e45542-7c53-5990-a551-95b40504b98a', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 5, 5, 'Therefore the five kings of the Amorites, the king of Jerusalem, the king of Hebron, the king of Jarmuth, the king of Lachish, the king of Eglon, gathered themselves together, and went up, they and all their armies, and encamped against Gibeon, and made war against it.'),
  ('0928878e-ff59-597f-a898-a4cf49936a4b', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 6, 6, 'The men of Gibeon sent to Joshua to the camp to Gilgal, saying, "Don''t abandon your servants! Come up to us quickly, and save us, and help us; for all the kings of the Amorites that dwell in the hill country have gathered together against us."'),
  ('a3fc7f2e-f268-592c-a6bf-035d749cd1ac', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 7, 7, 'So Joshua went up from Gilgal, he, and all the people of war with him, and all the mighty men of valor.'),
  ('aba930c7-0043-570d-a2f5-e1c136730e6f', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 8, 8, 'Yahweh said to Joshua, "Don''t fear them, for I have delivered them into your hands. Not a man of them will stand before you."'),
  ('d3ae2adb-ed09-5b36-aeca-60757b544276', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 9, 9, 'Joshua therefore came on them suddenly. He went up from Gilgal all night.'),
  ('cdef2f2c-3805-542b-a87d-13e18574b975', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 10, 10, 'Yahweh confused them before Israel, and he killed them with a great slaughter at Gibeon, and chased them by the way of the ascent of Beth Horon, and struck them to Azekah and to Makkedah.'),
  ('409d2e02-946d-5fc7-adfa-950e31c6764e', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 11, 11, 'It happened, as they fled from before Israel, while they were at the descent of Beth Horon, that Yahweh cast down great stones from the sky on them to Azekah, and they died. There were more who died from the hailstones than who the children of Israel killed with the sword.'),
  ('e40ad05e-e510-5c84-a800-1427b7dd3cf8', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 12, 12, 'Then Joshua spoke to Yahweh in the day when Yahweh delivered up the Amorites before the children of Israel; and he said in the sight of Israel, "Sun, stand still on Gibeon! You, moon, stop in the valley of Aijalon!"'),
  ('4b052768-96ae-5c44-ac1c-f57d48b1ef65', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 13, 13, 'The sun stood still, and the moon stayed, until the nation had avenged themselves of their enemies. Isn''t this written in the book of Jashar? The sun stayed in the midst of the sky, and didn''t hurry to go down about a whole day.'),
  ('b3bde419-6c75-5ee5-ac6a-0fc7c52319f0', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 14, 14, 'There was no day like that before it or after it, that Yahweh listened to the voice of a man; for Yahweh fought for Israel.'),
  ('ff9dc75a-bff5-5506-a7ab-16a65594ab65', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 15, 15, 'Joshua returned, and all Israel with him, to the camp to Gilgal.'),
  ('e54fd152-5dcc-5d40-a1dd-7aed740db5b6', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 16, 16, 'These five kings fled, and hid themselves in the cave at Makkedah.'),
  ('c90f7933-cdea-56f4-ab18-746a4f5dde67', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 17, 17, 'Joshua was told, saying, "The five kings are found, hidden in the cave at Makkedah."'),
  ('77fd2666-97fa-5399-a710-f72dd692e34b', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 18, 18, 'Joshua said, "Roll large stones to the mouth of the cave, and set men by it to guard them;'),
  ('781c4767-9d4e-54b3-a937-8480663273ee', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 19, 19, 'but don''t stay. Pursue your enemies, and them from the rear. Don''t allow them to enter into their cities; for Yahweh your God has delivered them into your hand."'),
  ('2907da1f-c99e-5297-a8aa-16cf894381d4', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 20, 20, 'It happened, when Joshua and the children of Israel had finished killing them with a very great slaughter until they were consumed, and the remnant which remained of them had entered into the fortified cities,'),
  ('3a91e17f-a703-580f-a326-03d7e7c9ce0b', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 21, 21, 'that all the people returned to the camp to Joshua at Makkedah in peace. None moved his tongue against any of the children of Israel.'),
  ('5624a0e8-5c45-51f4-af75-53f4dce3e972', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 22, 22, 'Then Joshua said, "Open the mouth of the cave, and bring those five kings out of the cave to me."'),
  ('52128da8-8c82-53f2-a576-77944ec23f58', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 23, 23, 'They did so, and brought those five kings out of the cave to him: the king of Jerusalem, the king of Hebron, the king of Jarmuth, the king of Lachish, and the king of Eglon.'),
  ('854ad126-677e-5a39-a385-ef1588ff8f1d', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 24, 24, 'It happened, when they brought those kings out to Joshua, that Joshua called for all the men of Israel, and said to the chiefs of the men of war who went with him, "Come near, put your feet on the necks of these kings." They came near, and put their feet on their necks.'),
  ('0d3558fa-01ad-5ff9-afa7-d8e7e0f120fa', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 25, 25, 'Joshua said to them, "Don''t be afraid, nor be dismayed. Be strong and courageous, for Yahweh will do this to all your enemies against whom you fight."'),
  ('7681e557-ff6a-52dc-a7f9-04415c171613', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 26, 26, 'Afterward Joshua struck them, put them to death, and hanged them on five trees. They were hanging on the trees until the evening.'),
  ('9aef204e-d13e-5034-a606-01410a0e16ce', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 27, 27, 'It happened at the time of the going down of the sun, that Joshua commanded, and they took them down off the trees, and cast them into the cave in which they had hidden themselves, and laid great stones on the mouth of the cave, which remain to this very day.'),
  ('579fd23d-4f7b-5342-aaf9-7331e6c6eb8b', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 28, 28, 'Joshua took Makkedah on that day, and struck it with the edge of the sword, with its king. He utterly destroyed them and all the souls who were in it. He left none remaining. He did to the king of Makkedah as he had done to the king of Jericho.'),
  ('d5795046-0705-522e-a380-d3ac633411ea', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 29, 29, 'Joshua passed from Makkedah, and all Israel with him, to Libnah, and fought against Libnah.'),
  ('bd71dbb2-73fd-539a-a910-79e677ca913e', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 30, 30, 'Yahweh delivered it also, with its king, into the hand of Israel. He struck it with the edge of the sword, and all the souls who were in it. He left none remaining in it. He did to its king as he had done to the king of Jericho.'),
  ('dd8cd6b6-0f49-5d92-accf-cacd89280e7f', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 31, 31, 'Joshua passed from Libnah, and all Israel with him, to Lachish, and encamped against it, and fought against it.'),
  ('b4267dd2-b981-5660-a0ae-6b994be83962', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 32, 32, 'Yahweh delivered Lachish into the hand of Israel. He took it on the second day, and struck it with the edge of the sword, with all the souls who were in it, according to all that he had done to Libnah.'),
  ('53a6ac2f-d446-5246-a418-851090a5a1ae', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 33, 33, 'Then Horam king of Gezer came up to help Lachish; and Joshua struck him and his people, until he had left him none remaining.'),
  ('bf7691f8-87e7-5959-acc8-07206b1e2078', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 34, 34, 'Joshua passed from Lachish, and all Israel with him, to Eglon; and they encamped against it fought against it.'),
  ('05bb4219-2674-5784-a403-f16963480647', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 35, 35, 'They took it on that day, and struck it with the edge of the sword. He utterly destroyed all the souls who were in it that day, according to all that he had done to Lachish.'),
  ('9bbf5533-9158-5c07-aa14-44915385fb51', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 36, 36, 'Joshua went up from Eglon, and all Israel with him, to Hebron; and they fought against it.'),
  ('97954027-9545-5131-a96c-5376d5290c81', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 37, 37, 'They took it, and struck it with the edge of the sword, with its king and all its cities, and all the souls who were in it. He left none remaining, according to all that he had done to Eglon; but he utterly destroyed it, and all the souls who were in it.'),
  ('409b363a-e4b7-513c-ac8d-63c48518c1f9', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 38, 38, 'Joshua returned, and all Israel with him, to Debir, and fought against it.'),
  ('d5dec7f8-7480-5d4e-a22a-63ce7f1be10d', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 39, 39, 'He took it, with its king and all its cities. They struck them with the edge of the sword, and utterly destroyed all the souls who were in it. He left none remaining. As he had done to Hebron, so he did to Debir, and to its king; as he had done also to Libnah, and to its king.'),
  ('d6ef14d9-8ae7-5e81-ae4e-1cd8c1637ae7', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 40, 40, 'So Joshua struck all the land, the hill country, and the South, and the lowland, and the slopes, and all their kings. He left none remaining, but he utterly destroyed all that breathed, as Yahweh, the God of Israel, commanded.'),
  ('61b9ee47-4fb7-530c-a591-a707be5d0e83', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 41, 41, 'Joshua struck them from Kadesh Barnea even to Gaza, and all the country of Goshen, even to Gibeon.'),
  ('24859771-4276-548e-a96d-112fb0eab85c', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 42, 42, 'Joshua took all these kings and their land at one time, because Yahweh, the God of Israel, fought for Israel.'),
  ('59627f13-1dd8-5fbc-a0f3-89ef85e73dd8', 'd9adc640-7f54-5c8d-abcf-c46139c1ba34', NULL, 43, 43, 'Joshua returned, and all Israel with him, to the camp to Gilgal.'),
  ('8111967c-cdf2-52c9-a9e3-6453d7ceb1a9', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 1, 1, 'It happened, when Jabin king of Hazor heard of it, that he sent to Jobab king of Madon, to the king of Shimron, to the king of Achshaph,'),
  ('254aabb3-c649-5568-a566-42c43c4fabf3', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 2, 2, 'and to the kings who were on the north, in the hill country, in the Arabah south of Chinneroth, in the lowland, and in the heights of Dor on the west,'),
  ('f2ac12e8-62fc-5f76-add7-264d64e5919b', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 3, 3, 'to the Canaanite on the east and on the west, and the Amorite, and the Hittite, and the Perizzite, and the Jebusite in the hill country, and the Hivite under Hermon in the land of Mizpah.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('e333be66-869e-5dee-a9d0-39d17ac6438a', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 4, 4, 'They went out, they and all their armies with them, many people, even as the sand that is on the seashore in multitude, with very many horses and chariots.'),
  ('22a0ef39-6a21-5ac1-a858-7f6b37bab9dd', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 5, 5, 'All these kings met together; and they came and encamped together at the waters of Merom, to fight with Israel.'),
  ('cde73841-6c2c-5ea0-a9d7-efb5c9d2bdc1', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 6, 6, 'Yahweh said to Joshua, "Don''t be afraid because of them; for tomorrow at this time, I will deliver them up all slain before Israel. You shall hamstring their horses and burn their chariots with fire."'),
  ('b9413b34-fdd4-5143-a299-fea36fcbc505', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 7, 7, 'So Joshua came, and all the people of war with him, against them by the waters of Merom suddenly, and fell on them.'),
  ('c1149210-5b03-5f11-a143-f7de3aece47a', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 8, 8, 'Yahweh delivered them into the hand of Israel, and they struck them, and chased them to great Sidon, and to Misrephoth Maim, and to the valley of Mizpeh eastward. They struck them until they left them none remaining.'),
  ('fc0bd91f-7bc1-5d83-ac9f-a5707f828d2e', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 9, 9, 'Joshua did to them as Yahweh told him. He hamstrung their horses and burnt their chariots with fire.'),
  ('eecc9d20-c72d-531d-a966-689cda2afdf1', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 10, 10, 'Joshua turned back at that time, and took Hazor, and struck its king with the sword: for Hazor used to be the head of all those kingdoms.'),
  ('64cf9d10-e18e-5bfb-a07b-15f59537dcd6', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 11, 11, 'They struck all the souls who were in it with the edge of the sword, utterly destroying them. There was no one left who breathed. He burnt Hazor with fire.'),
  ('0bed6ca4-7947-5bb6-a5c0-da48ffef4469', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 12, 12, 'Joshua captured all the cities of those kings, with their kings, and he struck them with the edge of the sword, and utterly destroyed them; as Moses the servant of Yahweh commanded.'),
  ('e95addba-0ef5-5373-a678-bed74880954e', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 13, 13, 'But as for the cities that stood on their mounds, Israel burned none of them, except Hazor only. Joshua burned that.'),
  ('009e458e-c3bb-57cd-ab47-eb4d4de74ce5', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 14, 14, 'The children of Israel took all the spoil of these cities, with the livestock, as spoils for themselves; but every man they struck with the edge of the sword, until they had destroyed them. They didn''t leave any who breathed.'),
  ('f7c79960-c7f2-51f8-a899-ff582f9ea915', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 15, 15, 'As Yahweh commanded Moses his servant, so Moses commanded Joshua. Joshua did so. He left nothing undone of all that Yahweh commanded Moses.'),
  ('93dcf1a6-041c-5112-af9e-deeca7637785', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 16, 16, 'So Joshua captured all that land, the hill country, all the South, all the land of Goshen, the lowland, the Arabah, the hill country of Israel, and the lowland of the same;'),
  ('ab9af759-cf63-5fed-ad32-99d45eab9cdf', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 17, 17, 'from Mount Halak, that goes up to Seir, even to Baal Gad in the valley of Lebanon under Mount Hermon. He took all their kings, struck them, and put them to death.'),
  ('9dad12ae-8ef6-5553-a53e-83ceb0ab0247', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 18, 18, 'Joshua made war a long time with all those kings.'),
  ('093c2235-ebb5-5080-a389-eb7c408e04db', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 19, 19, 'There was not a city that made peace with the children of Israel, except the Hivites, the inhabitants of Gibeon. They took all in battle.'),
  ('d9cdb1de-1076-50cc-a4b5-a3709715d375', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 20, 20, 'For it was of Yahweh to harden their hearts, to come against Israel in battle, that he might utterly destroy them, that they might have no favor, but that he might destroy them, as Yahweh commanded Moses.'),
  ('aff9fca1-b560-56b9-ae8b-f846511b4e4e', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 21, 21, 'Joshua came at that time, and cut off the Anakim from the hill country, from Hebron, from Debir, from Anab, and from all the hill country of Judah, and from all the hill country of Israel: Joshua utterly destroyed them with their cities.'),
  ('f8c2c71d-e802-5cd7-a98f-ad2189f0d706', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 22, 22, 'There were none of the Anakim left in the land of the children of Israel. Only in Gaza, in Gath, and in Ashdod, did some remain.'),
  ('3b7f415f-4d8f-5cf1-a128-58c920bb4f61', 'e59a7f38-59ef-5339-a124-51ee68825411', NULL, 23, 23, 'So Joshua took the whole land, according to all that Yahweh spoke to Moses; and Joshua gave it for an inheritance to Israel according to their divisions by their tribes. The land had rest from war.'),
  ('8ac1ba2f-589d-5379-a3c5-e246f38a0768', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 1, 1, 'Now these are the kings of the land, whom the children of Israel struck, and possessed their land beyond the Jordan toward the sunrise, from the valley of the Arnon to Mount Hermon, and all the Arabah eastward:'),
  ('dcf70c06-71df-5a95-a2b9-16b4b7e0c474', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 2, 2, 'Sihon king of the Amorites, who lived in Heshbon, and ruled from Aroer, which is on the edge of the valley of the Arnon, and the middle of the valley, and half Gilead, even to the river Jabbok, the border of the children of Ammon;'),
  ('20661554-df5c-5673-a563-e07114b3e7e5', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 3, 3, 'and the Arabah to the sea of Chinneroth, eastward, and to the sea of the Arabah, even the Salt Sea, eastward, the way to Beth Jeshimoth; and on the south, under the slopes of Pisgah:'),
  ('d3f7b07f-196c-51d1-a5bd-f1dcc7ecef23', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 4, 4, 'and the border of Og king of Bashan, of the remnant of the Rephaim, who lived at Ashtaroth and at Edrei,'),
  ('fe4ee362-e4bd-5897-a450-55d572d39fc6', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 5, 5, 'and ruled in Mount Hermon, and in Salecah, and in all Bashan, to the border of the Geshurites and the Maacathites, and half Gilead, the border of Sihon king of Heshbon.'),
  ('8d6bf856-828f-5215-a729-e103fc502d75', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 6, 6, 'Moses the servant of Yahweh and the children of Israel struck them. Moses the servant of Yahweh gave it for a possession to the Reubenites, and the Gadites, and the half-tribe of Manasseh.'),
  ('63940471-5536-5cf2-a596-3b221c1a1169', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 7, 7, 'These are the kings of the land whom Joshua and the children of Israel struck beyond the Jordan westward, from Baal Gad in the valley of Lebanon even to Mount Halak, that goes up to Seir. Joshua gave it to the tribes of Israel for a possession according to their divisions;'),
  ('8e63e5bc-442e-5ccb-a4ea-c6e4027ede9c', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 8, 8, 'in the hill country, and in the lowland, and in the Arabah, and in the slopes, and in the wilderness, and in the South; the Hittite, the Amorite, and the Canaanite, the Perizzite, the Hivite, and the Jebusite:'),
  ('b6df4f40-d0a9-57a2-ad00-984e7847ef8e', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 9, 9, 'the king of Jericho, one; the king of Ai, which is beside Bethel, one;'),
  ('bc4fedea-f4df-5983-a5af-877398d69515', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 10, 10, 'the king of Jerusalem, one; the king of Hebron, one;'),
  ('3f6a29d7-3ef7-5fbd-a269-47a5a0857412', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 11, 11, 'the king of Jarmuth, one; the king of Lachish, one;'),
  ('07978688-a1fa-54ee-a5c4-e210309bab9d', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 12, 12, 'the king of Eglon, one; the king of Gezer, one;'),
  ('a364868e-f8f5-5134-a69e-09ef0a5a2274', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 13, 13, 'the king of Debir, one; the king of Geder, one;'),
  ('9a10d43a-418a-55ad-a763-f72e95a0f288', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 14, 14, 'the king of Hormah, one; the king of Arad, one;'),
  ('64e39ade-c539-551d-a20c-24cdb6ceb964', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 15, 15, 'the king of Libnah, one; the king of Adullam, one;'),
  ('f1153756-6739-5495-ae35-67f27095b9ba', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 16, 16, 'the king of Makkedah, one; the king of Bethel, one;'),
  ('8e197410-5c5f-504e-a582-c494cc777fb8', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 17, 17, 'the king of Tappuah, one; the king of Hepher, one;'),
  ('fb276884-5b2e-5448-a83f-1c1ca80d3b8b', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 18, 18, 'the king of Aphek, one; the king of Lassharon, one;'),
  ('3872b123-642f-5cf8-abcf-4501390e923c', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 19, 19, 'the king of Madon, one; the king of Hazor, one;'),
  ('eab79bd3-8a82-56c1-a711-7b34dab75a74', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 20, 20, 'the king of Shimron Meron, one; the king of Achshaph, one;'),
  ('8ec437c5-284f-5301-af00-ed552517a32d', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 21, 21, 'the king of Taanach, one; the king of Megiddo, one;'),
  ('1ddd3a83-5756-54d6-a147-5c70d4bdacc0', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 22, 22, 'the king of Kedesh, one; the king of Jokneam in Carmel, one;'),
  ('20675510-211f-52c4-a04b-018c30422c79', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 23, 23, 'the king of Dor in the height of Dor, one; the king of Goiim in Gilgal, one;'),
  ('cfb4dc19-f42b-5faa-ad79-12d72ff57315', '5d609fc6-ca4e-50c4-a379-3293ac72bc7e', NULL, 24, 24, 'the king of Tirzah, one: all the kings thirty-one.'),
  ('e44659d4-a7ce-5855-a0df-f179dfd822fd', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 1, 1, 'Now Joshua was old and well advanced in years. Yahweh said to him, "You are old and advanced in years, and there remains yet very much land to be possessed.'),
  ('9527e1fd-b4e3-57b2-ac55-2d77c07821b6', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 2, 2, '"This is the land that still remains: all the regions of the Philistines, and all the Geshurites;'),
  ('0881cb3b-8d9c-5c23-a1e7-8c2eab0884de', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 3, 3, 'from the Shihor, which is before Egypt, even to the border of Ekron northward, which is counted as Canaanite; the five lords of the Philistines; the Gazites, and the Ashdodites, the Ashkelonites, the Gittites, and the Ekronites; also the Avvim,'),
  ('0ee03cc6-44f1-5ee8-abb2-52c08d34d7cb', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 4, 4, 'on the south; all the land of the Canaanites, and Mearah that belongs to the Sidonians, to Aphek, to the border of the Amorites;'),
  ('838dd491-8e47-5576-a81d-fde5c8746e58', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 5, 5, 'and the land of the Gebalites, and all Lebanon, toward the sunrise, from Baal Gad under Mount Hermon to the entrance of Hamath;'),
  ('b509edfb-48d2-5ee5-ae50-241c825256d7', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 6, 6, 'all the inhabitants of the hill country from Lebanon to Misrephoth Maim, even all the Sidonians; them will I drive out from before the children of Israel: only allocate it to Israel for an inheritance, as I have commanded you.'),
  ('45face1f-519e-5219-a346-a177d4e1f9d0', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 7, 7, 'Now therefore divide this land for an inheritance to the nine tribes and the half-tribe of Manasseh."'),
  ('368a1126-dd4b-5b0b-a4ba-836fceb08ed1', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 8, 8, 'With him the Reubenites and the Gadites received their inheritance, which Moses gave them, beyond the Jordan eastward, even as Moses the servant of Yahweh gave them:'),
  ('4b01dcff-c9af-56e0-a39e-376646b9f882', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 9, 9, 'from Aroer, that is on the edge of the valley of the Arnon, and the city that is in the middle of the valley, and all the plain of Medeba to Dibon;'),
  ('30a65273-f499-5bb3-a889-0eed0cf3deff', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 10, 10, 'and all the cities of Sihon king of the Amorites, who reigned in Heshbon, to the border of the children of Ammon;'),
  ('8ef54814-cad9-5091-a92c-6c453ebbf2a9', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 11, 11, 'and Gilead, and the border of the Geshurites and Maacathites, and all Mount Hermon, and all Bashan to Salecah;'),
  ('156595f5-ffb0-5ada-a002-df74248d2e26', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 12, 12, 'all the kingdom of Og in Bashan, who reigned in Ashtaroth and in Edrei (the same was left of the remnant of the Rephaim); for Moses attacked these, and drove them out.'),
  ('0ba18bb2-c82a-559c-ac32-b38f8188992d', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 13, 13, 'Nevertheless the children of Israel didn''t drive out the Geshurites, nor the Maacathites: but Geshur and Maacath dwell in the midst of Israel to this day.'),
  ('eb93f7c5-8113-5a65-a7bf-105a463a6cbe', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 14, 14, 'Only he gave no inheritance to the tribe of Levi. The offerings of Yahweh, the God of Israel, made by fire are his inheritance, as he spoke to him.'),
  ('7ab07e4d-a802-58cc-a4d6-8b72db4bc7a7', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 15, 15, 'Moses gave to the tribe of the children of Reuben according to their families.'),
  ('0395775d-8749-52ae-ab40-07af306850b6', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 16, 16, 'Their border was from Aroer, that is on the edge of the valley of the Arnon, and the city that is in the middle of the valley, and all the plain by Medeba;'),
  ('5360f00a-cf53-5e2b-a27d-6c0706f3d989', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 17, 17, 'Heshbon, and all its cities that are in the plain; Dibon, Bamoth Baal, Beth Baal Meon,'),
  ('ffa662e2-22bd-5c04-ad94-0cb9981580fc', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 18, 18, 'Jahaz, Kedemoth, Mephaath,'),
  ('c6d488ac-05a8-5335-ae57-6254ff278f83', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 19, 19, 'Kiriathaim, Sibmah, Zereth Shahar in the mount of the valley,'),
  ('aa06139c-39f2-5c3d-a246-e4e551c8b167', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 20, 20, 'Beth Peor, the slopes of Pisgah, Beth Jeshimoth,'),
  ('79d91df5-7fe3-5b03-a15a-9f468d029d36', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 21, 21, 'all the cities of the plain, and all the kingdom of Sihon king of the Amorites, who reigned in Heshbon, whom Moses struck with the chiefs of Midian, Evi, Rekem, Zur, Hur, and Reba, the princes of Sihon, who lived in the land.'),
  ('b1eedcf3-7e6e-5905-a52e-de2f459748fc', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 22, 22, 'The children of Israel alse killed Balaam also the son of Beor, the soothsayer, with the sword, among the rest of their slain.'),
  ('efd1654a-58c7-5207-af53-d3fc5245e898', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 23, 23, 'The border of the children of Reuben was the bank of the Jordan. This was the inheritance of the children of Reuben according to their families, the cities and its villages.'),
  ('7c7043bc-bf77-58bf-a806-0104b3c812db', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 24, 24, 'Moses gave to the tribe of Gad, to the children of Gad, according to their families.'),
  ('fd1cae65-c333-52e5-a911-160cd694cc29', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 25, 25, 'Their border was Jazer, and all the cities of Gilead, and half the land of the children of Ammon, to Aroer that is before Rabbah;'),
  ('58a5604d-6127-5029-ae8a-a78eb4b51d80', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 26, 26, 'and from Heshbon to Ramath Mizpeh, and Betonim; and from Mahanaim to the border of Debir;'),
  ('2683955d-c108-528a-af3d-a68e5d0fca1f', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 27, 27, 'and in the valley, Beth Haram, Beth Nimrah, Succoth, and Zaphon, the rest of the kingdom of Sihon king of Heshbon, the Jordan''s bank, to the uttermost part of the sea of Chinnereth beyond the Jordan eastward.'),
  ('e110ff62-6796-5f3c-aca9-3b692922e1f4', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 28, 28, 'This is the inheritance of the children of Gad according to their families, the cities and its villages.'),
  ('72cd333c-af14-5493-a8e7-8e9b8acd0fef', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 29, 29, 'Moses gave an inheritance to the half-tribe of Manasseh. It was for the half-tribe of the children of Manasseh according to their families.'),
  ('966f4536-8744-5908-a7ca-eb54d4756229', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 30, 30, 'Their border was from Mahanaim, all Bashan, all the kingdom of Og king of Bashan, and all the towns of Jair, which are in Bashan, sixty cities.'),
  ('47655b2c-b837-56e9-afff-67d59cb2615f', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 31, 31, 'Half Gilead, Ashtaroth, and Edrei, the cities of the kingdom of Og in Bashan, were for the children of Machir the son of Manasseh, even for the half of the children of Machir according to their families.'),
  ('20226e0c-dad8-5792-ae8b-9c5d39fe313f', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 32, 32, 'These are the inheritances which Moses distributed in the plains of Moab, beyond the Jordan at Jericho, eastward.'),
  ('9a2a60bf-e48a-5a06-a107-91170085ebfd', 'fc4efebd-1250-558a-ade1-2ac47e228d0c', NULL, 33, 33, 'But to the tribe of Levi Moses gave no inheritance. Yahweh, the God of Israel, is their inheritance, as he spoke to them.'),
  ('715409b4-628e-5d15-aaaf-0e003193cb91', '82583891-12dc-50de-a631-5f06855071dd', NULL, 1, 1, 'These are the inheritances which the children of Israel took in the land of Canaan, which Eleazar the priest, Joshua the son of Nun, and the heads of the fathers'' houses of the tribes of the children of Israel, distributed to them,'),
  ('84cea881-f4b1-5f13-ac9e-c2a577c7fb0d', '82583891-12dc-50de-a631-5f06855071dd', NULL, 2, 2, 'by the lot of their inheritance, as Yahweh commanded by Moses, for the nine tribes, and for the half-tribe.'),
  ('c82639d3-5b35-5e06-ac57-3987c92f84ba', '82583891-12dc-50de-a631-5f06855071dd', NULL, 3, 3, 'For Moses had given the inheritance of the two tribes and the half-tribe beyond the Jordan; but to the Levites he gave no inheritance among them.'),
  ('fd417a42-3aaf-5267-a22b-bffab6d4491f', '82583891-12dc-50de-a631-5f06855071dd', NULL, 4, 4, 'For the children of Joseph were two tribes, Manasseh and Ephraim: and they gave no portion to the Levites in the land, except cities to dwell in, with their suburbs for their livestock and for their property.'),
  ('b921cfcd-5d95-5832-ae9d-ce2340b93ece', '82583891-12dc-50de-a631-5f06855071dd', NULL, 5, 5, 'The children of Israel did as Yahweh commanded Moses, and they divided the land.'),
  ('3f3f1db4-328b-5d06-a3be-a611f26a5a8e', '82583891-12dc-50de-a631-5f06855071dd', NULL, 6, 6, 'Then the children of Judah drew near to Joshua in Gilgal. Caleb the son of Jephunneh the Kenizzite said to him, "You know the thing that Yahweh spoke to Moses the man of God concerning me and concerning you in Kadesh Barnea.'),
  ('4c18fd3e-5bbf-5da0-a2e0-a48a581b4379', '82583891-12dc-50de-a631-5f06855071dd', NULL, 7, 7, 'I was forty years old when Moses the servant of Yahweh sent me from Kadesh Barnea to spy out the land. I brought him word again as it was in my heart.'),
  ('aef30077-f2af-54c0-a808-0fd2bc5b5117', '82583891-12dc-50de-a631-5f06855071dd', NULL, 8, 8, 'Nevertheless, my brothers who went up with me made the heart of the people melt; but I wholly followed Yahweh my God.'),
  ('39867c49-42a0-5e7f-a22b-01efe6914aa9', '82583891-12dc-50de-a631-5f06855071dd', NULL, 9, 9, 'Moses swore on that day, saying, ''Surely the land where you walked shall be an inheritance to you and to your children forever, because you have wholly followed Yahweh my God.'''),
  ('afc34860-2f2c-599b-ac04-39f08ccc6986', '82583891-12dc-50de-a631-5f06855071dd', NULL, 10, 10, '"Now, behold, Yahweh has kept me alive, as he spoke, these forty-five years, from the time that Yahweh spoke this word to Moses, while Israel walked in the wilderness. Now, behold, I am eighty-five years old, today.'),
  ('58605cc7-bba2-5db5-acda-a34f38e03c5a', '82583891-12dc-50de-a631-5f06855071dd', NULL, 11, 11, 'As yet I am as strong today as I was in the day that Moses sent me: as my strength was then, even so is my strength now for war, to go out and to come in.'),
  ('d781b658-76cf-5a95-af36-7f35b330d368', '82583891-12dc-50de-a631-5f06855071dd', NULL, 12, 12, 'Now therefore give me this hill country, of which Yahweh spoke in that day; for you heard in that day how the Anakim were there, and great and fortified cities. It may be that Yahweh will be with me, and I shall drive them out, as Yahweh spoke."'),
  ('8cd82f8f-819e-52ea-a896-538c94a63d43', '82583891-12dc-50de-a631-5f06855071dd', NULL, 13, 13, 'Joshua blessed him; and he gave Hebron to Caleb the son of Jephunneh for an inheritance.'),
  ('d765379d-a4ef-5d62-ab53-3db5a09f84ce', '82583891-12dc-50de-a631-5f06855071dd', NULL, 14, 14, 'Therefore Hebron became the inheritance of Caleb the son of Jephunneh the Kenizzite to this day; because he wholly followed Yahweh, the God of Israel.'),
  ('6b854278-1c02-535d-a379-2db0cf8f4aaa', '82583891-12dc-50de-a631-5f06855071dd', NULL, 15, 15, 'Now the name of Hebron before was Kiriath Arba, after the greatest man among the Anakim. The land had rest from war.'),
  ('6dd8e82d-1f91-5a03-a9dc-c9c6a0b1113f', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 1, 1, 'The lot for the tribe of the children of Judah according to their families was to the border of Edom, even to the wilderness of Zin southward, at the uttermost part of the south.'),
  ('e2e17821-4036-5fe3-a871-888852e99768', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 2, 2, 'Their south border was from the uttermost part of the Salt Sea, from the bay that looks southward;'),
  ('0fe51a5b-e29e-5d27-a1ca-becd2a8186dd', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 3, 3, 'and it went out southward of the ascent of Akrabbim, and passed along to Zin, and went up by the south of Kadesh Barnea, and passed along by Hezron, went up to Addar, and turned about to Karka;'),
  ('8898cc88-2840-575f-af11-6136f9de0145', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 4, 4, 'and it passed along to Azmon, went out at the brook of Egypt; and the border ended at the sea. This shall be your south border.'),
  ('6ae46765-94bc-5729-a6f8-8b9193a31e19', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 5, 5, 'The east border was the Salt Sea, even to the end of the Jordan. The border of the north quarter was from the bay of the sea at the end of the Jordan.'),
  ('7de546eb-99d7-5cd1-a8e3-b8891faf84bc', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 6, 6, 'The border went up to Beth Hoglah, and passed along by the north of Beth Arabah; and the border went up to the stone of Bohan the son of Reuben.'),
  ('3a49b512-b0d3-5100-a899-2bf0c0329b17', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 7, 7, 'The border went up to Debir from the valley of Achor, and so northward, looking toward Gilgal, that is over against the ascent of Adummim, which is on the south side of the river. The border passed along to the waters of En Shemesh, and ended at En Rogel.'),
  ('dcda110c-84d8-5769-ac51-0fbc4a02ecf8', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 8, 8, 'The border went up by the valley of the son of Hinnom to the side of the Jebusite southward (the same is Jerusalem); and the border went up to the top of the mountain that lies before the valley of Hinnom westward, which is at the farthest part of the valley of Rephaim northward.'),
  ('6934e317-e5f6-5ac3-a4c0-236479bb1148', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 9, 9, 'The border extended from the top of the mountain to the spring of the waters of Nephtoah, and went out to the cities of Mount Ephron; and the border extended to Baalah (the same is Kiriath Jearim);'),
  ('dcf4343a-b56b-510c-a94c-65d47a0b07a3', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 10, 10, 'and the border turned about from Baalah westward to Mount Seir, and passed along to the side of Mount Jearim on the north (the same is Chesalon), and went down to Beth Shemesh, and passed along by Timnah;'),
  ('b36135e0-fbf1-5ebc-a362-7138a666ed54', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 11, 11, 'and the border went out to the side of Ekron northward; and the border extended to Shikkeron, and passed along to Mount Baalah, and went out at Jabneel; and the goings out of the border were at the sea.'),
  ('d0b4fb57-8f49-5a30-af15-4c563a57a57b', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 12, 12, 'The west border was to the shore of the great sea. This is the border of the children of Judah according to their families.'),
  ('2b497be6-2c90-5920-a139-89bdac839902', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 13, 13, 'To Caleb the son of Jephunneh he gave a portion among the children of Judah, according to the commandment of Yahweh to Joshua, even Kiriath Arba, named after the father of Anak (the same is Hebron).'),
  ('cc10330e-7c39-5b92-a305-20a8df345d08', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 14, 14, 'Caleb drove out the three sons of Anak: Sheshai, and Ahiman, and Talmai, the children of Anak.'),
  ('a73799a2-04f8-5362-a610-acf160fc2188', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 15, 15, 'He went up against the inhabitants of Debir: now the name of Debir before was Kiriath Sepher.'),
  ('5ea147a7-5877-57e2-aa9a-ded5584677d7', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 16, 16, 'Caleb said, "He who strikes Kiriath Sepher, and takes it, to him will I give Achsah my daughter as wife."'),
  ('345fdd5f-014b-50da-a316-859d648a5187', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 17, 17, 'Othniel the son of Kenaz, the brother of Caleb, took it: and he gave him Achsah his daughter as wife.'),
  ('653237c7-f9a2-5653-abea-7a0ef4fc0d33', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 18, 18, 'It happened, when she came, that she had him ask her father fore a field. She got off of her donkey, and Caleb said, "What do you want?"'),
  ('07e00cb1-590a-5dcc-ad21-ba1c7c23119a', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 19, 19, 'She said, "Give me a blessing. Because you have set me in the land of the South, give me also springs of water." He gave her the upper springs and the lower springs.'),
  ('f272c8c8-46e1-5fa8-a5e8-8e983647becd', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 20, 20, 'This is the inheritance of the tribe of the children of Judah according to their families.'),
  ('0818403e-ab23-5de9-a41b-b6b8c722a235', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 21, 21, 'The farthest cities of the tribe of the children of Judah toward the border of Edom in the South were Kabzeel, Eder, Jagur,'),
  ('ac3f9118-8ba9-5a5c-acf8-1287d419e882', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 22, 22, 'Kinah, Dimonah, Adadah,'),
  ('c73f3089-df80-5581-a601-fdbc909922ec', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 23, 23, 'Kedesh, Hazor, Ithnan,'),
  ('f1f4b16c-5239-5e67-a3a5-ff38cfdafa4d', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 24, 24, 'Ziph, Telem, Bealoth,'),
  ('b18ae29a-7096-5b66-a931-aac97d7ef63f', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 25, 25, 'Hazor Hadattah, Kerioth Hezron (the same is Hazor),'),
  ('448854d2-1136-569b-adce-21c3a0b8796c', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 26, 26, 'Amam, Shema, Moladah,'),
  ('6100b6a3-1b1e-590b-ae39-31a5040002a5', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 27, 27, 'Hazar Gaddah, Heshmon, Beth Pelet,'),
  ('2e6604d0-0e20-5490-ad82-239f804bcab3', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 28, 28, 'Hazar Shual, Beersheba, Biziothiah,'),
  ('d51996b6-70d4-52f0-aa0f-e3e313a98b72', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 29, 29, 'Baalah, Iim, Ezem,'),
  ('1c867b56-50dc-56bd-af30-da306f5b913b', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 30, 30, 'Eltolad, Chesil, Hormah,'),
  ('8ed46ecd-a85d-5d70-acb2-668728fd2a9c', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 31, 31, 'Ziklag, Madmannah, Sansannah,'),
  ('b143b8b1-e18b-592d-aac5-c46dbc102751', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 32, 32, 'Lebaoth, Shilhim, Ain, and Rimmon. All the cities are twenty-nine, with their villages.'),
  ('6668ba56-c7e5-550a-a25e-b3b8a30603e3', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 33, 33, 'In the lowland, Eshtaol, Zorah, Ashnah,'),
  ('496fae0b-e3e4-5f5d-ac4b-0707b7767076', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 34, 34, 'Zanoah, En Gannim, Tappuah, Enam,'),
  ('4c4786e1-1046-542d-a5e5-30ed1c23396a', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 35, 35, 'Jarmuth, Adullam, Socoh, Azekah,'),
  ('42651d55-60bd-54f1-aa5d-7032d9448cb9', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 36, 36, 'Shaaraim, Adithaim and Gederah (or Gederothaim); fourteen cities with their villages.'),
  ('4a2b55e6-a5ca-5f4a-a95e-0fc33df06276', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 37, 37, 'Zenan, Hadashah, Migdal Gad,'),
  ('604a6457-6c75-586a-a121-b0fe270927f6', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 38, 38, 'Dilean, Mizpeh, Joktheel,'),
  ('33584e21-352d-5afe-a105-6c0367cbc747', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 39, 39, 'Lachish, Bozkath, Eglon,'),
  ('b73469f6-7334-59f0-a118-4b4c47143f4b', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 40, 40, 'Cabbon, Lahmam, Chitlish,'),
  ('7f145dc9-bd6f-514a-a4b8-8b726cfd412e', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 41, 41, 'Gederoth, Beth Dagon, Naamah, and Makkedah; sixteen cities with their villages.'),
  ('a88234f6-0aee-53e1-a9b2-a5a9a6b1dfc6', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 42, 42, 'Libnah, Ether, Ashan,'),
  ('d6b2d99e-e0bb-525d-a5b3-05bfe511b357', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 43, 43, 'Iphtah, Ashnah, Nezib,'),
  ('935ea6fa-58b9-56db-a16d-c2b651b33ff2', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 44, 44, 'Keilah, Achzib, and Mareshah; nine cities with their villages.'),
  ('06c26ea8-6572-5a70-af1b-2f180f11f7ec', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 45, 45, 'Ekron, with its towns and its villages;'),
  ('1faf5c1c-6096-597b-a0e1-9617d910a18f', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 46, 46, 'from Ekron even to the sea, all that were by the side of Ashdod, with their villages.'),
  ('fd882ba8-7333-5bb6-a6b6-b9f96e91324d', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 47, 47, 'Ashdod, its towns and its villages; Gaza, its towns and its villages; to the brook of Egypt, and the great sea with its coastline.'),
  ('294ccad4-a493-5b2f-a314-8285ccaf9ab4', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 48, 48, 'In the hill country, Shamir, Jattir, Socoh,'),
  ('70cd6024-14de-5926-a877-88d75a1754f7', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 49, 49, 'Dannah, Kiriath Sannah (which is Debir),'),
  ('5350c74c-109f-561d-aa18-a84874f90801', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 50, 50, 'Anab, Eshtemoh, Anim,'),
  ('7134827d-7193-5217-a26e-2b8fa2c04606', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 51, 51, 'Goshen, Holon, and Giloh; eleven cities with their villages.'),
  ('941edac3-12e1-5e80-ac0f-d2780317035f', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 52, 52, 'Arab, Dumah, Eshan,'),
  ('6be09a6f-0d35-535d-a7de-b5f240aebcd5', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 53, 53, 'Janim, Beth Tappuah, Aphekah,'),
  ('6d483ca1-4f99-5185-aa2c-d4ca5faee35a', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 54, 54, 'Humtah, Kiriath Arba (the same is Hebron), and Zior; nine cities with their villages.'),
  ('1d42f83f-1e8d-5acd-a098-5424266b0253', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 55, 55, 'Maon, Carmel, Ziph, Jutah,'),
  ('8baf14e3-6be8-545d-a320-7c2314a66d3d', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 56, 56, 'Jezreel, Jokdeam, Zanoah,'),
  ('08c28455-dd2b-5989-a23c-80e7ca5f3d73', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 57, 57, 'Kain, Gibeah, and Timnah; ten cities with their villages.'),
  ('6498745c-be5f-5b4c-a518-9dfcd4d8d7c4', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 58, 58, 'Halhul, Beth Zur, Gedor,'),
  ('e766d975-7795-5df6-afc7-d6bf0306a59e', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 59, 59, 'Maarath, Beth Anoth, and Eltekon; six cities with their villages.'),
  ('1929d0ea-bfdf-530b-ad36-6c4d65f493e8', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 60, 60, 'Kiriath Baal (the same is Kiriath Jearim), and Rabbah; two cities with their villages.'),
  ('65e28267-e875-587e-a595-90cb75d09e4f', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 61, 61, 'In the wilderness, Beth Arabah, Middin, Secacah,'),
  ('84657bb2-8991-5f9b-a9a7-c3dbf09733b2', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 62, 62, 'Nibshan, the City of Salt, and En Gedi; six cities with their villages.'),
  ('6e0028be-c5bb-5879-abf3-6514334bf3b0', '7a4c5748-f0e8-582d-a87a-90e64b5a0d81', NULL, 63, 63, 'As for the Jebusites, the inhabitants of Jerusalem, the children of Judah couldn''t drive them out; but the Jebusites live with the children of Judah at Jerusalem to this day.'),
  ('32bd3442-80ee-515e-ad6f-2382d2f930d1', '6bb0c949-8920-578f-ac10-1337e4b1084d', NULL, 1, 1, 'The lot came out for the children of Joseph from the Jordan at Jericho, at the waters of Jericho on the east, even the wilderness, going up from Jericho through the hill country to Bethel.'),
  ('af0b7d51-d10b-5705-a558-85f3a15e1cd0', '6bb0c949-8920-578f-ac10-1337e4b1084d', NULL, 2, 2, 'It went out from Bethel to Luz, and passed along to the border of the Archites to Ataroth;'),
  ('9a7102a8-5bdc-5095-af73-b7d8df72ab6c', '6bb0c949-8920-578f-ac10-1337e4b1084d', NULL, 3, 3, 'and it went down westward to the border of the Japhletites, to the border of Beth Horon the lower, even to Gezer; and ended at the sea.'),
  ('a12ea001-5868-563f-a08f-1bab21884935', '6bb0c949-8920-578f-ac10-1337e4b1084d', NULL, 4, 4, 'The children of Joseph, Manasseh and Ephraim, took their inheritance.'),
  ('bc320a74-f81e-54c2-a922-2f49fa603c8f', '6bb0c949-8920-578f-ac10-1337e4b1084d', NULL, 5, 5, 'This was the border of the children of Ephraim according to their families. The border of their inheritance eastward was Ataroth Addar, to Beth Horon the upper.'),
  ('3a7a4942-3935-563f-aa93-bfee3e1bb42e', '6bb0c949-8920-578f-ac10-1337e4b1084d', NULL, 6, 6, 'The border went out westward at Michmethath on the north. The border turned about eastward to Taanath Shiloh, and passed along it on the east of Janoah.'),
  ('2adc7a28-a269-519e-aac4-62d7241b4024', '6bb0c949-8920-578f-ac10-1337e4b1084d', NULL, 7, 7, 'It went down from Janoah to Ataroth, to Naarah, reached to Jericho, and went out at the Jordan.'),
  ('1eb3fab8-8aa5-5b72-a474-d1142db5e6d1', '6bb0c949-8920-578f-ac10-1337e4b1084d', NULL, 8, 8, 'From Tappuah the border went along westward to the brook of Kanah; and ended at the sea. This is the inheritance of the tribe of the children of Ephraim according to their families;'),
  ('f08c68cd-e2e1-5402-a9ee-aa37ca6ec483', '6bb0c949-8920-578f-ac10-1337e4b1084d', NULL, 9, 9, 'together with the cities which were set apart for the children of Ephraim in the midst of the inheritance of the children of Manasseh, all the cities with their villages.'),
  ('a7ae5b8f-5c75-5b93-a71d-01acfd95c416', '6bb0c949-8920-578f-ac10-1337e4b1084d', NULL, 10, 10, 'They didn''t drive out the Canaanites who lived in Gezer; but the Canaanites dwell in the midst of Ephraim to this day, and have become servants to do forced labor.'),
  ('ecfb77ee-1224-5854-a136-c87bfc71a968', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 1, 1, 'This was the lot for the tribe of Manasseh, for he was the firstborn of Joseph. As for Machir the firstborn of Manasseh, the father of Gilead, because he was a man of war, therefore he had Gilead and Bashan.'),
  ('88055311-e497-5cbf-a1cf-bb4f4fb0c61e', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 2, 2, 'So this was for the rest of the children of Manasseh according to their families: for the children of Abiezer, for the children of Helek, for the children of Asriel, for the children of Shechem, for the children of Hepher, and for the children of Shemida: these were the male children of Manasseh the son of Joseph according to their families.'),
  ('f3185869-c2bc-505b-ac25-1e199ba69a0c', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 3, 3, 'But Zelophehad, the son of Hepher, the son of Gilead, the son of Machir, the son of Manasseh, had no sons, but daughters: and these are the names of his daughters: Mahlah, Noah, Hoglah, Milcah, and Tirzah.'),
  ('eacf10f8-4083-50c3-a538-f4cf1020f12d', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 4, 4, 'They came near before Eleazar the priest, and before Joshua the son of Nun, and before the princes, saying, "Yahweh commanded Moses to give us an inheritance among our brothers." Therefore according to the commandment of Yahweh he gave them an inheritance among the brothers of their father.'),
  ('36f94994-5554-5c53-ae23-db76485e828c', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 5, 5, 'Ten parts fell to Manasseh, besides the land of Gilead and Bashan, which is beyond the Jordan;'),
  ('6f54e348-f491-5f4a-a2a0-fa8278ef52e0', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 6, 6, 'because the daughters of Manasseh had an inheritance among his sons. The land of Gilead belonged to the rest of the sons of Manasseh.'),
  ('15e74ec0-95cb-52cb-ab8c-d48baa22d300', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 7, 7, 'The border of Manasseh was from Asher to Michmethath, which is before Shechem. The border went along to the right hand, to the inhabitants of En Tappuah.'),
  ('5c4ce15f-cd7a-5f32-ab8e-3915c33fa3bb', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 8, 8, 'The land of Tappuah belonged to Manasseh; but Tappuah on the border of Manasseh belonged to the children of Ephraim.'),
  ('8f5c7c79-4110-5a8b-af74-c616bc40273a', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 9, 9, 'The border went down to the brook of Kanah, southward of the brook. These cities belonged to Ephraim among the cities of Manasseh. The border of Manasseh was on the north side of the brook, and ended at the sea.'),
  ('667707fe-736a-5cd4-a220-a08f911b3eaf', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 10, 10, 'Southward it was Ephraim''s, and northward it was Manasseh''s, and the sea was his border. They reached to Asher on the north, and to Issachar on the east.'),
  ('5c426d16-288d-5652-a273-6ac7eec8a7e2', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 11, 11, 'Manasseh had three heights in Issachar, in Asher Beth Shean and its towns, and Ibleam and its towns, and the inhabitants of Dor and its towns, and the inhabitants of Endor and its towns, and the inhabitants of Taanach and its towns, and the inhabitants of Megiddo and its towns.'),
  ('db05c5b0-d70c-5f10-ae6a-38266473b11c', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 12, 12, 'Yet the children of Manasseh couldn''t drive out the inhabitants of those cities; but the Canaanites would dwell in that land.'),
  ('87c29904-f0fd-5450-ae54-e444f8a0a844', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 13, 13, 'It happened, when the children of Israel had grown strong, that they put the Canaanites to forced labor, and didn''t utterly drive them out.'),
  ('9144dc4c-82d8-556b-af4d-f92bc1cf4774', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 14, 14, 'The children of Joseph spoke to Joshua, saying, "Why have you given me just one lot and one part for an inheritance, since I am a great people, because Yahweh has blessed me so far?"'),
  ('4dff09b2-7ac4-5ee1-a357-acde765d7c4f', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 15, 15, 'Joshua said to them, "If you are a great people, go up to the forest, and clear land for yourself there in the land of the Perizzites and of the Rephaim; since the hill country of Ephraim is too narrow for you."'),
  ('ca8987d8-a1a8-5974-a9b9-9afdc42a4e5c', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 16, 16, 'The children of Joseph said, "The hill country is not enough for us. All the Canaanites who dwell in the land of the valley have chariots of iron, both those who are in Beth Shean and its towns, and those who are in the valley of Jezreel."'),
  ('6c158fe1-bde9-503b-a878-d4f26e0867f5', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 17, 17, 'Joshua spoke to the house of Joseph, even to Ephraim and to Manasseh, saying, "You are a great people, and have great power. You shall not have one lot only;'),
  ('c9157924-a71c-5aa4-a07a-5094ab1f8586', 'd1e265d3-9f4b-5d2d-a435-208d25b6f2d8', NULL, 18, 18, 'but the hill country shall be yours. Although it is a forest, you shall cut it down, and it''s farthest extent shall be yours; for you shall drive out the Canaanites, though they have chariots of iron, and though they are strong."'),
  ('d6065eb9-1c0c-5f68-a47c-2e96c7c9a47d', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 1, 1, 'The whole congregation of the children of Israel assembled themselves together at Shiloh, and set up the Tent of Meeting there. The land was subdued before them.'),
  ('4a42357b-bc60-5b30-a470-760a190e95da', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 2, 2, 'Seven tribes remained among the children of Israel, which had not yet divided their inheritance.'),
  ('bb02f9a7-d041-5c38-ac0a-3ea6bd974a01', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 3, 3, 'Joshua said to the children of Israel, "How long will you neglect to go in to possess the land, which Yahweh, the God of your fathers, has given you?'),
  ('a0d37239-e25b-56b0-a8d3-6d16431d5212', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 4, 4, 'Appoint for yourselves three men from each tribe. I will send them, and they shall arise, walk through the land, and describe it according to their inheritance; and they shall come to me.'),
  ('87809270-dcc7-5256-a463-9ed5c31894f8', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 5, 5, 'They shall divide it into seven portions. Judah shall live in his borders on the south, and the house of Joseph shall live in their borders on the north.'),
  ('358b3ef4-7624-5427-a8f1-175c8370b0c5', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 6, 6, 'You shall survey the land into seven parts, and bring the description here to me; and I will cast lots for you here before Yahweh our God.'),
  ('74ff0a2e-ba1d-55aa-ae21-8283981fbdee', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 7, 7, 'For the Levites have no portion among you; for the priesthood of Yahweh is their inheritance. Gad, Reuben, and the half-tribe of Manasseh have received their inheritance beyond the Jordan eastward, which Moses the servant of Yahweh gave them."'),
  ('d045a81b-ca1f-5481-af30-7b5382ca00a5', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 8, 8, 'The men arose and went. Joshua commanded those who went to survey the land, saying, "Go walk through the land, survey it, and come again to me. I will cast lots for you here before Yahweh in Shiloh."'),
  ('4895a204-91be-580a-aea4-f6d9d54c4981', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 9, 9, 'The men went and passed through the land, and surveyed it by cities into seven portions in a book. They came to Joshua to the camp at Shiloh.'),
  ('8f158458-41f4-5384-a3ef-85ae0020dd25', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 10, 10, 'Joshua cast lots for them in Shiloh before Yahweh. There Joshua divided the land to the children of Israel according to their divisions.'),
  ('81329511-c9e3-5cb1-a75d-7139691da933', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 11, 11, 'The lot of the tribe of the children of Benjamin came up according to their families. The border of their lot went out between the children of Judah and the children of Joseph.'),
  ('fcadcfda-55ae-5b71-a11e-024e926900c2', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 12, 12, 'Their border on the north quarter was from the Jordan. The border went up to the side of Jericho on the north, and went up through the hill country westward. It ended at the wilderness of Beth Aven.'),
  ('22dc6af8-e9d0-5455-a439-c432bca91d39', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 13, 13, 'The border passed along from there to Luz, to the side of Luz (the same is Bethel), southward. The border went down to Ataroth Addar, by the mountain that lies on the south of Beth Horon the lower.'),
  ('390824fd-98ac-51e8-a9c1-c93093d6510d', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 14, 14, 'The border extended, and turned around on the west quarter southward, from the mountain that lies before Beth Horon southward; and ended at Kiriath Baal (the same is Kiriath Jearim), a city of the children of Judah. This was the west quarter.'),
  ('0cc020da-75d5-5e55-a59c-3153cb421f25', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 15, 15, 'The south quarter was from the farthest part of Kiriath Jearim. The border went out westward, and went out to the spring of the waters of Nephtoah.'),
  ('3344a18e-801c-501d-a2af-0fad1de157e8', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 16, 16, 'The border went down to the farthest part of the mountain that lies before the valley of the son of Hinnom, which is in the valley of Rephaim northward. It went down to the valley of Hinnom, to the side of the Jebusite southward, and went down to En Rogel.'),
  ('51d49764-1b77-5628-a5dd-53d750831879', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 17, 17, 'It extended northward, went out at En Shemesh, and went out to Geliloth, which is over against the ascent of Adummim. It went down to the stone of Bohan the son of Reuben.'),
  ('81668ac7-e14c-5fb3-a8ba-61b74c8ed04b', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 18, 18, 'It passed along to the side over against the Arabah northward, and went down to the Arabah.'),
  ('cfbf23cf-4f0b-5b6f-acc0-40ea3385cc30', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 19, 19, 'The border passed along to the side of Beth Hoglah northward; and the border ended at the north bay of the Salt Sea, at the south end of the Jordan. This was the south border.'),
  ('408e23d7-0ec9-5d5a-afe3-b78b10f0d55d', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 20, 20, 'The Jordan was its border on the east quarter. This was the inheritance of the children of Benjamin, by the borders around it, according to their families.'),
  ('ff16fb8c-dea0-5d64-a353-e8629512b803', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 21, 21, 'Now the cities of the tribe of the children of Benjamin according to their families were Jericho, Beth Hoglah, Emek Keziz,'),
  ('5194360b-0a09-5ead-a2f7-e76a0086685f', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 22, 22, 'Beth Arabah, Zemaraim, Bethel,'),
  ('1da2168a-295c-5754-a3e8-f9b005008dea', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 23, 23, 'Avvim, Parah, Ophrah,'),
  ('7059ebb4-a79c-51bc-a9fb-156303f95135', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 24, 24, 'Chephar Ammoni, Ophni, and Geba; twelve cities with their villages.'),
  ('755b8830-9f2d-5b22-a39e-4a3d56e8c9b1', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 25, 25, 'Gibeon, Ramah, Beeroth,'),
  ('d48e9fbc-2924-5ac0-abcb-6c1d97d7e863', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 26, 26, 'Mizpeh, Chephirah, Mozah,'),
  ('efb911ec-b25c-5e18-a783-90b1328b316b', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 27, 27, 'Rekem, Irpeel, Taralah,'),
  ('d1cdf8b2-e076-5906-a623-8ddefdb23284', 'ef122f7a-97e7-5fd8-a918-9d6a25404a2d', NULL, 28, 28, 'Zelah, Eleph, the Jebusite (the same is Jerusalem), Gibeath, and Kiriath; fourteen cities with their villages. This is the inheritance of the children of Benjamin according to their families.'),
  ('de7ed9eb-ad6f-5952-afb1-36d0d5850fb4', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 1, 1, 'The second lot came out for Simeon, even for the tribe of the children of Simeon according to their families. Their inheritance was in the midst of the inheritance of the children of Judah.'),
  ('b066fc05-cca4-517d-a129-f4e4821283b8', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 2, 2, 'They had for their inheritance Beersheba (or Sheba), Moladah,'),
  ('2de21e37-6df7-53cb-a07a-85363d94da22', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 3, 3, 'Hazar Shual, Balah, Ezem,'),
  ('4739c866-7ab2-54c3-a7a6-5d632caa40af', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 4, 4, 'Eltolad, Bethul, Hormah,'),
  ('2ead1d0a-09ac-5c65-ae47-8960e719ac3e', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 5, 5, 'Ziklag, Beth Marcaboth, Hazar Susah,'),
  ('1151509b-3e16-5d86-adda-8534cb7e5e31', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 6, 6, 'Beth Lebaoth, and Sharuhen; thirteen cities with their villages;'),
  ('c525e226-10a5-5f61-abab-1214c2b9fe10', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 7, 7, 'Ain, Rimmon, Ether, and Ashan; four cities with their villages;'),
  ('05bdb474-fc29-5436-a07c-4f3d4b8c4680', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 8, 8, 'and all the villages that were around these cities to Baalath Beer, Ramah of the South. This is the inheritance of the tribe of the children of Simeon according to their families.'),
  ('6208ba98-f011-5060-a522-d87400f67ee4', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 9, 9, 'Out of the part of the children of Judah was the inheritance of the children of Simeon; for the portion of the children of Judah was too much for them. Therefore the children of Simeon had inheritance in the midst of their inheritance.'),
  ('5c1f066f-ad27-5955-a0f5-622b46b41c71', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 10, 10, 'The third lot came up for the children of Zebulun according to their families. The border of their inheritance was to Sarid.'),
  ('66fb231f-2dae-5a12-a18b-3a773362a96b', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 11, 11, 'Their border went up westward, even to Maralah, and reached to Dabbesheth. It reached to the brook that is before Jokneam.'),
  ('bf6ceb14-a914-5402-ae57-ab531418ff6e', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 12, 12, 'It turned from Sarid eastward toward the sunrise to the border of Chisloth Tabor. It went out to Daberath, and went up to Japhia.'),
  ('f9145233-5459-5e00-aa7d-34d73bd74dae', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 13, 13, 'From there it passed along eastward to Gath Hepher, to Ethkazin; and it went out at Rimmon which stretches to Neah.'),
  ('f1aef082-1b7c-508d-a700-0b9b410f792f', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 14, 14, 'The border turned around it on the north to Hannathon; and it ended at the valley of Iphtah El;'),
  ('de30b180-64e4-5e26-a4a6-b90989aba251', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 15, 15, 'Kattath, Nahalal, Shimron, Idalah, and Bethlehem: twelve cities with their villages.'),
  ('c6acc02a-c57e-5a23-a969-3eaec4d54110', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 16, 16, 'This is the inheritance of the children of Zebulun according to their families, these cities with their villages.'),
  ('9ee8f747-4b7c-526a-a2b4-7b65042677f7', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 17, 17, 'The fourth lot came out for Issachar, even for the children of Issachar according to their families.'),
  ('cbd551e5-0251-5b1b-a62e-d933d33fab76', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 18, 18, 'Their border was to Jezreel, Chesulloth, Shunem,'),
  ('0ce3dd04-559f-5b1e-a57b-be42f4698577', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 19, 19, 'Hapharaim, Shion, Anaharath,'),
  ('e4c92719-c22b-56ac-abc1-4ff51a2f714d', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 20, 20, 'Rabbith, Kishion, Ebez,'),
  ('ee81b78e-8265-590e-a998-9080b9d15d08', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 21, 21, 'Remeth, Engannim, En Haddah, and Beth Pazzez.'),
  ('304a75b5-fb3f-551a-a264-7cc8f51b076b', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 22, 22, 'The border reached to Tabor, Shahazumah, and Beth Shemesh. Their border ended at the Jordan: sixteen cities with their villages.'),
  ('03392454-223e-5eb9-a788-25da62ed227b', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 23, 23, 'This is the inheritance of the tribe of the children of Issachar according to their families, the cities with their villages.'),
  ('f0c0e9d1-162b-5115-ad4b-6585fad63b19', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 24, 24, 'The fifth lot came out for the tribe of the children of Asher according to their families.'),
  ('07dca609-0ca1-565f-a7a9-80ce9f7dccad', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 25, 25, 'Their border was Helkath, Hali, Beten, Achshaph,'),
  ('ecee8524-b55a-5e24-a57a-ef56ff65ce4b', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 26, 26, 'Allammelech, Amad, Mishal. It reached to Carmel westward, and to Shihorlibnath.'),
  ('220b82ff-1c01-500b-a27c-d1ea61b8ac80', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 27, 27, 'It turned toward the sunrise to Beth Dagon, and reached to Zebulun, and to the valley of Iphtah El northward to Beth Emek and Neiel. It went out to Cabul on the left hand,'),
  ('37f319f8-7289-50dd-a3da-6ab252d9066f', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 28, 28, 'and Ebron, Rehob, Hammon, and Kanah, even to great Sidon.'),
  ('dc1bcab6-059e-5f9c-a126-fbcc5b194604', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 29, 29, 'The border turned to Ramah, to the fortified city of Tyre; and the border turned to Hosah. It ended at the sea by the region of Achzib;'),
  ('74cb493f-7036-51da-a750-75064aa11dac', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 30, 30, 'Ummah also, and Aphek, and Rehob: twenty-two cities with their villages.'),
  ('a025fa4a-49cb-5328-a5f5-2ea377ac4645', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 31, 31, 'This is the inheritance of the tribe of the children of Asher according to their families, these cities with their villages.'),
  ('f91d50e6-3827-51b8-a55f-c07fbd9deea1', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 32, 32, 'The sixth lot came out for the children of Naphtali, even for the children of Naphtali according to their families.'),
  ('99f4c40d-3f05-5370-a353-0772fc716acf', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 33, 33, 'Their border was from Heleph, from the oak in Zaanannim, Adaminekeb, and Jabneel, to Lakkum. It ended at the Jordan.'),
  ('5d57620a-a887-5a72-ace2-6143d4e501ec', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 34, 34, 'The border turned westward to Aznoth Tabor, and went out from there to Hukkok. It reached to Zebulun on the south, and reached to Asher on the west, and to Judah at the Jordan toward the sunrise.'),
  ('0b61a9a7-33f0-56d9-a5d0-e36b1725ec84', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 35, 35, 'The fortified cities were Ziddim, Zer, Hammath, Rakkath, Chinnereth,'),
  ('dfdcc335-911d-5f84-a5fb-78b59cadb91f', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 36, 36, 'Adamah, Ramah, Hazor,'),
  ('6f895ba0-edf0-56db-a097-0f14c195f8bc', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 37, 37, 'Kedesh, Edrei, En Hazor,'),
  ('5e653344-4df5-5e5c-a984-b1a0e4e8ecc8', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 38, 38, 'Iron, Migdal El, Horem, Beth Anath, and Beth Shemesh; nineteen cities with their villages.'),
  ('690a7751-b6e7-589c-a564-f241db40a378', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 39, 39, 'This is the inheritance of the tribe of the children of Naphtali according to their families, the cities with their villages.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('43de6b57-b772-5ac2-af25-31e865e79b86', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 40, 40, 'The seventh lot came out for the tribe of the children of Dan according to their families.'),
  ('9e655092-725e-5577-a76a-cc6024e16040', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 41, 41, 'The border of their inheritance was Zorah, Eshtaol, Irshemesh,'),
  ('d962dad4-c812-5885-a0e6-5f6dd020d5b2', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 42, 42, 'Shaalabbin, Aijalon, Ithlah,'),
  ('380ce720-b878-5c75-a28e-05223a92c046', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 43, 43, 'Elon, Timnah, Ekron,'),
  ('49d2fb74-591a-5217-a531-e5ae26473a15', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 44, 44, 'Eltekeh, Gibbethon, Baalath,'),
  ('c40b07c4-352f-5056-a41b-2784510dc0ad', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 45, 45, 'Jehud, Bene Berak, Gath Rimmon,'),
  ('93ee2f26-b15c-51f9-ab10-672518500f73', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 46, 46, 'Me Jarkon, and Rakkon, with the border over against Joppa.'),
  ('77d2e40a-0c7b-5330-a18a-20edefb0d4e6', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 47, 47, 'The border of the children of Dan went out beyond them; for the children of Dan went up and fought against Leshem, and took it, and struck it with the edge of the sword, and possessed it, and lived therein, and called Leshem, Dan, after the name of Dan their father.'),
  ('c96fadf1-ea00-5396-aa34-a884e3fdfdb0', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 48, 48, 'This is the inheritance of the tribe of the children of Dan according to their families, these cities with their villages.'),
  ('8740167b-70cb-55ca-a40b-bd2f41ad3900', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 49, 49, 'So they made an end of distributing the land for inheritance by its borders. The children of Israel gave an inheritance to Joshua the son of Nun in the midst of them.'),
  ('d5514c4e-b6de-5546-a4b8-b968e3b5bb6d', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 50, 50, 'According to the commandment of Yahweh, they gave him the city which he asked, even Timnathserah in the hill country of Ephraim; and he built the city, and lived there.'),
  ('c3f3b8e7-c953-5456-acb5-f8ae1dcf7ca4', '8c77ccc9-bb02-58d4-ae1b-b3d84f632c9f', NULL, 51, 51, 'These are the inheritances, which Eleazar the priest, Joshua the son of Nun, and the heads of the fathers'' houses of the tribes of the children of Israel, distributed for inheritance by lot in Shiloh before Yahweh, at the door of the Tent of Meeting. So they made an end of dividing the land.'),
  ('2aa76fbb-2276-5b5f-adc5-aa73bd6d75b3', '4b1cc034-84fe-59a5-a933-af6f3b27e529', NULL, 1, 1, 'Yahweh spoke to Joshua, saying,'),
  ('1e2d3dd6-e468-5037-a7ec-1d0b059078dc', '4b1cc034-84fe-59a5-a933-af6f3b27e529', NULL, 2, 2, '"Speak to the children of Israel, saying, ''Assign the cities of refuge, of which I spoke to you by Moses,'),
  ('0eef6003-c633-58ef-a912-e99361ab4e0b', '4b1cc034-84fe-59a5-a933-af6f3b27e529', NULL, 3, 3, 'that the manslayer who kills any person accidentally or unintentionally may flee there. They shall be to you for a refuge from the avenger of blood.'),
  ('d219b1fc-33da-51ba-ad5a-cbac13933119', '4b1cc034-84fe-59a5-a933-af6f3b27e529', NULL, 4, 4, 'He shall flee to one of those cities, and shall stand at the entrance of the gate of the city, and declare his cause in the ears of the elders of that city. They shall take him into the city with them, and give him a place, that he may live among them.'),
  ('775d82e2-2724-5275-a5d9-d24e6ac8cac8', '4b1cc034-84fe-59a5-a933-af6f3b27e529', NULL, 5, 5, 'If the avenger of blood pursue after him, then they shall not deliver up the manslayer into his hand; because he struck his neighbor unintentionally, and didn''t hate him before.'),
  ('8eb59301-9e8f-5902-ac38-61c823a7e06f', '4b1cc034-84fe-59a5-a933-af6f3b27e529', NULL, 6, 6, 'He shall dwell in that city until he stands before the congregation for judgment, until the death of the high priest that shall be in those days. Then the manslayer shall return, and come to his own city, and to his own house, to the city he fled from.''"'),
  ('73d027d9-c0aa-5162-af1b-8cb8b8f1e2e0', '4b1cc034-84fe-59a5-a933-af6f3b27e529', NULL, 7, 7, 'They set apart Kedesh in Galilee in the hill country of Naphtali, Shechem in the hill country of Ephraim, and Kiriath Arba (the same is Hebron) in the hill country of Judah.'),
  ('b369e015-79c0-55a6-a982-77cf751825f4', '4b1cc034-84fe-59a5-a933-af6f3b27e529', NULL, 8, 8, 'Beyond the Jordan at Jericho eastward, they assigned Bezer in the wilderness in the plain out of the tribe of Reuben, Ramoth in Gilead out of the tribe of Gad, and Golan in Bashan out of the tribe of Manasseh.'),
  ('62fe765f-5380-5c51-a087-2e5831d5f20a', '4b1cc034-84fe-59a5-a933-af6f3b27e529', NULL, 9, 9, 'These were the appointed cities for all the children of Israel, and for the alien who lives among them, that whoever kills any person unintentionally might flee there, and not die by the hand of the avenger of blood, until he stands before the congregation.'),
  ('7b3ec159-c2ed-5684-a61e-6c928ae94d09', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 1, 1, 'Then the heads of fathers'' houses of the Levites came near to Eleazar the priest, and to Joshua the son of Nun, and to the heads of fathers'' houses of the tribes of the children of Israel.'),
  ('2d533ca3-b283-5885-ac93-31950ac18d25', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 2, 2, 'They spoke to them at Shiloh in the land of Canaan, saying, "Yahweh commanded Moses to give us cities to dwell in, with their suburbs for our livestock."'),
  ('c877a19d-341f-57c6-ab92-b1a76e7ed95b', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 3, 3, 'The children of Israel gave to the Levites out of their inheritance, according to the commandment of Yahweh, these cities with their suburbs.'),
  ('f94114d5-a293-5fc9-a6a1-05c1858e778c', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 4, 4, 'The lot came out for the families of the Kohathites. The children of Aaron the priest, who were of the Levites, had thirteen cities by lot out of the tribe of Judah, out of the tribe of the Simeonites, and out of the tribe of Benjamin.'),
  ('b07cafba-f0a4-56b3-ae51-f5df9aec3f87', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 5, 5, 'The rest of the children of Kohath had ten cities by lot out of the families of the tribe of Ephraim, out of the tribe of Dan, and out of the half-tribe of Manasseh.'),
  ('87e30311-67c1-503e-aa44-2142cf2d118c', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 6, 6, 'The children of Gershon had thirteen cities by lot out of the families of the tribe of Issachar, out of the tribe of Asher, out of the tribe of Naphtali, and out of the half-tribe of Manasseh in Bashan.'),
  ('db51fb11-1cc8-511e-a0f6-6f8806d6e8f3', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 7, 7, 'The children of Merari according to their families had twelve cities out of the tribe of Reuben, out of the tribe of Gad, and out of the tribe of Zebulun.'),
  ('c35aac00-1954-501f-afb0-e2e38ad5ef27', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 8, 8, 'The children of Israel gave these cities with their suburbs by lot to the Levites, as Yahweh commanded by Moses.'),
  ('bae6cb26-0996-56c0-af55-ef3ed572f6a3', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 9, 9, 'They gave out of the tribe of the children of Judah, and out of the tribe of the children of Simeon, these cities which are mentioned by name:'),
  ('df8e2c99-c883-59c2-a49b-44054029625d', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 10, 10, 'and they were for the children of Aaron, of the families of the Kohathites, who were of the children of Levi; for theirs was the first lot.'),
  ('6318bebc-949e-5a1c-a240-57d939c2d6a9', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 11, 11, 'They gave them Kiriath Arba, named after the father of Anak (the same is Hebron), in the hill country of Judah, with its suburbs around it.'),
  ('e8e1ba02-dee3-59c5-ab45-ce74a5de49e1', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 12, 12, 'But they gave the fields of the city and its villages to Caleb the son of Jephunneh for his possession.'),
  ('3ce46576-e4e2-5606-a77e-b05167884317', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 13, 13, 'To the children of Aaron the priest they gave Hebron with its suburbs, the city of refuge for the manslayer, Libnah with its suburbs,'),
  ('9ad10fbf-c7b2-590a-a748-5aaa163e1b0e', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 14, 14, 'Jattir with its suburbs, Eshtemoa with its suburbs,'),
  ('c4ae4bd5-a414-5c36-a526-68ef3ca9f1cb', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 15, 15, 'Holon with its suburbs, Debir with its suburbs,'),
  ('9375577c-df63-5293-a52f-79dc03ca2b8e', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 16, 16, 'Ain with its suburbs, Juttah with its suburbs, and Beth Shemesh with its suburbs; nine cities out of those two tribes.'),
  ('67e9a5de-cd16-5dcd-a844-a1074d06bfcb', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 17, 17, 'Out of the tribe of Benjamin, Gibeon with its suburbs, Geba with its suburbs,'),
  ('a28c50b0-f89d-54a7-a1dc-68038f6b70ba', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 18, 18, 'Anathoth with its suburbs, and Almon with its suburbs; four cities.'),
  ('8e4c2cb2-bd16-5eca-ad27-bb1a1a3ed4c6', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 19, 19, 'All the cities of the children of Aaron, the priests, were thirteen cities with their suburbs.'),
  ('0b15eca1-537f-5615-afe6-db2a589d779c', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 20, 20, 'The families of the children of Kohath, the Levites, even the rest of the children of Kohath, had the cities of their lot out of the tribe of Ephraim.'),
  ('b3f23536-4b23-51d2-a242-b16d2ec6c1ec', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 21, 21, 'They gave them Shechem with its suburbs in the hill country of Ephraim, the city of refuge for the manslayer, and Gezer with its suburbs,'),
  ('08916b18-556c-5d26-ab8c-2d2c32794c1c', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 22, 22, 'Kibzaim with its suburbs, and Beth Horon with its suburbs; four cities.'),
  ('1b1113a6-1735-5741-a111-0e284215414e', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 23, 23, 'Out of the tribe of Dan, Elteke with its suburbs, Gibbethon with its suburbs,'),
  ('17efa323-a12d-58a2-a851-293c9b26d9d7', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 24, 24, 'Aijalon with its suburbs, Gath Rimmon with its suburbs; four cities.'),
  ('979138e8-85cd-5261-a07f-0812e4da3a52', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 25, 25, 'Out of the half-tribe of Manasseh, Taanach with its suburbs, and Gath Rimmon with its suburbs; two cities.'),
  ('eeadfd13-cd76-5865-a2e5-58a8e0b49e07', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 26, 26, 'All the cities of the families of the rest of the children of Kohath were ten with their suburbs.'),
  ('f7288f42-588d-5f1a-acbd-c50e58555569', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 27, 27, 'They gave to the children of Gershon, of the families of the Levites, out of the half-tribe of Manasseh Golan in Bashan with its suburbs, the city of refuge for the manslayer, and Be Eshterah with its suburbs; two cities.'),
  ('b1c313a1-0ecc-539a-afa8-9f4543a09b0e', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 28, 28, 'Out of the tribe of Issachar, Kishion with its suburbs, Daberath with its suburbs,'),
  ('b70509d8-f613-525d-ae6b-d5e592afd786', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 29, 29, 'Jarmuth with its suburbs, En Gannim with its suburbs; four cities.'),
  ('f17530c0-f1e8-52d7-aa8e-22d82da6d86d', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 30, 30, 'Out of the tribe of Asher, Mishal with its suburbs, Abdon with its suburbs,'),
  ('163a9c4f-f070-5ded-a3d7-e082e87f7a1b', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 31, 31, 'Helkath with its suburbs, and Rehob with its suburbs; four cities.'),
  ('f10f433c-b412-5b53-aa64-febae4779ad8', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 32, 32, 'Out of the tribe of Naphtali, Kedesh in Galilee with its suburbs, the city of refuge for the manslayer, Hammothdor with its suburbs, and Kartan with its suburbs; three cities.'),
  ('acc14869-1fe7-5e8b-a22a-3e205830f847', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 33, 33, 'All the cities of the Gershonites according to their families were thirteen cities with their suburbs.'),
  ('6d8d0579-2947-50db-a984-e1177d7996c5', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 34, 34, 'To the families of the children of Merari, the rest of the Levites, out of the tribe of Zebulun, Jokneam with its suburbs, Kartah with its suburbs,'),
  ('ee18ef6c-580e-55d4-a2f5-7a013073c32b', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 35, 35, 'Dimnah with its suburbs, and Nahalal with its suburbs; four cities.'),
  ('65c8a3bd-97f8-5b52-a394-b6c500f8d67d', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 36, 36, 'Out of the tribe of Reuben, Bezer with its suburbs, Jahaz with its suburbs,'),
  ('8b2a8bc9-9f9d-5747-a79f-987ff67f920e', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 37, 37, 'Kedemoth with its suburbs, and Mephaath with its suburbs; four cities.'),
  ('f10a73e3-4601-5dfc-a4fd-8ed15710b255', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 38, 38, 'Out of the tribe of Gad, Ramoth in Gilead with its suburbs, the city of refuge for the manslayer, and Mahanaim with its suburbs,'),
  ('7a0b6d97-a6df-579a-a2df-26f7945c6694', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 39, 39, 'Heshbon with its suburbs, Jazer with its suburbs; four cities in all.'),
  ('3424ce5b-ef51-5401-aed1-0ec9d9ed83db', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 40, 40, 'All these were the cities of the children of Merari according to their families, even the rest of the families of the Levites. Their lot was twelve cities.'),
  ('06fc6eca-4f48-567d-a300-9d0233cd58d3', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 41, 41, 'All the cities of the Levites in the midst of the possession of the children of Israel were forty-eight cities with their suburbs.'),
  ('00636a12-a35f-5485-acd8-2ccc86f6cd47', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 42, 42, 'Each of these cities included their suburbs around them. It was this way with all these cities.'),
  ('b0122dbb-5a09-5bb0-a9c9-526da748d8e0', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 43, 43, 'So Yahweh gave to Israel all the land which he swore to give to their fathers. They possessed it, and lived in it.'),
  ('e7fa4525-5c0d-5efe-a663-b2dc42146d7d', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 44, 44, 'Yahweh gave them rest all around, according to all that he swore to their fathers. Not a man of all their enemies stood before them. Yahweh delivered all their enemies into their hand.'),
  ('2374d0bd-592b-5183-af3e-3963b21583c7', '205e5e16-380a-5777-a145-3cd3733ac839', NULL, 45, 45, 'Nothing failed of any good thing which Yahweh had spoken to the house of Israel. All came to pass.'),
  ('ab69a64b-5c21-5ce4-a0f5-fcc0b89fc9de', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 1, 1, 'Then Joshua called the Reubenites, the Gadites, and the half-tribe of Manasseh,'),
  ('caab73dd-2f07-52a0-a8d6-307eeac16181', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 2, 2, 'and said to them, "You have kept all that Moses the servant of Yahweh commanded you, and have listened to my voice in all that I commanded you.'),
  ('2cab8a37-4675-53e3-a8a3-b2b56561e16f', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 3, 3, 'You have not left your brothers these many days to this day, but have performed the duty of the commandment of Yahweh your God.'),
  ('c9b7b501-1c9a-5be8-afae-b720fb20d98b', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 4, 4, 'Now Yahweh your God has given rest to your brothers, as he spoke to them. Therefore now return and go to your tents, to the land of your possession, which Moses the servant of Yahweh gave you beyond the Jordan.'),
  ('5da5d8eb-3579-5632-aa9b-ab4c9f53d1c2', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 5, 5, 'Only take diligent heed to do the commandment and the law which Moses the servant of Yahweh commanded you, to love Yahweh your God, to walk in all his ways, to keep his commandments, to hold fast to him, and to serve him with all your heart and with all your soul."'),
  ('df0c0d0e-1575-57d1-a80a-9ed944560bc3', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 6, 6, 'So Joshua blessed them, and sent them away; and they went to their tents.'),
  ('0db5511b-82cc-5992-acaf-747335601710', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 7, 7, 'Now to the one half-tribe of Manasseh Moses had given inheritance in Bashan; but to the other half gave Joshua among their brothers beyond the Jordan westward. Moreover when Joshua sent them away to their tents, he blessed them,'),
  ('9d2b8963-260d-528d-a1c3-61818133668c', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 8, 8, 'and spoke to them, saying, "Return with much wealth to your tents, with very much livestock, with silver, with gold, with brass, with iron, and with very much clothing. Divide the spoil of your enemies with your brothers."'),
  ('5ee28e15-16b1-5878-a618-39a0b7253505', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 9, 9, 'The children of Reuben and the children of Gad and the half-tribe of Manasseh returned, and departed from the children of Israel out of Shiloh, which is in the land of Canaan, to go to the land of Gilead, to the land of their possession, which they owned, according to the commandment of Yahweh by Moses.'),
  ('5bbae6dc-e24f-56f5-a593-714fb785f9de', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 10, 10, 'When they came to the region about the Jordan, that is in the land of Canaan, the children of Reuben and the children of Gad and the half-tribe of Manasseh built there an altar by the Jordan, a great altar to look at.'),
  ('30e7074a-583d-5d7e-a0b8-2c892ff1e126', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 11, 11, 'The children of Israel heard this, "Behold, the children of Reuben and the children of Gad and the half-tribe of Manasseh have built an altar in the forefront of the land of Canaan, in the region about the Jordan, on the side that pertains to the children of Israel."'),
  ('69ca78be-baea-53fb-ae97-2bd9d3922a1b', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 12, 12, 'When the children of Israel heard of it, the whole congregation of the children of Israel gathered themselves together at Shiloh, to go up against them to war.'),
  ('9dcb6a3f-46bb-56ee-a8db-a3eb1f14b97f', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 13, 13, 'The children of Israel sent to the children of Reuben, and to the children of Gad, and to the half-tribe of Manasseh, into the land of Gilead, Phinehas the son of Eleazar the priest,'),
  ('62ecdf47-841e-5877-a607-9bda6c325c4a', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 14, 14, 'and with him ten princes, one prince of a fathers'' house for each of the tribes of Israel; and they were everyone of them head of their fathers'' houses among the thousands of Israel.'),
  ('8e3d2fda-cfb1-5e58-ac47-f1e1fbee9eb4', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 15, 15, 'They came to the children of Reuben, and to the children of Gad, and to the half-tribe of Manasseh, to the land of Gilead, and they spoke with them, saying,'),
  ('db77e54f-e0ff-5287-a8eb-25e67c693d62', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 16, 16, '"Thus says the whole congregation of Yahweh, ''What trespass is this that you have committed against the God of Israel, to turn away this day from following Yahweh, in that you have built you an altar, to rebel this day against Yahweh?'),
  ('4ade59c4-806c-5cfd-ae36-b6458f35a206', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 17, 17, 'Is the iniquity of Peor too little for us, from which we have not cleansed ourselves to this day, although there came a plague on the congregation of Yahweh,'),
  ('c1b6b332-ad78-5c43-a794-1185616a7da8', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 18, 18, 'that you must turn away this day from following Yahweh? It will be, since you rebel today against Yahweh, that tomorrow he will be angry with the whole congregation of Israel.'),
  ('92d19965-6f94-5731-a0dd-2d06aedf2442', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 19, 19, 'However, if the land of your possession is unclean, then pass over to the land of the possession of Yahweh, in which Yahweh''s tabernacle dwells, and take possession among us; but don''t rebel against Yahweh, nor rebel against us, in building an altar other than the altar of Yahweh our God.'),
  ('f3a6b066-14a8-5d06-a0d2-4ca6ed2ecdda', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 20, 20, 'Didn''t Achan the son of Zerah commit a trespass in the devoted thing, and wrath fell on all the congregation of Israel? That man didn''t perish alone in his iniquity.''"'),
  ('480d8ed9-933c-5d25-ae29-36dd3bb8a262', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 21, 21, 'Then the children of Reuben and the children of Gad and the half-tribe of Manasseh answered, and spoke to the heads of the thousands of Israel,'),
  ('33f6ede2-76b1-55ad-a0cd-8492da41ccc8', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 22, 22, '"The Mighty One, God, Yahweh, the Mighty One, God, Yahweh, he knows; and Israel shall know: if it was in rebellion, or if in trespass against Yahweh (don''t save us this day),'),
  ('63e923cc-2222-5036-a7e9-1fd704294dc8', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 23, 23, 'that we have built us an altar to turn away from following Yahweh; or if to offer burnt offering or meal offering, or if to offer sacrifices of peace offerings, let Yahweh himself require it.'),
  ('6f49b7de-83b2-5ad6-a996-4b0f10716f19', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 24, 24, '"If we have not out of concern done this, and for a reason, saying, ''In time to come your children might speak to our children, saying, "What have you to do with Yahweh, the God of Israel?'),
  ('a58b6dad-82d8-50a1-a0a0-68e6c4c789f4', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 25, 25, 'For Yahweh has made the Jordan a border between us and you, you children of Reuben and children of Gad. You have no portion in Yahweh."'' So your children might make our children cease from fearing Yahweh.'),
  ('aaa6d364-f930-53af-a194-a9a7bf3a2317', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 26, 26, '"Therefore we said, ''Let''s now prepare to build ourselves an altar, not for burnt offering, nor for sacrifice;'),
  ('b58f10a0-84ff-5d3a-a1b2-ea4a7ae8966c', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 27, 27, 'but it will be a witness between us and you, and between our generations after us, that we may perform the service of Yahweh before him with our burnt offerings, with our sacrifices, and with our peace offerings;'' that your children may not tell our children in time to come, ''You have no portion in Yahweh.'''),
  ('3d63d290-ecaa-5d11-a63e-8aca3cae9022', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 28, 28, '"Therefore we said, ''It shall be, when they tell us or our generations this in time to come, that we shall say, "Behold the pattern of the altar of Yahweh, which our fathers made, not for burnt offering, nor for sacrifice; but it is a witness between us and you."'''),
  ('36b85414-cbc4-5040-a09c-ef3154c79bb7', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 29, 29, '"Far be it from us that we should rebel against Yahweh, and turn away this day from following Yahweh, to build an altar for burnt offering, for meal offering, or for sacrifice, besides the altar of Yahweh our God that is before his tabernacle!"'),
  ('392973dc-4bc0-5073-aa00-934fdc2f3502', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 30, 30, 'When Phinehas the priest, and the princes of the congregation, even the heads of the thousands of Israel that were with him, heard the words that the children of Reuben and the children of Gad and the children of Manasseh spoke, it pleased them well.'),
  ('6cb81078-cc59-559a-a0cb-7a4717b38047', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 31, 31, 'Phinehas the son of Eleazar the priest said to the children of Reuben, to the children of Gad, and to the children of Manasseh, "Today we know that Yahweh is in the midst of us, because you have not committed this trespass against Yahweh. Now you have delivered the children of Israel out of the hand of Yahweh."'),
  ('8f497d21-5c7a-5398-afaa-eafa94b3ba48', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 32, 32, 'Phinehas the son of Eleazar the priest, and the princes, returned from the children of Reuben, and from the children of Gad, out of the land of Gilead, to the land of Canaan, to the children of Israel, and brought them word again.'),
  ('e941a4df-f0cc-5c9e-a11d-59464ebb4122', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 33, 33, 'The thing pleased the children of Israel; and the children of Israel blessed God, and spoke no more of going up against them to war, to destroy the land in which the children of Reuben and the children of Gad lived.'),
  ('fe6e9f62-8cc7-5e3c-a0b6-f90eeedcdfff', 'cf676c6f-4cdd-597b-a5f5-c3491ec09568', NULL, 34, 34, 'The children of Reuben and the children of Gad named the altar "A Witness Between Us that Yahweh is God."'),
  ('45f204a2-b063-5f44-ad83-1bf0f7ca0a8d', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 1, 1, 'It happened after many days, when Yahweh had given rest to Israel from their enemies all around, and Joshua was old and well advanced in years,'),
  ('3be11ba8-fa90-5170-a887-24adc59eb914', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 2, 2, 'that Joshua called for all Israel, for their elders and for their heads, and for their judges and for their officers, and said to them, "I am old and well advanced in years.'),
  ('f359d283-83cb-5bc9-a7a6-d66c219c965d', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 3, 3, 'You have seen all that Yahweh your God has done to all these nations because of you; for it is Yahweh your God who has fought for you.'),
  ('51fd9648-5683-5717-a6b8-035cb35e92db', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 4, 4, 'Behold, I have allotted to you these nations that remain, to be an inheritance for your tribes, from the Jordan, with all the nations that I have cut off, even to the great sea toward the going down of the sun.'),
  ('80b2056e-bb98-52b4-a88a-33bc13eff036', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 5, 5, 'Yahweh your God will thrust them out from before you, and drive them from out of your sight. You shall possess their land, as Yahweh your God spoke to you.'),
  ('b8ab2b41-411e-5489-a1b3-ed1e770f9e51', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 6, 6, '"Therefore be very courageous to keep and to do all that is written in the book of the law of Moses, that you not turn aside from it to the right hand or to the left;'),
  ('374486b5-4cbe-5e00-a6e9-6a4286a64b33', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 7, 7, 'that you not come among these nations, these that remain among you; neither make mention of the name of their gods, nor cause to swear by them, neither serve them, nor bow down yourselves to them;'),
  ('48c4f265-2d89-50f9-a29b-4dd57d372da2', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 8, 8, 'but hold fast to Yahweh your God, as you have done to this day.'),
  ('0081f499-bee8-56ba-a728-8b3a5e78b725', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 9, 9, '"For Yahweh has driven great and strong nations out from before you. But as for you, no man has stood before you to this day.'),
  ('97c8c33f-2f16-5344-a011-6dd209bb37c1', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 10, 10, 'One man of you shall chase a thousand; for it is Yahweh your God who fights for you, as he spoke to you.'),
  ('6e25c7d4-f10a-5bf7-a574-946b4b4768a7', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 11, 11, 'Take good heed therefore to yourselves, that you love Yahweh your God.'),
  ('f192a0c5-c240-5453-a4ad-b2b56f3ee17e', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 12, 12, '"But if you do at all go back, and hold fast to the remnant of these nations, even these who remain among you, and make marriages with them, and go in to them, and they to you;'),
  ('6b9c0b86-db5f-5e86-a394-9199a6805d07', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 13, 13, 'know for a certainty that Yahweh your God will no longer drive these nations from out of your sight; but they shall be a snare and a trap to you, a scourge in your sides, and thorns in your eyes, until you perish from off this good land which Yahweh your God has given you.'),
  ('a048861f-9072-53b0-aef8-bbdc29151384', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 14, 14, '"Behold, today I am going the way of all the earth. You know in all your hearts and in all your souls that not one thing has failed of all the good things which Yahweh your God spoke concerning you. All have happened to you. Not one thing has failed of it.'),
  ('c07dab5a-d861-57d2-aafa-4cd55c010823', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 15, 15, 'It shall happen that as all the good things have come on you of which Yahweh your God spoke to you, so Yahweh will bring on you all the evil things, until he has destroyed you from off this good land which Yahweh your God has given you,'),
  ('49d544e5-cd6a-5651-a668-24b77cac3534', '72bfc66e-e922-5aac-a43f-8120a0ccadd9', NULL, 16, 16, 'when you disobey the covenant of Yahweh your God, which he commanded you, and go and serve other gods, and bow down yourselves to them. Then the anger of Yahweh will be kindled against you, and you will perish quickly from off the good land which he has given to you."'),
  ('56bf1fc4-b882-5a33-ab26-276598a9685a', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 1, 1, 'Joshua gathered all the tribes of Israel to Shechem, and called for the elders of Israel, for their heads, for their judges, and for their officers; and they presented themselves before God.'),
  ('b3c2764d-f8e1-5604-ac1d-940be6060f0c', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 2, 2, 'Joshua said to all the people, "Thus says Yahweh, the God of Israel, ''Your fathers lived of old time beyond the River, even Terah, the father of Abraham, and the father of Nahor: and they served other gods.'),
  ('c247b7c1-3474-5a89-a439-2714c1bfdc0f', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 3, 3, 'I took your father Abraham from beyond the River, and led him throughout all the land of Canaan, and multiplied his seed, and gave him Isaac.'),
  ('ef37ed18-9c26-52fc-ac7c-23ce5f9b9c97', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 4, 4, 'I gave to Isaac Jacob and Esau: and I gave to Esau Mount Seir, to possess it. Jacob and his children went down into Egypt.'),
  ('0277e833-5c6a-5d10-ae55-716b3d34fd48', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 5, 5, '"''I sent Moses and Aaron, and I plagued Egypt, according to that which I did in its midst: and afterward I brought you out.'),
  ('bcf80d4e-8356-5482-aff5-9eb308f556fb', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 6, 6, 'I brought your fathers out of Egypt: and you came to the sea. The Egyptians pursued after your fathers with chariots and with horsemen to the Red Sea.'),
  ('6576e323-645b-5710-a8aa-638f495adbd8', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 7, 7, 'When they cried out to Yahweh, he put darkness between you and the Egyptians, and brought the sea on them, and covered them; and your eyes saw what I did in Egypt: and you lived in the wilderness many days.'),
  ('5dfbf516-3dfa-5ed1-a1f9-46e91445b93c', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 8, 8, '"''I brought you into the land of the Amorites, that lived beyond the Jordan: and they fought with you; and I gave them into your hand. You possessed their land; and I destroyed them from before you.'),
  ('62511d13-bc00-59d3-a7ca-b96cf26f7f2e', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 9, 9, 'Then Balak the son of Zippor, king of Moab, arose and fought against Israel. He sent and called Balaam the son of Beor to curse you;'),
  ('b89d5b71-33af-5991-a5fd-a63f7c471ad3', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 10, 10, 'but I would not listen to Balaam; therefore he blessed you still. So I delivered you out of his hand.'),
  ('38ab1447-6404-5b34-a663-c949af4e3785', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 11, 11, '"''You went over the Jordan, and came to Jericho. The men of Jericho fought against you, the Amorite, the Perizzite, the Canaanite, the Hittite, the Girgashite, the Hivite, and the Jebusite; and I delivered them into your hand.'),
  ('5da4d229-ca82-51e4-afa6-05623d45b7c6', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 12, 12, 'I sent the hornet before you, which drove them out from before you, even the two kings of the Amorites; not with your sword, nor with your bow.'),
  ('01c533e9-5ff4-5a03-a637-e5150ce06ed1', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 13, 13, 'I gave you a land whereon you had not labored, and cities which you didn''t build, and you live in them. You eat of vineyards and olive groves which you didn''t plant.'''),
  ('2c90b788-24e7-5b5c-ab4e-c9c1f81ea315', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 14, 14, '"Now therefore fear Yahweh, and serve him in sincerity and in truth. Put away the gods which your fathers served beyond the River, in Egypt; and serve Yahweh.'),
  ('4bbefeda-7cf0-55da-aa2d-3672216dc5cc', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 15, 15, 'If it seems evil to you to serve Yahweh, choose this day whom you will serve; whether the gods which your fathers served that were beyond the River, or the gods of the Amorites, in whose land you dwell: but as for me and my house, we will serve Yahweh."'),
  ('8e515bd2-f04e-5ddc-ab25-f468a8abe8c0', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 16, 16, 'The people answered, "Far be it from us that we should forsake Yahweh, to serve other gods;'),
  ('dfa1fccc-a742-534b-ace6-9417e3c795e7', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 17, 17, 'for it is Yahweh our God who brought us and our fathers up out of the land of Egypt, from the house of bondage, and who did those great signs in our sight, and preserved us in all the way in which we went, and among all the peoples through the midst of whom we passed.'),
  ('ccd630e7-5444-5d33-a64a-1a5b0cd289be', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 18, 18, 'Yahweh drove out from before us all the peoples, even the Amorites who lived in the land. Therefore we also will serve Yahweh; for he is our God."'),
  ('7e7b0b48-4c2b-544d-a8c6-9fea2abc7e6f', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 19, 19, 'Joshua said to the people, "You can''t serve Yahweh; for he is a holy God. He is a jealous God. He will not forgive your disobedience nor your sins.'),
  ('f590f13f-ed9a-59c0-a679-a5d4aa92b3ea', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 20, 20, 'If you forsake Yahweh, and serve foreign gods, then he will turn and do you evil, and consume you, after he has done you good."'),
  ('585ff2e5-534a-5bfe-a0bc-4d5505daf08a', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 21, 21, 'The people said to Joshua, "No; but we will serve Yahweh."'),
  ('bc5b9069-2734-524f-a33a-e0336ae20915', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 22, 22, 'Joshua said to the people, "You are witnesses against yourselves that you have chosen Yahweh yourselves, to serve him." They said, "We are witnesses."'),
  ('87fd2b29-3cad-5795-a31e-40ec7da888e3', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 23, 23, '"Now therefore put away the foreign gods which are among you, and incline your heart to Yahweh, the God of Israel."'),
  ('15e92cfa-b1a1-59ec-acfb-e9b3d49d9c12', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 24, 24, 'The people said to Joshua, "We will serve Yahweh our God, and we will listen to his voice."'),
  ('05286214-1f9a-5ea8-ab30-76b0fc21693f', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 25, 25, 'So Joshua made a covenant with the people that day, and made for them a statute and an ordinance in Shechem.'),
  ('195d2d9c-1d4d-5e1a-ae77-a797b5430dcb', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 26, 26, 'Joshua wrote these words in the book of the law of God; and he took a great stone, and set it up there under the oak that was by the sanctuary of Yahweh.'),
  ('a92462f5-95a3-5f6a-a723-4897708e9a06', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 27, 27, 'Joshua said to all the people, "Behold, this stone shall be a witness against us; for it has heard all the words of Yahweh which he spoke to us. It shall be therefore a witness against you, lest you deny your God."'),
  ('60a55109-82e8-50c2-a733-4df3c6b44104', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 28, 28, 'So Joshua sent the people away, every man to his inheritance.'),
  ('674fc925-c220-5f8c-a702-5fffadb62580', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 29, 29, 'It happened after these things, that Joshua the son of Nun, the servant of Yahweh, died, being one hundred and ten years old.'),
  ('1adcf49b-49d3-54a0-af45-7287e21ecb60', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 30, 30, 'They buried him in the border of his inheritance in Timnathserah, which is in the hill country of Ephraim, on the north of the mountain of Gaash.'),
  ('5a4720fc-5d01-5e95-a6c9-824d7e813c04', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 31, 31, 'Israel served Yahweh all the days of Joshua, and all the days of the elders who outlived Joshua, and had known all the work of Yahweh, that he had worked for Israel.'),
  ('c17fb847-daf0-57fc-a226-d78b817e502f', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 32, 32, 'They buried the bones of Joseph, which the children of Israel brought up out of Egypt, in Shechem, in the parcel of ground which Jacob bought of the sons of Hamor the father of Shechem for a hundred pieces of money. They became the inheritance of the children of Joseph.'),
  ('7fb0e440-6de3-5a9a-a995-179e681c9130', 'f2d72834-45c4-5791-a01c-35b77e0fe998', NULL, 33, 33, 'Eleazar the son of Aaron died. They buried him in the hill of Phinehas his son, which was given him in the hill country of Ephraim.'),
  ('977c65fd-5393-500f-a72f-055d2dd01919', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 1, 1, 'It happened after the death of Joshua, the children of Israel asked of Yahweh, saying, "Who should go up for us first against the Canaanites, to fight against them?"'),
  ('ba38cf33-976e-560d-a53e-36a257adc475', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 2, 2, 'Yahweh said, "Judah shall go up. Behold, I have delivered the land into his hand."'),
  ('cd60cdcb-2a4c-5349-a641-9becdba93314', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 3, 3, 'Judah said to Simeon his brother, "Come up with me into my lot, that we may fight against the Canaanites; and I likewise will go with you into your lot." So Simeon went with him.'),
  ('29ccdad9-6a5a-509e-aecc-07bee10a50c6', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 4, 4, 'Judah went up; and Yahweh delivered the Canaanites and the Perizzites into their hand: and they struck of them in Bezek ten thousand men.'),
  ('9a68af6a-f769-58ff-a653-78d33025ae10', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 5, 5, 'They found Adoni-Bezek in Bezek; and they fought against him, and they struck the Canaanites and the Perizzites.'),
  ('84e16fc6-dab8-5369-a4a1-431c0b575467', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 6, 6, 'But Adoni-Bezek fled; and they pursued after him, and caught him, and cut off his thumbs and his great toes.'),
  ('64fb0ee6-76a9-5e7c-ad96-e74567234e3f', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 7, 7, 'Adoni-Bezek said, "Seventy kings, having their thumbs and their great toes cut off, gathered [their food] under my table: as I have done, so God has requited me." They brought him to Jerusalem, and he died there.'),
  ('8f314475-3bd9-54ad-ae0a-ab545e7de230', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 8, 8, 'The children of Judah fought against Jerusalem, and took it, and struck it with the edge of the sword, and set the city on fire.'),
  ('e774f7d6-c6a7-5cec-a9cb-cd2c7b8e11df', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 9, 9, 'Afterward the children of Judah went down to fight against the Canaanites who lived in the hill country, and in the South, and in the lowland.'),
  ('543389a3-c496-574c-a638-709d40254bd5', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 10, 10, 'Judah went against the Canaanites who lived in Hebron (now the name of Hebron before was Kiriath Arba); and they struck Sheshai, and Ahiman, and Talmai.'),
  ('3fc6b7fa-69a6-5f9a-a498-a6c389898094', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 11, 11, 'From there he went against the inhabitants of Debir. (Now the name of Debir before was Kiriath Sepher.)'),
  ('303d9743-82e5-570c-a89e-c9e2b9712a38', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 12, 12, 'Caleb said, "He who strikes Kiriath Sepher, and takes it, to him will I give Achsah my daughter as wife."'),
  ('1a4730e4-b870-59a5-a8ee-f07c1ed98556', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 13, 13, 'Othniel the son of Kenaz, Caleb''s younger brother, took it: and he gave him Achsah his daughter as wife.'),
  ('2329c613-515e-5206-a673-3b241ae593c4', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 14, 14, 'It happened, when she came [to him], that she moved him to ask of her father a field: and she alighted from off her donkey; and Caleb said to her, "What would you like?"'),
  ('dd3de829-271d-58ab-acc2-25c350a2bfa9', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 15, 15, 'She said to him, "Give me a blessing; for that you have set me in the land of the South, give me also springs of water." Then Caleb gave her the upper springs and the lower springs.'),
  ('2dea1818-3a4a-54fb-a0bc-f85b8eff35f5', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 16, 16, 'The children of the Kenite, Moses'' brother-in-law, went up out of the city of palm trees with the children of Judah into the wilderness of Judah, which is in the south of Arad; and they went and lived with the people.'),
  ('3e57691a-9403-552f-a568-5093cd9b3b37', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 17, 17, 'Judah went with Simeon his brother, and they struck the Canaanites who inhabited Zephath, and utterly destroyed it. The name of the city was called Hormah.'),
  ('5abe75c7-980c-5cf3-a57d-01ca239be06e', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 18, 18, 'Also Judah took Gaza with its border, and Ashkelon with its border, and Ekron with its border.'),
  ('17f87abb-675d-51be-adc0-3eb0df31ad0f', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 19, 19, 'Yahweh was with Judah; and drove out [the inhabitants of] the hill country; for he could not drive out the inhabitants of the valley, because they had chariots of iron.'),
  ('e8929677-24af-5a63-a4d7-fa351f409d7b', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 20, 20, 'They gave Hebron to Caleb, as Moses had spoken: and he drove out there the three sons of Anak.'),
  ('18dff951-d58a-5412-a5c9-cfc84997325e', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 21, 21, 'The children of Benjamin did not drive out the Jebusites who inhabited Jerusalem; but the Jebusites dwell with the children of Benjamin in Jerusalem to this day.'),
  ('16bf56a9-c353-5366-a46b-3fc61236d576', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 22, 22, 'The house of Joseph, they also went up against Bethel; and Yahweh was with them.'),
  ('ff64f26a-375a-52fd-a034-fe9c16c4575e', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 23, 23, 'The house of Joseph sent to spy out Bethel. (Now the name of the city before was Luz.)'),
  ('e4ca5f18-8dfb-53bf-a8ae-827969b61690', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 24, 24, 'The watchers saw a man come forth out of the city, and they said to him, "Please show us the entrance into the city, and we will deal kindly with you."'),
  ('b29f5f7a-9d68-59ec-ae7b-740010bdf2e9', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 25, 25, 'He showed them the entrance into the city; and they struck the city with the edge of the sword; but they let the man go and all his family.'),
  ('de4ba812-b69b-5e4b-af0d-9e1510f1290e', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 26, 26, 'The man went into the land of the Hittites, and built a city, and called its name Luz, which is its name to this day.'),
  ('cdbe920a-0abc-5402-a4f0-f036c423d32e', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 27, 27, 'Manasseh did not drive out [the inhabitants of] Beth Shean and its towns, nor [of] Taanach and its towns, nor the inhabitants of Dor and its towns, nor the inhabitants of Ibleam and its towns, nor the inhabitants of Megiddo and its towns; but the Canaanites would dwell in that land.'),
  ('7bfd7758-6dbe-59ab-af00-885830fab338', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 28, 28, 'It happened, when Israel had grown strong, that they put the Canaanites to forced labor, and did not utterly drive them out.'),
  ('eaef50e2-cb22-5dae-ad9d-326dd28b9a88', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 29, 29, 'Ephraim didn''t drive out the Canaanites who lived in Gezer; but the Canaanites lived in Gezer among them.'),
  ('029b5d5c-007f-5cf7-a4ec-8e8d17bb40cb', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 30, 30, 'Zebulun didn''t drive out the inhabitants of Kitron, nor the inhabitants of Nahalol; but the Canaanites lived among them, and became subject to forced labor.'),
  ('c35655f2-2e6d-5a1e-a5a8-715b792bc484', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 31, 31, 'Asher didn''t drive out the inhabitants of Acco, nor the inhabitants of Sidon, nor of Ahlab, nor of Achzib, nor of Helbah, nor of Aphik, nor of Rehob;'),
  ('df6d1bba-018c-5b52-a2ce-fca4a1c04f94', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 32, 32, 'but the Asherites lived among the Canaanites, the inhabitants of the land; for they did not drive them out.'),
  ('be24804b-fe90-5772-a672-92b8f42c6bfa', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 33, 33, 'Naphtali didn''t drive out the inhabitants of Beth Shemesh, nor the inhabitants of Beth Anath; but he lived among the Canaanites, the inhabitants of the land: nevertheless the inhabitants of Beth Shemesh and of Beth Anath became subject to forced labor.'),
  ('ad8f3f71-66db-5bec-a8d2-160addfab729', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 34, 34, 'The Amorites forced the children of Dan into the hill country; for they would not allow them to come down to the valley;'),
  ('d1786b99-2f09-5151-a19c-89ee1143a75d', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 35, 35, 'but the Amorites would dwell in Mount Heres, in Aijalon, and in Shaalbim: yet the hand of the house of Joseph prevailed, so that they became subject to forced labor.'),
  ('a932ad28-c7bb-56db-a532-9d50222aa4cd', 'f7d2ef91-a92b-5f1f-af2f-3d875d003f63', NULL, 36, 36, 'The border of the Amorites was from the ascent of Akrabbim, from the rock, and upward.'),
  ('b200113a-65b6-520c-a167-ec2006666628', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 1, 1, 'The angel of Yahweh came up from Gilgal to Bochim. He said, "I made you to go up out of Egypt, and have brought you to the land which I swore to your fathers; and I said, ''I will never break my covenant with you:'),
  ('bb1a559c-e1c5-5394-a5ca-29ddb7ba59b6', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 2, 2, 'and you shall make no covenant with the inhabitants of this land; you shall break down their altars.'' But you have not listened to my voice: why have you done this?'),
  ('2ef4275f-a051-5f6c-a70b-b40b10bbc2ce', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 3, 3, 'Therefore I also said, I will not drive them out from before you; but they shall be [as thorns] in your sides, and their gods shall be a snare to you."'),
  ('219f6f5d-3d96-54fa-a7d2-6838526daa65', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 4, 4, 'It happened, when the angel of Yahweh spoke these words to all the children of Israel, that the people lifted up their voice, and wept.'),
  ('54c23abe-ddb6-5c41-af39-ba86d21067be', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 5, 5, 'They called the name of that place Bochim: and they sacrificed there to Yahweh.'),
  ('87b1f6e6-4499-5b8a-a560-8abedd01dfe6', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 6, 6, 'Now when Joshua had sent the people away, the children of Israel went every man to his inheritance to possess the land.'),
  ('42550623-39c2-5690-a2b7-1b503b7f6b81', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 7, 7, 'The people served Yahweh all the days of Joshua, and all the days of the elders who outlived Joshua, who had seen all the great work of Yahweh that he had worked for Israel.'),
  ('00c2baf0-d3f9-5726-a9ed-88e1c3ebda3c', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 8, 8, 'Joshua the son of Nun, the servant of Yahweh, died, being one hundred ten years old.'),
  ('b45f5d8d-5724-5f15-a472-f47510b9678d', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 9, 9, 'They buried him in the border of his inheritance in Timnath Heres, in the hill country of Ephraim, on the north of the mountain of Gaash.'),
  ('b9c4729d-7cbe-5d17-a092-b331a2d939b5', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 10, 10, 'Also all that generation were gathered to their fathers: and there arose another generation after them, who didn''t know Yahweh, nor yet the work which he had worked for Israel.'),
  ('d80b3eff-a494-5b26-ad92-e079968acdcd', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 11, 11, 'The children of Israel did that which was evil in the sight of Yahweh, and served the Baals;'),
  ('45cab34c-e1d8-5736-aad9-bfc19f63e1c5', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 12, 12, 'and they forsook Yahweh, the God of their fathers, who brought them out of the land of Egypt, and followed other gods, of the gods of the peoples who were around them, and bowed themselves down to them: and they provoked Yahweh to anger.'),
  ('8d880edc-55fc-5f87-a667-1be6c35b65ee', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 13, 13, 'They forsook Yahweh, and served Baal and the Ashtaroth.'),
  ('fa45a5e6-1a43-57fe-ab1c-bd8b34492d4f', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 14, 14, 'The anger of Yahweh was kindled against Israel, and he delivered them into the hands of spoilers who despoiled them; and he sold them into the hands of their enemies all around, so that they could not any longer stand before their enemies.'),
  ('8b245904-b5b4-5f9e-a043-07a8a7c14e3e', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 15, 15, 'Wherever they went out, the hand of Yahweh was against them for evil, as Yahweh had spoken, and as Yahweh had sworn to them: and they were very distressed.'),
  ('35751669-e868-5371-aa1f-1a1bf8a88380', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 16, 16, 'Yahweh raised up judges, who saved them out of the hand of those who despoiled them.'),
  ('a815be14-de18-5cc2-aaf4-21c99b468768', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 17, 17, 'Yet they didn''t listen to their judges; for they played the prostitute after other gods, and bowed themselves down to them: they turned aside quickly out of the way in which their fathers walked, obeying the commandments of Yahweh; [but] they didn''t do so.'),
  ('9585014e-dca2-5392-ab6b-fb96ab63b38e', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 18, 18, 'When Yahweh raised them up judges, then Yahweh was with the judge, and saved them out of the hand of their enemies all the days of the judge: for it grieved Yahweh because of their groaning by reason of those who oppressed them and troubled them.'),
  ('b7111117-5b2c-5536-a34a-3d70744e7b7f', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 19, 19, 'But it happened, when the judge was dead, that they turned back, and dealt more corruptly than their fathers, in following other gods to serve them, and to bow down to them; they didn''t cease from their doings, nor from their stubborn way.'),
  ('2d05766c-36b9-56e5-ae99-14efecf93efb', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 20, 20, 'The anger of Yahweh was kindled against Israel; and he said, "Because this nation have transgressed my covenant which I commanded their fathers, and have not listened to my voice;'),
  ('ff950085-9a7c-5583-a9dc-7a54ed2b9939', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 21, 21, 'I also will not henceforth drive out any from before them of the nations that Joshua left when he died;'),
  ('d1d95ea9-eaee-523f-a026-2f17a7613a8c', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 22, 22, 'that by them I may prove Israel, whether they will keep the way of Yahweh to walk therein, as their fathers did keep it, or not."'),
  ('fc9ccf2d-55ac-5ecb-a3ed-2e4f6ad1ac31', '512bffbf-6018-5163-a745-6dea5ccabeb5', NULL, 23, 23, 'So Yahweh left those nations, without driving them out hastily; neither delivered he them into the hand of Joshua.'),
  ('75c7efe9-60b6-5d8a-a887-e39a9ab22825', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 1, 1, 'Now these are the nations which Yahweh left, to prove Israel by them, even as many [of Israel] as had not known all the wars of Canaan;'),
  ('8b9e0970-d423-5dae-a6f5-60044e24fc5c', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 2, 2, 'only that the generations of the children of Israel might know, to teach them war, at the least such as before knew nothing of it:'),
  ('4eeac990-e0e2-5dcd-a743-1ac92e622265', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 3, 3, '[namely], the five lords of the Philistines, and all the Canaanites, and the Sidonians, and the Hivites who lived on Mount Lebanon, from Mount Baal Hermon to the entrance of Hamath.'),
  ('4a118b10-1893-5d19-abae-47e97f4400da', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 4, 4, 'They were [left], to prove Israel by them, to know whether they would listen to the commandments of Yahweh, which he commanded their fathers by Moses.'),
  ('970c8fac-b5f7-50fe-ae21-0c0d21055c3d', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 5, 5, 'The children of Israel lived among the Canaanites, the Hittites, and the Amorites, and the Perizzites, and the Hivites, and the Jebusites:'),
  ('feb003c7-d64b-50e1-a810-440bf8045f58', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 6, 6, 'and they took their daughters to be their wives, and gave their own daughters to their sons and served their gods.'),
  ('c30c0f0c-1012-55e5-a6b7-e4c4f5df9dbb', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 7, 7, 'The children of Israel did that which was evil in the sight of Yahweh, and forgot Yahweh their God, and served the Baals and the Asheroth.'),
  ('2d0d7609-1483-5ee2-a6bb-3058eaffd692', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 8, 8, 'Therefore the anger of Yahweh was kindled against Israel, and he sold them into the hand of Cushan Rishathaim king of Mesopotamia: and the children of Israel served Cushan Rishathaim eight years.'),
  ('2af5e524-5691-5b28-a132-778c23fac4dd', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 9, 9, 'When the children of Israel cried to Yahweh, Yahweh raised up a savior to the children of Israel, who saved them, even Othniel the son of Kenaz, Caleb''s younger brother.'),
  ('63e64e84-62d4-5aaa-a2af-29c4bfe956a8', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 10, 10, 'The Spirit of Yahweh came on him, and he judged Israel; and he went out to war, and Yahweh delivered Cushan Rishathaim king of Mesopotamia into his hand: and his hand prevailed against Cushan Rishathaim.'),
  ('706d3365-ef45-598b-a71b-72c0c521eb7d', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 11, 11, 'The land had rest forty years. Othniel the son of Kenaz died.'),
  ('efcffb17-59e0-5bb8-a286-86092d01a8b8', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 12, 12, 'The children of Israel again did that which was evil in the sight of Yahweh: and Yahweh strengthened Eglon the king of Moab against Israel, because they had done that which was evil in the sight of Yahweh.'),
  ('da3ee6d3-6f5b-520f-a962-3a206b5d3fe6', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 13, 13, 'He gathered to him the children of Ammon and Amalek; and he went and struck Israel, and they possessed the city of palm trees.'),
  ('634f0b19-618a-5fc3-a7c1-07fde64920dc', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 14, 14, 'The children of Israel served Eglon the king of Moab eighteen years.'),
  ('58c15d60-2b17-53ec-a6d1-63972eaa0b9e', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 15, 15, 'But when the children of Israel cried to Yahweh, Yahweh raised them up a savior, Ehud the son of Gera, the Benjamite, a man left-handed. The children of Israel sent tribute by him to Eglon the king of Moab.'),
  ('7705a60f-fcc8-5376-a928-159446f07510', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 16, 16, 'Ehud made him a sword which had two edges, a cubit in length; and he wore it under his clothing on his right thigh.'),
  ('4821d90c-ae47-52f7-a945-00f26c2801ce', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 17, 17, 'He offered the tribute to Eglon king of Moab: now Eglon was a very fat man.'),
  ('54491dc4-49a6-55c0-a079-9b9a057ac6a3', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 18, 18, 'When he had made an end of offering the tribute, he sent away the people who bore the tribute.'),
  ('e1164797-a241-5ddf-a84d-d367574af110', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 19, 19, 'But he himself turned back from the quarries that were by Gilgal, and said, "I have a secret errand to you, king." The king said, "Keep silence!" All who stood by him went out from him.'),
  ('03a5ec7a-e2d5-5db9-ab29-1325d666035a', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 20, 20, 'Ehud came to him; and he was sitting by himself alone in the cool upper room. Ehud said, "I have a message from God to you." He arose out of his seat.'),
  ('231312c2-68cc-5228-a333-aaf37d0e2fe8', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 21, 21, 'Ehud put forth his left hand, and took the sword from his right thigh, and thrust it into his body:'),
  ('85221079-6e9b-523b-a9c4-4fbaf12972bd', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 22, 22, 'and the handle also went in after the blade; and the fat closed on the blade, for he didn''t draw the sword out of his body; and it came out behind.'),
  ('131b8449-9034-5f8e-a6f4-46fb85b5e573', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 23, 23, 'Then Ehud went forth into the porch, and shut the doors of the upper room on him, and locked them.'),
  ('517e5d2c-c45d-5cee-aec4-79a63d0a1e5a', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 24, 24, 'Now when he was gone out, his servants came; and they saw, and behold, the doors of the upper room were locked; and they said, "Surely he is covering his feet in the upper room."'),
  ('78cb4ed4-7641-5502-ad2a-4f48803e6e0c', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 25, 25, 'They waited until they were ashamed; and behold, he didn''t open the doors of the upper room: therefore they took the key, and opened [them], and behold, their lord was fallen down dead on the earth.'),
  ('7eba5397-92ec-5656-a722-36133c459025', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 26, 26, 'Ehud escaped while they waited, and passed beyond the quarries, and escaped to Seirah.'),
  ('3d6d719c-4538-59c6-a2ba-80d2e1ee71ba', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 27, 27, 'It happened, when he had come, that he blew a trumpet in the hill country of Ephraim; and the children of Israel went down with him from the hill country, and he before them.'),
  ('9c794dc4-c49e-5ca3-af85-4ce0e6718a05', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 28, 28, 'He said to them, "Follow me; for Yahweh has delivered your enemies the Moabites into your hand." They followed him, and took the fords of the Jordan against the Moabites, and didn''t allow any man to pass over.'),
  ('1f35d482-640d-5934-a163-89c960bf860c', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 29, 29, 'They struck of Moab at that time about ten thousand men, every lusty man, and every man of valor; and there escaped not a man.'),
  ('abbb5d5f-0ceb-5c83-a84c-71b7431bceb4', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 30, 30, 'So Moab was subdued that day under the hand of Israel. The land had rest eighty years.'),
  ('b739f16a-6ee0-507a-a7cc-2a9bf3600ace', '0e3f9ef0-485b-5563-a704-8c84e9ee115c', NULL, 31, 31, 'After him was Shamgar the son of Anath, who struck of the Philistines six hundred men with an oxgoad: and he also saved Israel.'),
  ('fe12b655-3808-5f9a-ab9d-b5428d05e0ce', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 1, 1, 'The children of Israel again did that which was evil in the sight of Yahweh, when Ehud was dead.'),
  ('6a81869b-eb51-576e-addd-be0cc7fc9c8b', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 2, 2, 'Yahweh sold them into the hand of Jabin king of Canaan, who reigned in Hazor; the captain of whose army was Sisera, who lived in Harosheth of the Gentiles.'),
  ('d6f828eb-ed53-5965-ae66-7ef5eeed8859', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 3, 3, 'The children of Israel cried to Yahweh: for he had nine hundred chariots of iron; and twenty years he mightily oppressed the children of Israel.'),
  ('f46869e1-ffad-5ec8-a244-946cf9ac13e5', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 4, 4, 'Now Deborah, a prophetess, the wife of Lappidoth, she judged Israel at that time.'),
  ('6b559ed6-5e52-51b6-a5c1-7c60d7705cac', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 5, 5, 'She lived under the palm tree of Deborah between Ramah and Bethel in the hill country of Ephraim: and the children of Israel came up to her for judgment.'),
  ('272e151d-a3e1-5306-a8be-2535f93ddcb4', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 6, 6, 'She sent and called Barak the son of Abinoam out of Kedesh Naphtali, and said to him, "Hasn''t Yahweh, the God of Israel, commanded, ''Go and draw to Mount Tabor, and take with you ten thousand men of the children of Naphtali and of the children of Zebulun?'),
  ('465f2a34-7d5e-51ee-a54d-ce3fc1d7dc7c', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 7, 7, 'I will draw to you, to the river Kishon, Sisera, the captain of Jabin''s army, with his chariots and his multitude; and I will deliver him into your hand.''"'),
  ('a1332520-65b8-5cc6-a066-908f4b04bea9', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 8, 8, 'Barak said to her, "If you will go with me, then I will go; but if you will not go with me, I will not go."'),
  ('27e69dfe-3d79-534f-a48f-2a7e8588dee1', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 9, 9, 'She said, "I will surely go with you: nevertheless, the journey that you take shall not be for your honor; for Yahweh will sell Sisera into the hand of a woman." Deborah arose, and went with Barak to Kedesh.'),
  ('c2321fcb-a9b7-557e-a2b6-f845a1c77dcb', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 10, 10, 'Barak called Zebulun and Naphtali together to Kedesh; and there went up ten thousand men at his feet: and Deborah went up with him.'),
  ('2fba0f8e-4833-56f9-ad58-7ea0e7af5081', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 11, 11, 'Now Heber the Kenite had separated himself from the Kenites, even from the children of Hobab the brother-in-law of Moses, and had pitched his tent as far as the oak in Zaanannim, which is by Kedesh.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('ee04d321-668f-5516-ab1a-4dfa644949c0', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 12, 12, 'They told Sisera that Barak the son of Abinoam was gone up to Mount Tabor.'),
  ('b48af559-b40b-5344-aa85-e1584dd5b181', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 13, 13, 'Sisera gathered together all his chariots, even nine hundred chariots of iron, and all the people who were with him, from Harosheth of the Gentiles, to the river Kishon.'),
  ('c1ce2c9d-7c8b-5533-a83f-c8a77d14b65f', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 14, 14, 'Deborah said to Barak, "Go; for this is the day in which Yahweh has delivered Sisera into your hand. Hasn''t Yahweh gone out before you?" So Barak went down from Mount Tabor, and ten thousand men after him.'),
  ('d03b92ef-c8cc-5dcb-a6bb-e5d9fe45e717', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 15, 15, 'Yahweh confused Sisera, and all his chariots, and all his army, with the edge of the sword before Barak; and Sisera alighted from his chariot, and fled away on his feet.'),
  ('2d63d2ff-5763-5d3d-a87e-31393fd6f9fa', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 16, 16, 'But Barak pursued after the chariots, and after the army, to Harosheth of the Gentiles: and all the army of Sisera fell by the edge of the sword; there was not a man left.'),
  ('330c0207-62dd-5513-a754-cfdebdc058eb', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 17, 17, 'However Sisera fled away on his feet to the tent of Jael the wife of Heber the Kenite; for there was peace between Jabin the king of Hazor and the house of Heber the Kenite.'),
  ('4bcb269a-1677-54ab-a88f-5262f16fa44c', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 18, 18, 'Jael went out to meet Sisera, and said to him, "Turn in, my lord, turn in to me; don''t be afraid." He came in to her into the tent, and she covered him with a rug.'),
  ('f1e098b8-dea2-5e9a-a1e5-9e8e57b37251', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 19, 19, 'He said to her, "Please give me a little water to drink; for I am thirsty." She opened a bottle of milk, and gave him drink, and covered him.'),
  ('cfad44eb-f471-558a-a781-568f84af93d3', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 20, 20, 'He said to her, "Stand in the door of the tent, and it shall be, when any man comes and inquires of you, and says, ''Is there any man here?'' that you shall say, ''No.''"'),
  ('12879251-9f2e-5d32-a510-400af6e9c61c', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 21, 21, 'Then Jael Heber''s wife took a tent peg, and took a hammer in her hand, and went softly to him, and struck the pin into his temples, and it pierced through into the ground; for he was in a deep sleep; so he swooned and died.'),
  ('e7bfc0d3-5db2-5186-a997-4cc5040fd979', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 22, 22, 'Behold, as Barak pursued Sisera, Jael came out to meet him, and said to him, "Come, and I will show you the man whom you seek." He came to her; and behold, Sisera lay dead, and the tent peg was in his temples.'),
  ('aa9789f8-27cf-5c9e-a959-57f99a230a35', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 23, 23, 'So God subdued on that day Jabin the king of Canaan before the children of Israel.'),
  ('276d0c74-4998-5a39-aa6b-f55dfa3f4fa8', 'ad829961-6b4e-57dc-adfa-f272fd50f80b', NULL, 24, 24, 'The hand of the children of Israel prevailed more and more against Jabin the king of Canaan, until they had destroyed Jabin king of Canaan.'),
  ('9b0fe252-1d1d-5b9c-a617-046461518873', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 1, 1, 'Then Deborah and Barak the son of Abinoam sang on that day, saying,'),
  ('c83052ba-ca0a-504a-a3c3-c0753627b473', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 2, 2, '"Because the leaders took the lead in Israel, because the people offered themselves willingly, be blessed, Yahweh!'),
  ('e631c87a-a8ba-5058-a375-7073aa7f5cb1', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 3, 3, '"Hear, you kings! Give ear, you princes! I, [even] I, will sing to Yahweh. I will sing praise to Yahweh, the God of Israel.'),
  ('c712a163-0490-5c75-a267-7c89878a1004', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 4, 4, '"Yahweh, when you went forth out of Seir, when you marched out of the field of Edom, the earth trembled, the sky also dropped. Yes, the clouds dropped water.'),
  ('b034e7e7-5172-5440-a01d-987023258548', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 5, 5, 'The mountains quaked at the presence of Yahweh, even Sinai, at the presence of Yahweh, the God of Israel.'),
  ('e8e9a457-be53-5159-aa7a-88503bb52dae', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 6, 6, '"In the days of Shamgar the son of Anath, in the days of Jael, the highways were unoccupied. The travelers walked through byways.'),
  ('94eec26d-7674-5333-aeec-4928cb67a3e1', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 7, 7, 'The rulers ceased in Israel. They ceased until I, Deborah, arose; Until I arose a mother in Israel.'),
  ('9f7267f5-79c2-5c3b-afbc-06a725a963ac', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 8, 8, 'They chose new gods. Then war was in the gates. Was there a shield or spear seen among forty thousand in Israel?'),
  ('53484a47-0e16-54a1-ac71-c03b0cc975f4', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 9, 9, 'My heart is toward the governors of Israel, who offered themselves willingly among the people. Bless Yahweh!'),
  ('bf2b3cc3-091c-5207-a76d-cec704fee5ca', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 10, 10, '"Tell [of it], you who ride on white donkeys, you who sit on rich carpets, and you who walk by the way.'),
  ('554c7fb5-06f9-54eb-a42b-3a71d44e3304', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 11, 11, 'Far from the noise of archers, in the places of drawing water, there they will rehearse the righteous acts of Yahweh, [Even] the righteous acts of his rule in Israel. "Then the people of Yahweh went down to the gates.'),
  ('888fb0ff-4994-584f-ae7e-50af958d0786', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 12, 12, '''Awake, awake, Deborah! Awake, awake, utter a song! Arise, Barak, and lead away your captives, you son of Abinoam.'''),
  ('e0d9c4ec-62a8-5cfe-a40e-0728f013449b', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 13, 13, '"Then a remnant of the nobles [and] the people came down. Yahweh came down for me against the mighty.'),
  ('d267dcbf-3e68-577c-a8a6-dbe0e1128142', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 14, 14, 'Those whose root is in Amalek came out of Ephraim, after you, Benjamin, among your peoples. Governors come down out of Machir. Those who handle the marshal''s staff came out of Zebulun.'),
  ('b2432cc2-b8cd-51b5-a009-16a3a2677040', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 15, 15, 'The princes of Issachar were with Deborah. As was Issachar, so was Barak. They rushed into the valley at his feet. By the watercourses of Reuben, there were great resolves of heart.'),
  ('90e51337-2a6c-5ced-af3f-69aea95dabaf', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 16, 16, 'Why did you sit among the sheepfolds, To hear the whistling for the flocks? At the watercourses of Reuben There were great searchings of heart.'),
  ('01c27913-5fbf-5ffd-abae-4c537a93cdf5', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 17, 17, 'Gilead lived beyond the Jordan. Why did Dan remain in ships? Asher sat still at the haven of the sea, and lived by his creeks.'),
  ('6abf5407-9e09-579d-ad4f-8b1a90677591', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 18, 18, 'Zebulun was a people that jeopardized their lives to the deaths; Naphtali also, on the high places of the field.'),
  ('5aaf7b28-24c9-5d2f-a1f2-ad703bc803ab', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 19, 19, '"The kings came and fought, then the kings of Canaan fought at Taanach by the waters of Megiddo. They took no plunder of silver.'),
  ('565e1e1f-7acb-5992-a4c8-c9be677d42af', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 20, 20, 'From the sky the stars fought. From their courses, they fought against Sisera.'),
  ('e1b68555-142c-5ff2-af64-e3a8c103b541', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 21, 21, 'The river Kishon swept them away, that ancient river, the river Kishon. My soul, march on with strength.'),
  ('0b84863b-e64b-5bbc-a521-cd13a33efff8', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 22, 22, 'Then the horse hoofs stamped because of the prancings, the prancings of their strong ones.'),
  ('dcae97b0-272c-5464-ae4b-b9d4050e1dc4', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 23, 23, '''Curse Meroz,'' said the angel of Yahweh. ''Curse bitterly its inhabitants, because they didn''t come to help Yahweh, to help Yahweh against the mighty.'''),
  ('e05f07d9-1d04-5de1-a312-88b912d75673', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 24, 24, '"Jael shall be blessed above women, the wife of Heber the Kenite; blessed shall she be above women in the tent.'),
  ('1167478b-113a-583a-a055-bef71c8479f1', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 25, 25, 'He asked for water. She gave him milk. She brought him butter in a lordly dish.'),
  ('42277463-8821-519c-a169-c56fd3df8e47', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 26, 26, 'She put her hand to the tent peg, and her right hand to the workmen''s hammer. With the hammer she struck Sisera. She struck through his head. Yes, she pierced and struck through his temples.'),
  ('3ceae8ab-aa4f-5bb8-a5cd-46e1f0ac8678', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 27, 27, 'At her feet he bowed, he fell, he lay. At her feet he bowed, he fell. Where he bowed, there he fell down dead.'),
  ('e644947a-e90a-571f-aa99-d303dd880bdf', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 28, 28, '"Through the window she looked out, and cried: Sisera''s mother looked through the lattice. ''Why is his chariot so long in coming? Why do the wheels of his chariots wait?'''),
  ('a3a1125b-1a6a-577e-aecd-11b2472ae9e9', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 29, 29, 'Her wise ladies answered her, Yes, she returned answer to herself,'),
  ('83ce01b0-db77-5acf-a40c-c0b87869b030', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 30, 30, '''Have they not found, have they not divided the spoil? A lady, two ladies to every man; to Sisera a spoil of dyed garments, a spoil of dyed garments embroidered, of dyed garments embroidered on both sides, on the necks of the spoil?'''),
  ('492498dc-df24-560e-af32-0ca381453faf', '6f3d140b-d234-50d3-a608-ec4a39ab5c2f', NULL, 31, 31, '"So let all your enemies perish, Yahweh, but let those who love him be as the sun when it rises forth in its strength." Then the land had rest forty years.'),
  ('f5119252-c8f2-5541-a75c-189c695ed67e', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 1, 1, 'The children of Israel did that which was evil in the sight of Yahweh: and Yahweh delivered them into the hand of Midian seven years.'),
  ('8e6a5dbe-f443-5049-ae22-ea4546f03b44', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 2, 2, 'The hand of Midian prevailed against Israel; and because of Midian the children of Israel made them the dens which are in the mountains, and the caves, and the strongholds.'),
  ('760e7a4e-195e-53a1-a534-697f0e0e9ada', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 3, 3, 'So it was, when Israel had sown, that the Midianites came up, and the Amalekites, and the children of the east; they came up against them;'),
  ('8c13c7d2-7bf5-5783-a8a9-26e477efb0af', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 4, 4, 'and they encamped against them, and destroyed the increase of the earth, until you come to Gaza, and left no sustenance in Israel, neither sheep, nor ox, nor donkey.'),
  ('f168eddc-db41-5515-ad33-3dfce72aa7e5', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 5, 5, 'For they came up with their livestock and their tents; they came in as locusts for multitude; both they and their camels were without number: and they came into the land to destroy it.'),
  ('6c83a94f-453d-54d4-a8bf-a1577ee1c7bc', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 6, 6, 'Israel was brought very low because of Midian; and the children of Israel cried to Yahweh.'),
  ('86058daa-a443-548b-a859-1df2823261ef', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 7, 7, 'It happened, when the children of Israel cried to Yahweh because of Midian,'),
  ('1a1a1bef-a278-5333-a1ab-22b6f8f40b96', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 8, 8, 'that Yahweh sent a prophet to the children of Israel: and he said to them, "Thus says Yahweh, the God of Israel, ''I brought you up from Egypt, and brought you forth out of the house of bondage;'),
  ('7af2834b-8fec-522c-a184-ed8ea39e5904', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 9, 9, 'and I delivered you out of the hand of the Egyptians, and out of the hand of all who oppressed you, and drove them out from before you, and gave you their land;'),
  ('018c7d7b-e753-50aa-af38-bb4e8b57eb42', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 10, 10, 'and I said to you, "I am Yahweh your God; you shall not fear the gods of the Amorites, in whose land you dwell." But you have not listened to my voice.''"'),
  ('12c668a9-c5a6-52ab-a642-89b0761e52d7', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 11, 11, 'The angel of Yahweh came, and sat under the oak which was in Ophrah, that pertained to Joash the Abiezrite: and his son Gideon was beating out wheat in the winepress, to hide it from the Midianites.'),
  ('92c6be0c-07ca-5d4a-a95c-e14660f6d12d', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 12, 12, 'The angel of Yahweh appeared to him, and said to him, "Yahweh is with you, you mighty man of valor!"'),
  ('49942e96-527b-5768-addb-aa8c3cb39c9c', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 13, 13, 'Gideon said to him, "Oh, my lord, if Yahweh is with us, why then has all this happened to us? Where are all his wondrous works which our fathers told us of, saying, ''Didn''t Yahweh bring us up from Egypt?'' But now Yahweh has cast us off, and delivered us into the hand of Midian."'),
  ('d88b9557-7836-58ae-a007-6d09ac011273', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 14, 14, 'Yahweh looked at him, and said, "Go in this your might, and save Israel from the hand of Midian. Haven''t I sent you?"'),
  ('82f92110-f95c-5dee-a2ae-166c20142e17', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 15, 15, 'He said to him, "O Lord, how shall I save Israel? Behold, my family is the poorest in Manasseh, and I am the least in my father''s house."'),
  ('be4bc931-b67a-5bc2-a692-c98204331783', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 16, 16, 'Yahweh said to him, "Surely I will be with you, and you shall strike the Midianites as one man."'),
  ('98b7b20a-c6f1-5c3e-a731-823f4b227780', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 17, 17, 'He said to him, "If now I have found favor in your sight, then show me a sign that it is you who talk with me.'),
  ('81f5a6c9-7a50-5f12-a946-06c5e9ceca33', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 18, 18, 'Please don''t go away, until I come to you, and bring out my present, and lay it before you." He said, "I will wait until you come back."'),
  ('1da823b1-65c5-5f81-a920-d0e208b3767c', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 19, 19, 'Gideon went in, and prepared a young goat, and unleavened cakes of an ephah of meal. He put the meat in a basket and he put the broth in a pot, and brought it out to him under the oak, and presented it.'),
  ('4e587c51-73ff-5ea6-a67b-be481e870144', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 20, 20, 'The angel of God said to him, "Take the meat and the unleavened cakes, and lay them on this rock, and pour out the broth." He did so.'),
  ('4cfc7bbd-a293-5265-a556-e20619fcb0c5', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 21, 21, 'Then the angel of Yahweh stretched out the end of the staff that was in his hand, and touched the meat and the unleavened cakes; and fire went up out of the rock, and consumed the meat and the unleavened cakes; and the angel of Yahweh departed out of his sight.'),
  ('1134ff7c-56d7-5d45-ab97-9730598461b2', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 22, 22, 'Gideon saw that he was the angel of Yahweh; and Gideon said, "Alas, Lord Yahweh! Because I have seen the angel of Yahweh face to face!"'),
  ('51122083-93fd-58ec-a193-10498fd5d061', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 23, 23, 'Yahweh said to him, "Peace be to you! Don''t be afraid. You shall not die."'),
  ('8651f746-8273-5151-a068-48a8dc1823f1', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 24, 24, 'Then Gideon built an altar there to Yahweh, and called it "Yahweh is Peace." To this day it is still in Ophrah of the Abiezrites.'),
  ('a700c59f-8ddc-545d-a688-95a1a54a9ff3', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 25, 25, 'It happened the same night, that Yahweh said to him, "Take your father''s bull, even the second bull seven years old, and throw down the altar of Baal that your father has, and cut down the Asherah that is by it;'),
  ('3c846a07-4f46-52f1-a29e-fc133cfe2ca2', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 26, 26, 'and build an altar to Yahweh your God on the top of this stronghold, in an orderly way, and take the second bull, and offer a burnt offering with the wood of the Asherah which you shall cut down."'),
  ('6bacc480-e1c2-5b1a-a771-3107cfacf3ac', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 27, 27, 'Then Gideon took ten men of his servants, and did as Yahweh had spoken to him: and it happened, because he feared his father''s household and the men of the city, so that he could not do it by day, that he did it by night.'),
  ('b56e262b-5796-58cb-aebd-a470a4b4ef70', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 28, 28, 'When the men of the city arose early in the morning, behold, the altar of Baal was broken down, and the Asherah was cut down that was by it, and the second bull was offered on the altar that was built.'),
  ('2b178cbc-7840-535c-af9e-79b6fafae815', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 29, 29, 'They said one to another, "Who has done this thing?" When they inquired and asked, they said, "Gideon the son of Joash has done this thing."'),
  ('5dbd8124-23c0-5695-ad7e-816dd57c8aba', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 30, 30, 'Then the men of the city said to Joash, "Bring out your son, that he may die, because he has broken down the altar of Baal, and because he has cut down the Asherah that was by it."'),
  ('828ddece-555b-5a2a-aaa4-2f9ad8b44299', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 31, 31, 'Joash said to all who stood against him, "Will you contend for Baal? Or will you save him? He who will contend for him, let him be put to death while [it is yet] morning. If he is a god, let him contend for himself, because someone has broken down his altar."'),
  ('18b36ed9-663e-5556-a76b-68bd24697d86', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 32, 32, 'Therefore on that day he named him Jerub-Baal, saying, "Let Baal contend against him, because he has broken down his altar."'),
  ('485988e3-8785-59bd-a6d7-acfc03a235ff', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 33, 33, 'Then all the Midianites and the Amalekites and the children of the east assembled themselves together; and they passed over, and encamped in the valley of Jezreel.'),
  ('1966a20e-e99b-5a3a-a495-f97102b9b936', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 34, 34, 'But the Spirit of Yahweh came on Gideon; and he blew a trumpet; and Abiezer was gathered together after him.'),
  ('230b6870-3121-554c-aca9-14eb6eebfba4', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 35, 35, 'He sent messengers throughout all Manasseh; and they also were gathered together after him: and he sent messengers to Asher, and to Zebulun, and to Naphtali; and they came up to meet them.'),
  ('8d4d57ff-1e3c-5962-ad4d-e50e5a4f37a5', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 36, 36, 'Gideon said to God, "If you will save Israel by my hand, as you have spoken,'),
  ('265cbb05-33ca-5875-a7d8-22cdd5fd39bb', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 37, 37, 'behold, I will put a fleece of wool on the threshing floor; if there be dew on the fleece only, and it be dry on all the ground, then shall I know that you will save Israel by my hand, as you have spoken."'),
  ('e3aa7664-fc6e-55ca-ab3b-71bd0876d434', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 38, 38, 'It was so; for he rose up early on the next day, and pressed the fleece together, and wrung the dew out of the fleece, a bowl full of water.'),
  ('ea1bd669-95fa-51e9-ad27-13b76b6d9f48', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 39, 39, 'Gideon said to God, "Don''t let your anger be kindled against me, and I will speak but this once. Please let me make a trial just this once with the fleece. Let it now be dry only on the fleece, and on all the ground let there be dew."'),
  ('230f40a3-9bbb-5529-a2ac-a4a1288e2b96', '4e024d82-e71a-57b6-a1e9-3d10578a7ded', NULL, 40, 40, 'God did so that night: for it was dry on the fleece only, and there was dew on all the ground.'),
  ('7173ad2e-6ad8-5505-a306-c4c1b31aae0b', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 1, 1, 'Then Jerubbaal, who is Gideon, and all the people who were with him, rose up early, and encamped beside the spring of Harod: and the camp of Midian was on the north side of them, by the hill of Moreh, in the valley.'),
  ('27edc860-3f6e-5b0b-aa68-9f3c7bb482d4', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 2, 2, 'Yahweh said to Gideon, "The people who are with you are too many for me to give the Midianites into their hand, lest Israel vaunt themselves against me, saying, ''My own hand has saved me.'''),
  ('2555f6d4-305f-539e-a07c-c792bac92c94', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 3, 3, 'Now therefore proclaim in the ears of the people, saying, ''Whoever is fearful and trembling, let him return and depart from Mount Gilead.''" Twenty-two thousand of the people returned, and ten thousand remained.'),
  ('d40c7a94-6c85-5592-aa02-e75303336896', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 4, 4, 'Yahweh said to Gideon, "The people are still too many. Bring them down to the water, and I will test them for you there. It shall be, that of whom I tell you, ''This shall go with you,'' the same shall go with you; and of whoever I tell you, ''This shall not go with you,'' the same shall not go."'),
  ('4f9d9fcf-41cd-5fe3-a0b0-84276fbc498f', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 5, 5, 'So he brought down the people to the water; and Yahweh said to Gideon, "Everyone who laps of the water with his tongue, like a dog laps, you shall set him by himself; likewise everyone who bows down on his knees to drink."'),
  ('33d4cc50-3641-5223-aac0-d0e0b2cac67a', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 6, 6, 'The number of those who lapped, putting their hand to their mouth, was three hundred men; but all the rest of the people bowed down on their knees to drink water.'),
  ('464792ee-7788-547d-a88b-bcb76cbfbbfd', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 7, 7, 'Yahweh said to Gideon, "By the three hundred men who lapped will I save you, and deliver the Midianites into your hand. Let all the other people go, each to his own place."'),
  ('248c3455-536a-5a05-a307-020f124d16eb', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 8, 8, 'So the people took food in their hand, and their trumpets; and he sent all the men of Israel every man to his tent, but retained the three hundred men: and the camp of Midian was beneath him in the valley.'),
  ('2ff80887-7d8f-5970-ae9b-976e9aca8761', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 9, 9, 'It happened the same night, that Yahweh said to him, "Arise, go down into the camp; for I have delivered it into your hand.'),
  ('95cc130a-52bd-5f8c-adc6-22753d3328ca', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 10, 10, 'But if you are afraid to go down, go with Purah your servant down to the camp:'),
  ('e630c533-59b8-5393-aae8-e5084c90729d', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 11, 11, 'and you shall hear what they say; and afterward your hands will be strengthened to go down into the camp." Then went he down with Purah his servant to the outermost part of the armed men who were in the camp.'),
  ('eb0759e0-4edc-5f06-abed-eb5769ed5f70', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 12, 12, 'The Midianites and the Amalekites and all the children of the east lay along in the valley like locusts for multitude; and their camels were without number, as the sand which is on the seashore for multitude.'),
  ('322501fa-de5d-53e8-a08a-5e9c731c2102', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 13, 13, 'When Gideon had come, behold, there was a man telling a dream to his fellow; and he said, "Behold, I dreamed a dream; and behold, a cake of barley bread tumbled into the camp of Midian, and came to the tent, and struck it so that it fell, and turned it upside down, so that the tent lay flat."'),
  ('ef998808-0a8e-5319-a907-41d4bb7b6b99', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 14, 14, 'His fellow answered, "This is nothing other than the sword of Gideon the son of Joash, a man of Israel. God has delivered Midian into his hand, with all the army."'),
  ('909f922a-778c-5cc6-adf4-86f7ab039b82', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 15, 15, 'It was so, when Gideon heard the telling of the dream, and its interpretation, that he worshiped; and he returned into the camp of Israel, and said, "Arise; for Yahweh has delivered the army of Midian into your hand!"'),
  ('d7655318-4be0-573c-aace-049bd736b4c2', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 16, 16, 'He divided the three hundred men into three companies, and he put into the hands of all of them trumpets, and empty pitchers, with torches within the pitchers.'),
  ('cb99bdc7-2d03-5565-ab42-49b1ef450a51', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 17, 17, 'He said to them, "Watch me, and do likewise. Behold, when I come to the outermost part of the camp, it shall be that, as I do, so you shall do.'),
  ('01271ec8-2b9a-50e7-ad26-bae3abbe804d', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 18, 18, 'When I blow the trumpet, I and all who are with me, then blow the trumpets also on every side of all the camp, and shout, ''For Yahweh and for Gideon!''"'),
  ('d9188587-d279-5fed-ae51-65c3504013ad', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 19, 19, 'So Gideon, and the hundred men who were with him, came to the outermost part of the camp in the beginning of the middle watch, when they had but newly set the watch: and they blew the trumpets, and broke in pieces the pitchers that were in their hands.'),
  ('cb56a16b-98ff-5c9c-aecd-4affab5b8306', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 20, 20, 'The three companies blew the trumpets, and broke the pitchers, and held the torches in their left hands, and the trumpets in their right hands with which to blow; and they shouted, "The sword of Yahweh and of Gideon!"'),
  ('c5fe8812-538a-5c53-a372-8bb1018317fb', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 21, 21, 'They stood every man in his place around the camp; and all the army ran; and they shouted, and put [them] to flight.'),
  ('0a8d9218-fcf6-5acd-a6da-f8b8e863ecce', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 22, 22, 'They blew the three hundred trumpets, and Yahweh set every man''s sword against his fellow, and against all the army; and the army fled as far as Beth Shittah toward Zererah, as far as the border of Abel Meholah, by Tabbath.'),
  ('6dbe4a7c-d7f8-5af5-a36b-6229adef68b8', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 23, 23, 'The men of Israel were gathered together out of Naphtali, and out of Asher, and out of all Manasseh, and pursued after Midian.'),
  ('c166cabb-9bd7-5cf3-ad88-eec4373a6bfa', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 24, 24, 'Gideon sent messengers throughout all the hill country of Ephraim, saying, "Come down against Midian, and take before them the waters, as far as Beth Barah, even the Jordan!" So all the men of Ephraim were gathered together, and took the waters as far as Beth Barah, even the Jordan.'),
  ('a67ce583-25af-585c-a4e3-efb045eed4ac', '2c92ba1d-5aee-555f-ac12-17ec69bb57fb', NULL, 25, 25, 'They took the two princes of Midian, Oreb and Zeeb; and they killed Oreb at the rock of Oreb, and Zeeb they killed at the winepress of Zeeb, and pursued Midian: and they brought the heads of Oreb and Zeeb to Gideon beyond the Jordan.'),
  ('424b0243-b472-5c17-af45-ff5fc45a01bf', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 1, 1, 'The men of Ephraim said to him, "Why have you treated us this way, that you didn''t call us, when you went to fight with Midian?" They rebuked him sharply.'),
  ('64da6acf-d0d2-5dc4-a1a5-a37a98771ecf', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 2, 2, 'He said to them, "What have I now done in comparison with you? Isn''t the gleaning of the grapes of Ephraim better than the vintage of Abiezer?'),
  ('f58626f0-6306-53fc-a3f3-d73dfbefd0b6', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 3, 3, 'God has delivered into your hand the princes of Midian, Oreb and Zeeb! What was I able to do in comparison with you?" Then their anger was abated toward him, when he had said that.'),
  ('f2615cf7-43ab-57c9-a34c-bea2f48ed8f4', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 4, 4, 'Gideon came to the Jordan, [and] passed over, he, and the three hundred men who were with him, faint, yet pursuing.'),
  ('6739b774-2022-5e57-aa4e-2e0f1840b0e8', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 5, 5, 'He said to the men of Succoth, "Please give loaves of bread to the people who follow me; for they are faint, and I am pursuing after Zebah and Zalmunna, the kings of Midian."'),
  ('fe312fc2-8aa0-53dd-a75d-edb4680f3a75', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 6, 6, 'The princes of Succoth said, "Are the hands of Zebah and Zalmunna now in your hand, that we should give bread to your army?"'),
  ('275e2317-20b9-5cbc-ab15-f8fd31fcdd11', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 7, 7, 'Gideon said, "Therefore when Yahweh has delivered Zebah and Zalmunna into my hand, then I will tear your flesh with the thorns of the wilderness and with briers."'),
  ('8411c4fd-7e33-5af3-a2f7-de2551c90f52', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 8, 8, 'He went up there to Penuel, and spoke to them in the same way; and the men of Penuel answered him as the men of Succoth had answered.'),
  ('322b84c8-bd79-5bc3-afee-0e0243cb3b9f', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 9, 9, 'He spoke also to the men of Penuel, saying, "When I come again in peace, I will break down this tower."'),
  ('0a9062f5-5b96-5bcf-a065-96ece57ef750', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 10, 10, 'Now Zebah and Zalmunna were in Karkor, and their armies with them, about fifteen thousand men, all who were left of all the army of the children of the east; for there fell one hundred twenty thousand men who drew sword.'),
  ('d52152ca-1e68-57bc-a834-83c0eaacdde9', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 11, 11, 'Gideon went up by the way of those who lived in tents on the east of Nobah and Jogbehah, and struck the army; for the army was secure.'),
  ('40c578ab-1f87-55ee-adbe-7fafc90400cf', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 12, 12, 'Zebah and Zalmunna fled; and he pursued after them; and he took the two kings of Midian, Zebah and Zalmunna, and confused all the army.'),
  ('f1950da9-871a-5214-a595-8ae81151fd97', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 13, 13, 'Gideon the son of Joash returned from the battle from the ascent of Heres.'),
  ('423f0d3a-7eda-5b6f-a9fc-344c02d860c0', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 14, 14, 'He caught a young man of the men of Succoth, and inquired of him: and he described for him the princes of Succoth, and its elders, seventy-seven men.'),
  ('afcb814d-fe1b-57a0-a1e0-bfb82ed0e1ea', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 15, 15, 'He came to the men of Succoth, and said, "See Zebah and Zalmunna, concerning whom you taunted me, saying, ''Are the hands of Zebah and Zalmunna now in your hand, that we should give bread to your men who are weary?''"'),
  ('465e9ec2-4027-54dc-a3cc-f8312eeb1ac7', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 16, 16, 'He took the elders of the city, and thorns of the wilderness and briers, and with them he taught the men of Succoth.'),
  ('113c7ccd-0011-579a-ac06-1ada8f2fc531', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 17, 17, 'He broke down the tower of Penuel, and killed the men of the city.'),
  ('d16b64eb-630a-5559-a1fa-fedce3820e70', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 18, 18, 'Then he said to Zebah and Zalmunna, "What kind of men were they whom you killed at Tabor?" They answered, "They were like you. Each one resembled the children of a king."'),
  ('3317b4f4-77c5-5ef8-a5c4-d6380609d4ec', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 19, 19, 'He said, "They were my brothers, the sons of my mother. As Yahweh lives, if you had saved them alive, I would not kill you."'),
  ('d1f3ef49-8461-5963-ab09-08d2ed16321f', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 20, 20, 'He said to Jether his firstborn, "Get up, and kill them!" But the youth didn''t draw his sword; for he was afraid, because he was yet a youth.'),
  ('8463f911-aae3-5402-ac1a-d51c33eb2ee4', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 21, 21, 'Then Zebah and Zalmunna said, "Rise and fall on us; for as the man is, so is his strength." Gideon arose, and killed Zebah and Zalmunna, and took the crescents that were on their camels'' necks.'),
  ('ca1fca1d-9ece-51f9-a75d-e35a3590510d', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 22, 22, 'Then the men of Israel said to Gideon, "Rule over us, both you, and your son, and your son''s son also; for you have saved us out of the hand of Midian."'),
  ('f6413be1-87be-5917-a769-cec9513e1cfe', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 23, 23, 'Gideon said to them, "I will not rule over you, neither shall my son rule over you. Yahweh shall rule over you."'),
  ('1601d841-0ca9-5142-a7c7-08e2829c16c6', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 24, 24, 'Gideon said to them, "I would make a request of you, that you would give me every man the earrings of his spoil." (For they had golden earrings, because they were Ishmaelites.)'),
  ('ec8ce343-f862-5d7e-a049-4726c2998642', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 25, 25, 'They answered, "We will willingly give them." They spread a garment, and every man threw the earrings of his spoil into it.'),
  ('a200560f-0a3f-51bc-abc3-d3cf3d2a3f17', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 26, 26, 'The weight of the golden earrings that he requested was one thousand and seven hundred [shekels] of gold, besides the crescents, and the pendants, and the purple clothing that was on the kings of Midian, and besides the chains that were about their camels'' necks.'),
  ('f31549af-b819-5f9b-a1e8-baad9d8d410a', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 27, 27, 'Gideon made an ephod of it, and put it in his city, even in Ophrah: and all Israel played the prostitute after it there; and it became a snare to Gideon, and to his house.'),
  ('71277c4f-c94a-5ca0-a7bc-43a466764292', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 28, 28, 'So Midian was subdued before the children of Israel, and they lifted up their heads no more. The land had rest forty years in the days of Gideon.'),
  ('1b10d63b-6870-565c-a753-e90cc62325d9', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 29, 29, 'Jerubbaal the son of Joash went and lived in his own house.'),
  ('3c8c44b7-c285-51db-a45b-f1c5750f4eeb', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 30, 30, 'Gideon had seventy sons conceived from his body; for he had many wives.'),
  ('bb88f38a-126f-53e0-a814-1f34d43f46f7', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 31, 31, 'His concubine who was in Shechem, she also bore him a son, and he named him Abimelech.'),
  ('387bf56e-1a66-5c83-a128-31199b4808b7', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 32, 32, 'Gideon the son of Joash died in a good old age, and was buried in the tomb of Joash his father, in Ophrah of the Abiezrites.'),
  ('8fe658f1-6c1c-5b0d-a281-a2047df07fd2', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 33, 33, 'It happened, as soon as Gideon was dead, that the children of Israel turned again, and played the prostitute after the Baals, and made Baal Berith their god.'),
  ('3a6b45ef-daf2-571f-a6f1-85ebadf765a4', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 34, 34, 'The children of Israel didn''t remember Yahweh their God, who had delivered them out of the hand of all their enemies on every side;'),
  ('aa00bbaf-a767-503d-adde-1f02254073d3', '528bb37d-de24-5969-a306-6da3bc3727e7', NULL, 35, 35, 'neither did they show kindness to the house of Jerubbaal, [who is] Gideon, according to all the goodness which he had shown to Israel.'),
  ('3d37d50b-6e13-546d-a2f0-90ae6e16023b', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 1, 1, 'Abimelech the son of Jerubbaal went to Shechem to his mother''s brothers, and spoke with them, and with all the family of the house of his mother''s father, saying,'),
  ('2f06d6f9-a820-5a80-a9c5-5c10e8d0cb72', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 2, 2, '"Please speak in the ears of all the men of Shechem, ''Is it better for you that all the sons of Jerubbaal, who are seventy persons, rule over you, or that one rule over you?'' Remember also that I am your bone and your flesh."'),
  ('faacc4c3-0b42-544a-ac96-817183b46c2f', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 3, 3, 'His mother''s brothers spoke of him in the ears of all the men of Shechem all these words: and their hearts inclined to follow Abimelech; for they said, "He is our brother."'),
  ('64f50f76-d6c9-50ac-adbe-4f7059e4ca9e', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 4, 4, 'They gave him seventy [pieces] of silver out of the house of Baal Berith, with which Abimelech hired vain and light fellows, who followed him.'),
  ('f9ec4216-a008-5f96-a342-bab3c57c06e4', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 5, 5, 'He went to his father''s house at Ophrah, and killed his brothers the sons of Jerubbaal, being seventy persons, on one stone: but Jotham the youngest son of Jerubbaal was left; for he hid himself.'),
  ('c3f2b9e9-3ac2-540d-a51b-a5a5281b6e54', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 6, 6, 'All the men of Shechem assembled themselves together, and all the house of Millo, and went and made Abimelech king, by the oak of the pillar that was in Shechem.'),
  ('3ab7cbcd-f49c-52ff-a649-83938533fc6e', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 7, 7, 'When they told it to Jotham, he went and stood on the top of Mount Gerizim, and lifted up his voice, and cried, and said to them, "Listen to me, you men of Shechem, that God may listen to you.'),
  ('e294b8a5-db0b-5552-a653-99670478a853', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 8, 8, 'The trees went forth on a time to anoint a king over them; and they said to the olive tree, ''Reign over us.'''),
  ('cba7c6f8-8065-5065-ab7f-425b7f3ded00', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 9, 9, '"But the olive tree said to them, ''Should I leave my fatness, with which by me they honor God and man, and go to wave back and forth over the trees?'''),
  ('5d5f38df-e660-5f36-ad32-3dafd636501f', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 10, 10, '"The trees said to the fig tree, ''Come and reign over us.'''),
  ('582eedae-37b9-5009-a94a-224d26e49f5a', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 11, 11, '"But the fig tree said to them, ''Should I leave my sweetness, and my good fruit, and go to wave back and forth over the trees?'''),
  ('c471cb8a-b97f-55b3-a30a-b53b81c774ef', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 12, 12, '"The trees said to the vine, ''Come and reign over us.'''),
  ('55fa819e-0d9c-5237-ab38-44e8d5ff01d8', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 13, 13, '"The vine said to them, ''Should I leave my new wine, which cheers God and man, and go to wave back and forth over the trees?'''),
  ('f7c0b0fc-93b7-533f-af9f-5fe2892a53ae', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 14, 14, '"Then all the trees said to the bramble, ''Come and reign over us.'''),
  ('94c1d292-47b0-5c99-ad1d-49bcb4ce2617', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 15, 15, '"The bramble said to the trees, ''If in truth you anoint me king over you, then come and take refuge in my shade; and if not, let fire come out of the bramble, and devour the cedars of Lebanon.'''),
  ('74c58830-7c7d-57f7-a40a-294c91c45eb4', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 16, 16, '"Now therefore, if you have dealt truly and righteously, in that you have made Abimelech king, and if you have dealt well with Jerubbaal and his house, and have done to him according to the deserving of his hands'),
  ('29de128d-57b9-50ba-a811-3f3aec71aca6', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 17, 17, '(for my father fought for you, and risked his life, and delivered you out of the hand of Midian:'),
  ('c518aef8-1b5e-5fa0-a144-7b4991648661', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 18, 18, 'and you have risen up against my father''s house this day, and have slain his sons, seventy persons, on one stone, and have made Abimelech, the son of his female servant, king over the men of Shechem, because he is your brother);'),
  ('f618f19e-f03b-5501-a4a3-9e27e17424dd', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 19, 19, 'if you then have dealt truly and righteously with Jerubbaal and with his house this day, then rejoice in Abimelech, and let him also rejoice in you:'),
  ('bded1aaf-c62d-5983-a38f-12db682fe374', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 20, 20, 'but if not, let fire come out from Abimelech, and devour the men of Shechem, and the house of Millo; and let fire come out from the men of Shechem, and from the house of Millo, and devour Abimelech."'),
  ('664a8f4b-1a48-573c-a972-4ff670e144ce', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 21, 21, 'Jotham ran away, and fled, and went to Beer, and lived there, for fear of Abimelech his brother.'),
  ('f003f6b5-b880-56cd-a05f-fbe4264f782e', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 22, 22, 'Abimelech was prince over Israel three years.'),
  ('a5417d18-6492-5c85-a0c2-114863285d0e', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 23, 23, 'God sent an evil spirit between Abimelech and the men of Shechem; and the men of Shechem dealt treacherously with Abimelech:'),
  ('e3471772-5dd5-5e47-ab70-8081360db7ef', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 24, 24, 'that the violence done to the seventy sons of Jerubbaal might come, and that their blood might be laid on Abimelech their brother, who killed them, and on the men of Shechem, who strengthened his hands to kill his brothers.'),
  ('8b6582b8-121c-554e-a467-f74a568509fb', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 25, 25, 'The men of Shechem set an ambush for him on the tops of the mountains, and they robbed all who came along that way by them: and it was told Abimelech.'),
  ('7c6cf7e2-3d77-5a34-a485-14ec84c31628', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 26, 26, 'Gaal the son of Ebed came with his brothers, and went over to Shechem; and the men of Shechem put their trust in him.'),
  ('4f6147ea-047d-59ed-abd5-d4660b7e3cce', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 27, 27, 'They went out into the field, and gathered their vineyards, and trod [the grapes], and held festival, and went into the house of their god, and did eat and drink, and cursed Abimelech.'),
  ('c440d411-b3f6-5bbc-a039-d2589fef2822', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 28, 28, 'Gaal the son of Ebed said, "Who is Abimelech, and who is Shechem, that we should serve him? Isn''t he the son of Jerubbaal? and Zebul his officer? Serve the men of Hamor the father of Shechem: but why should we serve him?'),
  ('566b19c4-400a-5a3e-a549-5e2abdb4ea46', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 29, 29, 'Would that this people were under my hand! Then I would remove Abimelech." He said to Abimelech, "Increase your army, and come out!"'),
  ('bcf981fe-e14d-5f01-ab7e-04cdce8a9d44', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 30, 30, 'When Zebul the ruler of the city heard the words of Gaal the son of Ebed, his anger was kindled.'),
  ('630ab826-2485-577b-ae44-eec92a128941', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 31, 31, 'He sent messengers to Abimelech craftily, saying, "Behold, Gaal the son of Ebed and his brothers are come to Shechem; and behold, they constrain the city [to take part] against you.'),
  ('befc0f90-5584-5678-a210-ec97a37477bd', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 32, 32, 'Now therefore, go up by night, you and the people who are with you, and lie in wait in the field:'),
  ('cba98acf-346f-568a-ac75-e919bfa4e8ca', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 33, 33, 'and it shall be, that in the morning, as soon as the sun is up, you shall rise early, and rush on the city; and behold, when he and the people who are with him come out against you, then may you do to them as you shall find occasion."'),
  ('60aa4e24-ebeb-52c5-a348-7347e965f3e9', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 34, 34, 'Abimelech rose up, and all the people who were with him, by night, and they laid wait against Shechem in four companies.'),
  ('e44aba1e-57ba-5221-a937-416d9c1aaec9', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 35, 35, 'Gaal the son of Ebed went out, and stood in the entrance of the gate of the city: and Abimelech rose up, and the people who were with him, from the ambush.'),
  ('fffd8958-bc96-5402-a3e8-c8b6267ae257', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 36, 36, 'When Gaal saw the people, he said to Zebul, "Behold, people are coming down from the tops of the mountains." Zebul said to him, "You see the shadow of the mountains as if they were men."'),
  ('2ebd89a0-0043-5a85-a5de-e112b69c8ab8', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 37, 37, 'Gaal spoke again and said, "Behold, people are coming down by the middle of the land, and one company comes by the way of the oak of Meonenim."'),
  ('d94aecc8-d63f-5b60-abf4-5bb54b049af4', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 38, 38, 'Then Zebul said to him, "Now where is your mouth, that you said, ''Who is Abimelech, that we should serve him?'' Isn''t this the people that you have despised? Please go out now and fight with them."'),
  ('6a00d643-12d1-5bf4-a143-bc35927115b0', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 39, 39, 'Gaal went out before the men of Shechem, and fought with Abimelech.'),
  ('e7d1c4e2-d430-5b5a-a976-57fd84e7f5df', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 40, 40, 'Abimelech chased him, and he fled before him, and many fell wounded, even to the entrance of the gate.'),
  ('184ec57b-9e34-51b0-a62a-f7fb7c4a604e', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 41, 41, 'Abimelech lived at Arumah: and Zebul drove out Gaal and his brothers, that they should not dwell in Shechem.'),
  ('e62b80d5-538a-5faf-afd7-ca1fcbb77640', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 42, 42, 'It happened on the next day, that the people went out into the field; and they told Abimelech.'),
  ('204cdb4d-30a4-510f-ae3c-c0565cf9cc59', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 43, 43, 'He took the people, and divided them into three companies, and laid wait in the field; and he looked, and behold, the people came forth out of the city; He rose up against them, and struck them.'),
  ('dd459b26-13f8-5442-a68b-c2b5537d8f15', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 44, 44, 'Abimelech, and the companies that were with him, rushed forward, and stood in the entrance of the gate of the city: and the two companies rushed on all who were in the field, and struck them.'),
  ('e02d99d3-c551-5dba-a3d2-f43c6aaa9464', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 45, 45, 'Abimelech fought against the city all that day; and he took the city, and killed the people who were therein: and he beat down the city, and sowed it with salt.'),
  ('3a293020-891e-5e9d-ac83-7706f48740ac', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 46, 46, 'When all the men of the tower of Shechem heard of it, they entered into the stronghold of the house of Elberith.'),
  ('fc82298f-88d2-58cb-a3bf-eaed50d7cfbc', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 47, 47, 'It was told Abimelech that all the men of the tower of Shechem were gathered together.'),
  ('b10e150b-99d8-53f4-a4af-3f365a12168f', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 48, 48, 'Abimelech went up to Mount Zalmon, he and all the people who were with him; and Abimelech took an axe in his hand, and cut down a bough from the trees, and took it up, and laid it on his shoulder: and he said to the people who were with him, "What you have seen me do, make haste, and do as I have done!"'),
  ('d6e2dfcb-7af3-5be7-a57c-2f5600af0333', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 49, 49, 'All the people likewise each cut down his bough, and followed Abimelech, and put them at the base of the stronghold, and set the stronghold on fire on them; so that all the people of the tower of Shechem died also, about a thousand men and women.'),
  ('7c70c3c8-be8f-51ee-a193-93394c11ac39', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 50, 50, 'Then went Abimelech to Thebez, and encamped against Thebez, and took it.'),
  ('d05b9f8f-b662-5a74-ab23-387a62c42168', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 51, 51, 'But there was a strong tower within the city, and there fled all the men and women, and all they of the city, and shut themselves in, and went up to the roof of the tower.'),
  ('16a763f6-8b1c-5eed-aead-db40f338f345', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 52, 52, 'Abimelech came to the tower, and fought against it, and drew near to the door of the tower to burn it with fire.'),
  ('764e1d07-3746-5678-a38f-62f7bd50ccf3', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 53, 53, 'A certain woman cast an upper millstone on Abimelech''s head, and broke his skull.'),
  ('d6b7ae29-2232-552e-af14-46cdc4fdab60', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 54, 54, 'Then he called hastily to the young man his armor bearer, and said to him, "Draw your sword, and kill me, that men not say of me, ''A woman killed him.'' His young man thrust him through, and he died."'),
  ('4766164a-2fab-5ce9-a990-a70a8a178078', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 55, 55, 'When the men of Israel saw that Abimelech was dead, they departed every man to his place.'),
  ('af98292d-b588-5280-ad59-8c31bc4b8cfe', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 56, 56, 'Thus God requited the wickedness of Abimelech, which he did to his father, in killing his seventy brothers;'),
  ('ead50eec-8290-5f37-ab6a-f699f32d6eb8', '052b5d84-47fa-51c9-ab2e-5545ad6cd8ab', NULL, 57, 57, 'and all the wickedness of the men of Shechem did God requite on their heads: and on them came the curse of Jotham the son of Jerubbaal.'),
  ('77f1d901-6fe8-5d9e-a0b9-afc4cce0f209', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 1, 1, 'After Abimelech there arose to save Israel Tola the son of Puah, the son of Dodo, a man of Issachar; and he lived in Shamir in the hill country of Ephraim.'),
  ('8775753e-1c8f-5145-a058-b78becc94bc1', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 2, 2, 'He judged Israel twenty-three years, and died, and was buried in Shamir.'),
  ('a2a0dc61-2e15-58be-a260-a659fa9f1587', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 3, 3, 'After him arose Jair, the Gileadite; and he judged Israel twenty-two years.'),
  ('1acd7f31-9315-5039-a2de-1c6743cb5410', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 4, 4, 'He had thirty sons who rode on thirty donkey colts, and they had thirty cities, which are called Havvoth Jair to this day, which are in the land of Gilead.'),
  ('c17cb5b2-8d2e-585e-a946-04bb4bd52f31', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 5, 5, 'Jair died, and was buried in Kamon.'),
  ('6fe46daf-4589-5827-a097-83ee89e0b5f3', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 6, 6, 'The children of Israel again did that which was evil in the sight of Yahweh, and served the Baals, and the Ashtaroth, and the gods of Syria, and the gods of Sidon, and the gods of Moab, and the gods of the children of Ammon, and the gods of the Philistines; and they forsook Yahweh, and didn''t serve him.'),
  ('06b82b20-04df-5152-a69f-9d5804b8dbbf', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 7, 7, 'The anger of Yahweh was kindled against Israel, and he sold them into the hand of the Philistines, and into the hand of the children of Ammon.'),
  ('ba24d65c-b91d-5782-a39a-4680cc21ea63', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 8, 8, 'They troubled and oppressed the children of Israel that year: eighteen years [oppressed they] all the children of Israel that were beyond the Jordan in the land of the Amorites, which is in Gilead.'),
  ('fdc3be0f-661e-5a97-aaf4-f887e0dd39f3', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 9, 9, 'The children of Ammon passed over the Jordan to fight also against Judah, and against Benjamin, and against the house of Ephraim; so that Israel was very distressed.'),
  ('68c03825-08b1-5e76-ab20-8af4b8cba850', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 10, 10, 'The children of Israel cried to Yahweh, saying, "We have sinned against you, even because we have forsaken our God, and have served the Baals."'),
  ('fd18248f-dce0-5fea-a5bd-68cc2b8b3347', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 11, 11, 'Yahweh said to the children of Israel, "Didn''t I save you from the Egyptians, and from the Amorites, from the children of Ammon, and from the Philistines?'),
  ('f59035f2-d378-58b9-ad8f-8e94ce6c8f50', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 12, 12, 'The Sidonians also, and the Amalekites, and the Maonites, did oppress you; and you cried to me, and I saved you out of their hand.'),
  ('f9c46089-e78a-5796-a6e2-af3ea3378daa', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 13, 13, 'Yet you have forsaken me, and served other gods: therefore I will save you no more.'),
  ('91d2ece5-dbdd-5357-aa99-2df8228d0f0f', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 14, 14, 'Go and cry to the gods which you have chosen. Let them save you in the time of your distress!"'),
  ('7264a3d9-9fa2-51b2-a3e5-e3a2cf227138', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 15, 15, 'The children of Israel said to Yahweh, "We have sinned: do you to us whatever seems good to you; only deliver us, please, this day."'),
  ('c30c3a62-5b96-5cc4-afbe-1f459c067942', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 16, 16, 'They put away the foreign gods from among them, and served Yahweh; and his soul was grieved for the misery of Israel.'),
  ('42fd4b6e-77fd-5f7c-a408-dd9f92ae3d2f', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 17, 17, 'Then the children of Ammon were gathered together, and encamped in Gilead. The children of Israel assembled themselves together, and encamped in Mizpah.'),
  ('7db17734-99e7-549e-aba6-6c1c0efe5018', 'abe62862-d8e8-5011-abd9-70470cb22000', NULL, 18, 18, 'The people, the princes of Gilead, said one to another, "What man is he who will begin to fight against the children of Ammon? He shall be head over all the inhabitants of Gilead."'),
  ('5a74cc96-73c1-54d6-a316-33a0887c9a44', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 1, 1, 'Now Jephthah the Gileadite was a mighty man of valor, and he was the son of a prostitute: and Gilead became the father of Jephthah.'),
  ('cf2dcfa2-bd96-5660-a5d3-7603f1c1d39b', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 2, 2, 'Gilead''s wife bore him sons; and when his wife''s sons grew up, they drove out Jephthah, and said to him, "You shall not inherit in our father''s house; for you are the son of another woman."'),
  ('1982e770-8c9f-52dd-ace9-70dbeaaa7791', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 3, 3, 'Then Jephthah fled from his brothers, and lived in the land of Tob: and there were gathered vain fellows to Jephthah, and they went out with him.'),
  ('bc5e06e3-f6ac-5161-a1e4-d68913835b14', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 4, 4, 'It happened after a while, that the children of Ammon made war against Israel.'),
  ('11be94a7-d7d5-596e-a02f-057acc5d2e36', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 5, 5, 'It was so, that when the children of Ammon made war against Israel, the elders of Gilead went to get Jephthah out of the land of Tob;'),
  ('6234cf92-7ab4-5e7e-a041-557f7a0b899f', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 6, 6, 'and they said to Jephthah, "Come and be our chief, that we may fight with the children of Ammon."'),
  ('3d99772e-07ca-5c34-a837-e97fea5627ad', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 7, 7, 'Jephthah said to the elders of Gilead, "Didn''t you hate me, and drive me out of my father''s house? Why have you come to me now when you are in distress?"'),
  ('3b6a52b0-d948-51d3-aefc-d044cff9f9ed', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 8, 8, 'The elders of Gilead said to Jephthah, "Therefore we have turned again to you now, that you may go with us, and fight with the children of Ammon; and you shall be our head over all the inhabitants of Gilead."'),
  ('d9b69974-e33b-5845-a2c9-d9e6bf80a3d1', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 9, 9, 'Jephthah said to the elders of Gilead, "If you bring me home again to fight with the children of Ammon, and Yahweh deliver them before me, shall I be your head?"'),
  ('575ef817-0539-50d9-afe5-a98e73ea910d', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 10, 10, 'The elders of Gilead said to Jephthah, "Yahweh shall be witness between us; surely according to your word so will we do."'),
  ('e90f16b7-b219-5922-addf-8b0379f644e7', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 11, 11, 'Then Jephthah went with the elders of Gilead, and the people made him head and chief over them: and Jephthah spoke all his words before Yahweh in Mizpah.'),
  ('de9271bd-86f6-5056-aead-6e1b284a12cf', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 12, 12, 'Jephthah sent messengers to the king of the children of Ammon, saying, "What have you to do with me, that you have come to me to fight against my land?"'),
  ('97e7cd3d-4675-5b4e-a97b-9034f9c6defc', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 13, 13, 'The king of the children of Ammon answered to the messengers of Jephthah, "Because Israel took away my land, when he came up out of Egypt, from the Arnon even to the Jabbok, and to the Jordan: now therefore restore those [lands] again peaceably."'),
  ('d8c6db39-0bfc-5963-a40f-c225ff9e6862', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 14, 14, 'Jephthah sent messengers again to the king of the children of Ammon;'),
  ('2c9310e4-2862-561b-adfb-eabad660302d', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 15, 15, 'and he said to him, "Thus says Jephthah: Israel didn''t take away the land of Moab, nor the land of the children of Ammon,'),
  ('a51f5476-a2e3-5177-ab0d-6f554a290d7f', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 16, 16, 'but when they came up from Egypt, and Israel went through the wilderness to the Red Sea, and came to Kadesh;'),
  ('77a6b1cb-e0da-5af1-aa33-4e1663c136fd', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 17, 17, 'then Israel sent messengers to the king of Edom, saying, ''Please let me pass through your land;'' but the king of Edom didn''t listen. In the same way, he sent to the king of Moab; but he would not: and Israel stayed in Kadesh.'),
  ('362b8951-3833-51a2-ab8f-2d7d31c3b57b', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 18, 18, 'Then they went through the wilderness, and went around the land of Edom, and the land of Moab, and came by the east side of the land of Moab, and they encamped on the other side of the Arnon; but they didn''t come within the border of Moab, for the Arnon was the border of Moab.'),
  ('415acab7-540a-5f7c-aa10-1ae1630a351c', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 19, 19, 'Israel sent messengers to Sihon king of the Amorites, the king of Heshbon; and Israel said to him, ''Please let us pass through your land to my place.'''),
  ('5e1a268a-5486-5555-ac0b-1ffaaa88be6f', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 20, 20, 'But Sihon didn''t trust Israel to pass through his border; but Sihon gathered all his people together, and encamped in Jahaz, and fought against Israel.'),
  ('650f252a-be87-5c57-ab11-892574f063ca', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 21, 21, 'Yahweh, the God of Israel, delivered Sihon and all his people into the hand of Israel, and they struck them: so Israel possessed all the land of the Amorites, the inhabitants of that country.'),
  ('82a3a417-5752-54ff-a2dd-530a96ece595', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 22, 22, 'They possessed all the border of the Amorites, from the Arnon even to the Jabbok, and from the wilderness even to the Jordan.'),
  ('2f51b5dc-034d-5a13-a17b-65d9572770a6', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 23, 23, 'So now Yahweh, the God of Israel, has dispossessed the Amorites from before his people Israel, and should you possess them?'),
  ('0871cf47-9902-5505-a8f3-dc3db76a243e', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 24, 24, 'Won''t you possess that which Chemosh your god gives you to possess? So whoever Yahweh our God has dispossessed from before us, them will we possess.'),
  ('baa1c8ad-f248-56ec-ae94-9cc466029eb8', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 25, 25, 'Now are you anything better than Balak the son of Zippor, king of Moab? Did he ever strive against Israel, or did he ever fight against them?'),
  ('060ce77b-06b3-5a78-a4c6-b0f2866cafec', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 26, 26, 'While Israel lived in Heshbon and its towns, and in Aroer and its towns, and in all the cities that are along by the side of the Arnon, three hundred years; why didn''t you recover them within that time?'),
  ('b5d66bf7-0712-5a6b-a9cc-2b0dfba8c946', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 27, 27, 'I therefore have not sinned against you, but you do me wrong to war against me. Yahweh, the Judge, be judge this day between the children of Israel and the children of Ammon."'),
  ('5ec7e32c-f72d-54c7-abbd-22f96f77e675', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 28, 28, 'However the king of the children of Ammon didn''t listen to the words of Jephthah which he sent him.'),
  ('e9529b8e-b85f-5e9f-a3ca-01d074c5f5f7', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 29, 29, 'Then the Spirit of Yahweh came on Jephthah, and he passed over Gilead and Manasseh, and passed over Mizpeh of Gilead, and from Mizpeh of Gilead he passed over to the children of Ammon.'),
  ('3a02f901-5aaa-55eb-a4d7-c974f5dd29ad', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 30, 30, 'Jephthah vowed a vow to Yahweh, and said, "If you will indeed deliver the children of Ammon into my hand,'),
  ('1d8a63c4-144a-5872-adb4-0150f865799b', 'b0daf5cc-31c6-5c77-abbb-a7f223c4ec0b', NULL, 31, 31, 'then it shall be, that whatever comes forth from the doors of my house to meet me, when I return in peace from the children of Ammon, it shall be Yahweh''s, and I will offer it up for a burnt offering."')
